quests[4786] = { id = 4786, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die fertig gestellte Robe", description = "Jetzt schneidere ich die Robe für Euch. Es dauert nur einen Augenblick. Geht nicht weit fort, ja?", completion = "Es ist vollbracht, {name}. Hier, bitte sehr. Tragt sie mit Stolz.\n\nIhr habt hart dafür gearbeitet und ich sehe große Taten in Eurer Zukunft. Denkt daran: Um sich der Verderbnis zu erwehren, die unseren Weg begleitet, bedarf es eines starken Willens und großer, innerer Stärke. Solange Ihr Herr Eures Willens seid, wird Euch großer Erfolg beschieden sein.", objectives = "Wartet, bis Menara Voidrender Eure Robe fertig gestellt hat, und sprecht dann noch einmal mit ihr.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[4787] = { id = 4787, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das uralte Ei", description = "Mosh'arus Prophezeiung spricht von einem uralten Ei. Es ist ein Relikt aus einer Zeit, als die Trolle noch über riesige Reiche herrschten, und es hat die Kraft, die Essenz von Hakkar zu binden. Möglicherweise ist es das einzige Mittel, um unsere Welt vor diesem Bösen zu schützen.\n\nBringt mir das uralte Ei, {name}. Man sagt, dass es tief verborgen in Jintha'Alor im Hinterland liegt, in einer Höhle hinter dem Amphitheater am obersten Punkt der Stadt.", progress = "Habt Ihr das uralte Ei? Ich spüre, wie sich große Mächte regen, und ich fürchte, dass die Zeit knapp wird.", completion = "Ah, Ihr habt das Ei! Ich verneige mich vor Euch, {name}. An Eure Kraft und Euren Mut wird man sich noch lang erinnern.", objectives = "Bringt das uralte Ei zu Yeh'kinya nach Tanaris.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[4788] = { id = 4788, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die letzten Schrifttafeln", description = "Während ich die dritte und vierte Schrifttafel von Mosh'aru überprüfe, müsst ihr die fünfte und sechste finden! Es wird nicht einfach sein, da sie in den Händen der Trolle des Gluthauerstamms auf der Blackrockspitze sind. Die Spitze ist ein dunkler Berg aus Feuer zwischen der brennenden Steppe und der sengenden Schlucht.\n\nViel Glück, {name}. Die Blackrockspitze ist kein Ort für anständige Leute ...", progress = "Wart Ihr bei der Spitze, {name}? Habt Ihr die fünfte und sechste Schrifttafel?", completion = "Unglaublich! Ihr habt sie gefunden! Ihr seid ein wahrer Held, {name}!\n\nDas ist eine gute Sache, denn ich habe die Schrifttafeln gelesen, die Ihr mir zuvor gebracht habt, und nach dem, was ich herausgefunden habe... tja, da werden wir wohl einen Helden brauchen, der aufhält, was kommt...", objectives = "Bringt Ausgrabungsleiter Ironboot in Tanaris die fünfte und sechste Schrifttafel von Mosh'aru.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[4801] = { id = 4801, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "E'ko der Frostsäbler", progress = "In Winterspring da werdeta gegen große Katzens kämpfen müssen, das sin' de Frostsäblers. Diese Biesties sin' unglaublich schnell un' gerissen. Wenn Ihr auch so schnell wie 'n Frostsäbler sein wollt, dann bringt mir das E'ko, das Ihr von ihnen kriegt.\n\nNich' vergessen: Ihr müsst 'n Behälter von Mau'ari in Eurem Inventar haben, wenn Ihr Euch E'ko schnappen wollt.", completion = "Mau'ari kann für {name} 'n Juju machen... Benutzt 'n Behälter von Mau'ari, um das Juju auf Euch oder Eure Verbündeten zu wirken." }
quests[4802] = { id = 4802, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "E'ko der Winterfelle", progress = "In Winterspring da werdeta gegen fehlgeleitete Kreaturens kämpfen, das sin' de Winterfellfurbolgse. Weil ihr Anführer das so wollt', ham die unglaubliche Kraft gekriegt. Wenn Ihr auch so stark wie 'n Winterfell sein wollt, dann bringt mir das E'ko, das Ihr von ihnen kriegt.\n\nNich' vergessen: Ihr müsst 'n Behälter von Mau'ari in Eurem Inventar haben, wenn Ihr Euch E'ko schnappen wollt.", completion = "Mau'ari kann für {name} 'n Juju machen... Benutzt 'n Behälter von Mau'ari, um das Juju auf Euch oder Eure Verbündeten zu wirken." }
quests[4803] = { id = 4803, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "E'ko eines Splitterzahns", progress = "In Winterspring, da sin' große Bärens mit extrem dicken Bälgens. Diese Splitterzahnbären kriegen davon so viel Schutz, dasse unheimlich viel Zeugs widerstehen könn'. Wenn Ihr gegen Feuer auch so widerstandsfähig sein wollt, dann bringt mir das E'ko, das Ihr von 'nem Splitterzahn kriegt.\n\nNich' vergessen: Ihr müsst 'n Behälter von Mau'ari in Eurem Inventar haben, wenn Ihr Euch E'ko schnappen wollt.", completion = "Mau'ari kann für {name} 'n Juju machen... Benutzt 'n Behälter von Mau'ari, um das Juju auf Euch oder Eure Verbündeten zu wirken." }
quests[4804] = { id = 4804, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "E'ko der Eiswindschimären", progress = "In Winterspring, da müssta gegen große fliegende Kreaturens kämpfen, das sin' de Eiswindschimären. Diese Biesties könn' Frostmagie wirken. Wenn Ihr gegen Frost auch so widerstandsfähig sein wollt, dann bringt mir das E'ko, das Ihr von 'ner Eiswindschimäre kriegt.\n\nNich' vergessen: Ihr müsst 'n Behälter von Mau'ari in Eurem Inventar haben, wenn Ihr Euch E'ko schnappen wollt.", completion = "Mau'ari kann für {name} 'n Juju machen... Benutzt 'n Behälter von Mau'ari, um das Juju auf Euch oder Eure Verbündeten zu wirken." }
quests[4805] = { id = 4805, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "E'ko der Eisdistelyetis", progress = "In Winterspring, da müssta gegen große Kreaturens kämpfen, das sin' de Eisdistelyetis. Diese Viecher bewegen sich nur langsam, aber se könn' Dank dem dicken Fell 'ne Menge Prügel einstecken. Wenn Ihr auch so gut wie die Angriffen ausweich'n wollt, dann bringt mir das E'ko, das Ihr von ihnen kriegt.\n\nNich' vergessen: Ihr müsst 'n Behälter von Mau'ari in Eurem Inventar haben, wenn Ihr Euch E'ko schnappen wollt.", completion = "Mau'ari kann für {name} 'n Juju machen... Benutzt 'n Behälter von Mau'ari, um das Juju auf Euch oder Eure Verbündeten zu wirken." }
quests[4806] = { id = 4806, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "E'ko der Frosthagelriesen", progress = "In Winterspring habta gegen de großen Eisriesens gekämpft, de Frosthagel. Die verlassen sich auf rohe Gewalt und Kraft. Wenn Ihr auch so stark wie 'n Frosthagelriese sein wollt, dann bringt mir das E'ko, das Ihr von ihnen kriegt.\n\nNich' vergessen: Ihr müsst 'n Behälter von Mau'ari in Eurem Inventar haben, wenn Ihr Euch E'ko schnappen wollt.", completion = "Mau'ari kann für {name} 'n Juju machen... Benutzt 'n Behälter von Mau'ari, um das Juju auf Euch oder Eure Verbündeten zu wirken." }
quests[4807] = { id = 4807, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "E'ko der Wildekin", progress = "In Winterspring, da müssta gegen Kreaturens kämpfen, die ham anscheinend angeborene magische Fertigkeitens. Diese Wildekinses könn' echt starke Magie anwenden. Wenn Ihr Euren Intellekt erweitern wollt, dann bringt mir das E'ko von allen denen Eulenbiesters, die Ihr dort findet.\n\nNich' vergessen: Ihr müsst 'n Behälter von Mau'ari in Eurem Inventar haben, wenn Ihr Euch E'ko schnappen wollt.", completion = "Mau'ari kann für {name} 'n Juju machen... Benutzt 'n Behälter von Mau'ari, um das Juju auf Euch oder Eure Verbündeten zu wirken." }
quests[4808] = { id = 4808, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Felnok Steelspring", description = "Ich habe noch eine weitere kleine Bitte an Euch.\n\nMeine anfänglichen Studien bezüglich der Essenz, die Ihr gesammelt habt, haben ergeben, dass es wohl möglich ist, Großdrachenwelpen-Eier einzufrieren und so zu konservieren! Ich möchte diese Theorie überprüfen, aber zuerst benötige ich speziell angefertigte Komponenten der Ingenieurskunst. Mein Kollege Felnok Steelspring kann sie herstellen.\n\nHier, bringt Felnok diesen Brief. Darin steht, was ich benötige. Ihr findet Felnok in Winterspring in der Stadt Everlook.", sourceObjective = "Gebt Felnok SteelspringTinkees Brief.", progress = "Ganz schön kalt hier oben! Hoffentlich habt Ihr mir eine Decke mitgebracht!", completion = "Das ist doch keine Decke! Aber was haben wir denn hier? Einen Brief von Tinkee? Ich frage mich, was so wichtig ist, dass sie mir schreibt...\n\nAh, sie befasst sich in der brennenden Steppe mit ihren Studien. Eine gute Idee - das ist ein guter Fundort für Drachkin. Oh, aber seht doch nur! Hier steht, dass sie ein paar Teile für ein Gerät benötigt, das sie bauen möchte. Tja, da bin dann wohl ich gefragt, was?", sourceObjectiveStatus = "unverified-source-field" }
quests[4809] = { id = 4809, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hörner der Eiswindschimären", description = "Ich habe fast alles, was Tinkee benötigt, aber mir fehlt eine wichtige Komponente, und das sind Eiswindschimärenhörner. Die Hörner der Eiswindschimären von Winterspring sind eine konzentrierte Kältequelle, aber man kann nur makellose, unbeschädigte Hörner verwenden! Ich brauche ein paar davon, um Tinkees Auftrag zu erfüllen.\n\nBringt mir unbeschädigte Hörner der Eiswindschimären, dann schnüre ich ein Päckchen für Tinkee zusammen.", progress = "Habt Ihr die Hörner der Eiswindschimären, {name}?", completion = "Das sind wirklich Prachtexemplare. Sie sind eiskalt! Ich ziehe mir schnell ein Paar Handschuhe an und dann packe ich sie zu den anderen Dingen, die Tinkee braucht...", objectives = "Bringt Felnok Steelspring 8 unbeschädigte Hörner einer Eiswindschimäre.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[4810] = { id = 4810, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr zu Tinkee", description = "Gut, alles ist bereit und verpackt und transportfertig! Viel Glück auf Eurer Reise und richtet Tinkee aus, dass sie mir was schuldet!", progress = "{name}! Habt Ihr mit Felnok gesprochen? Habt Ihr die Komponenten, die ich benötige?", completion = "Ihr habt sie! Großartig! Ich mache mich sogleich ans Werk! Tausendmal Dank, {name}!\n\nIhr wart mir eine so große Hilfe, dass ich Euch bestimmt einmal wieder für noch wichtigere Aufgaben brauchen könnte...", objectives = "Bringt Tinkee Steamboil in der brennenden Steppe Felnoks Päckchen.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[4811] = { id = 4811, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der rote Kristall", description = "Im Osten streifen immer mehr feindliche Moonkin umher. Man dachte einst, dass sie sanftmütige, fast mystische Kreaturen wären. Wenn auch viele ihnen weiterhin Ehrfurcht entgegenbringen, zwingt mich die Sicherheit Auberdines, die Sache realistischer zu sehen.\n\nIch habe Berichte erhalten, dass es die Moonkin zu einem großen roten Kristall an der östlichen Bergkette von Dunkelküste zieht. Niemand weiß, was dieser Kristall ist oder ob er wirklich existiert. Ich möchte, dass Ihr ihn dort sucht und mir meldet, was Ihr vorgefunden habt.", completion = "Der Kristall existiert also, {name}? Faszinierend... Ihr habt Eure Aufgabe gut ausgeführt; das war gute Arbeit!\n\nWas genau ist dieser Kristall? Das ist nur eine einzelne Frage in einem Meer von Fragen. Eine weitere Frage, die sich stellt, ist, warum die Moonkin von diesem Objekt angezogen werden... Ist der Kristall von Natur aus gut oder birgt er einen düsteren Zweck?\n\nIch habe viele weitere Fragen, aber wir werden diesen Kristall näher untersuchen müssen, um einige Antworten zu erhalten.", objectives = "Reist von Auberdine nach Osten und sucht nach einem großen, roten Kristall entlang der östlichen Bergkette von Dunkelküste. Informiert Schildwache Glynda Nal'Shea in Auberdine über Eure Erkenntnisse.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[4812] = { id = 4812, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wenn das Wasser fließt", description = "Benutzt diese leere Phiole und füllt hier in Auberdine Mondbrunnenwasser hinein. Solch mächtige Magie sollte einen Hinweis auf die Zusammensetzung des Kristalls liefern. Zu diesem Zweck gießt Ihr etwas Flüssigkeit über den Kristall; alles Weitere sollte sich dann von selbst ergeben.\n\nWenn ich auch nicht erwarte, dass Euch etwas Böses zustoßen könnte, möchte ich dennoch, dass Ihr vorsichtig seid. Über uns im Osten liegt der Teufelswald; falls dieser Kristall mit jenem Ort verbunden ist, wie ich es vermute, könnte sich das als sehr gefährlich erweisen.", progress = "Gegen die Baumkulisse von Dunkelküste wirkt der Kristall sehr fremdartig. Ihr meint, ein sehr leises Summen aus seinem tiefsten Inneren zu vernehmen.", completion = "Ihr habt den mysteriösen Kristall erneut erreicht. Sogleich entfernt Ihr den Verschluss der Röhre mit Mondbrunnenwasser und gießt den Inhalt vorsichtig über dem Kristall aus. Als das Wasser über das Kristallgitter läuft, seht Ihr, wie seine undurchsichtige Oberfläche durchsichtig wird...", objectives = "Füllt die leere Wasserröhre am Mondbrunnen von Auberdine und untersucht dann den roten Kristall an der östlichen Bergkette von Dunkelküste.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[4813] = { id = 4813, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Fragmente im Inneren", description = "Das Mondbrunnenwasser hat enthüllt, dass im Inneren des Kristalls einige kleine Knochenfragmente sowie ein Teil eines Kieferknochens eingebettet sind. Der Kieferknochen scheint menschlich zu sein, aber um Klarheit darüber zu gewinnen, müsste man den Kristall aufbrechen - eine Leistung, die sogar für die stärkste Magie schier unmöglich erscheint.\n\nDa Ihr die gestellte Aufgabe erfüllt habt, bleibt nur noch, Schildwache Glynda Nal'Shea in Auberdine Bericht zu erstatten.", completion = "Tja, es scheint, dass wir jetzt zwar mehr über den Kristall wissen, dafür aber vor noch mehr unbeantworteten Fragen stehen!\n\nIch werde die Informationen, die Ihr enthüllt habt, zum Rat hier in Auberdine bringen. Vielleicht weiß er, was bezüglich dieses Kristalls zu tun ist. Das heißt, vorausgesetzt, dass es etwas zu tun gibt; vorerst befindet sich die Bedrohung weit genug im Osten, sodass sie für uns keine Gefahr bedeutet.\n\nUnd was Euch angeht, bitte nehmt dies. Seht es als eine Belohnung für gut geleistete Arbeit an, {name}.", objectives = "Informiert Schildwache Glynda Nal'Shea in Auberdine über Eure Erkenntnisse.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[4821] = { id = 4821, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fremdartiges Ei", description = "Es wurde ein Gerücht über ein fremdartiges Ei hier in Tausend Nadeln in Umlauf gebracht. Diejenigen, die dieses Ei gesehen haben, konnten aber nicht nahe genug herankommen, um es ausführlich zu untersuchen. Schlangen bewachen das Ei, als wäre es eines ihrer eigenen.\n\nIch möchte, dass Ihr dieses fremdartige Ei sucht und es mir bringt, damit ich es untersuchen kann. Berichten zufolge soll sich das Ei in einem Schlangenbau befinden, aber es gibt mehrere Schlangenbaue entlang des Fußes der Klippenwand südlich und nordöstlich des Freiwindpostens.", progress = "Ich muss mehr über dieses mysteriöse Ei herausfinden. Wer weiß, was einmal daraus schlüpfen wird.", completion = "Ja, endlich... das mysteriöse Ei wurde mir endlich gebracht. Dann lasst mich mal einen Blick darauf werfen... Was...! Was ist das...?", objectives = "Bringt Hagar Lightninghoof am Freiwindposten das fremdartige Ei.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[4822] = { id = 4822, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lecker Eis", description = "EISCREME! Oh, kannst du mir bitte, bitte, bitte, etwas Eiscreme besorgen? Am liebsten mag ich Erdbeere und es gibt einfach kein besseres Erdbeereis als das von Skippi. Das ist mein liebstes Eis auf der ganzen Welt!\n\nFrüher gab es das immer auf der Rennstrecke in der schimmernden Ebene, aber ich habe mal gehört, dass man es jetzt auch in der Stadt kaufen kann. Kriege ich bitte eins? Bitte? Am liebsten Skippis Eiscreme.", sourceObjective = "Besorgt für Euren Schützling etwas Erdbeereis. Der Kleine scheint die Marke 'Skippis Eiscreme' zu bevorzugen.", progress = "Ich wünschte sie würden mehr als nur Erdbeereis herstellen, aber Gott sei Dank ist Erdbeere meine Lieblingssorte.", completion = "Mmmmmmmmm! Ich liebe Erdbeereis! Wenn Skippi und Gunni eines können, dann ist das Erdbeereis machen!\n\nVielen Dank, {name} - Das ist die beste Süßigkeit seit langem!", sourceObjectiveStatus = "unverified-source-field" }
quests[4841] = { id = 4841, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Befriedung der Zentauren", description = "{name}, ich flehe Euch an, diese Zentauren zur Strecke zu bringen. Sie sollen den Zorn unserer Rache spüren. Greift das Zentaurenlager im Norden des Freiwindpostens an! Lasst den Zorn Eure Hand führen!", progress = "Kommt schon, {name}, ich weiß, dass Ihr Euren Anteil noch nicht erlegt habt. Bringt sie zur Strecke, dann bekommt Ihr eine Belohnung als Zeichen meiner Dankbarkeit.", completion = "Das ist für Euch, {name}, als Zeichen meiner Dankbarkeit.", objectives = "Tötet 12 Späher der Galak, 10 Zänker der Galak sowie 6 Windjäger der Galak und kehrt dann zu Klippenbehüter Longhorn am Freiwindposten zurück.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[4842] = { id = 4842, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sonderbare Quellen", description = "Also mal ehrlich, es gibt hier in Winterspring zwar keine Vulkane, aber ich glaube, dass es ein paar viel gefährlichere Ursachen für diese heißen Quellen gibt...\n\nTja, Ihr möchtet Euch das bestimmt lieber mit eigenen Augen ansehen. Ihr müsst dazu ganz Winterspring durchqueren und ganz nach Süden reisen. Wenn die Luft irgendwie stickig und schwül wird und sich der Himmel verdunkelt, habt Ihr gefunden, was ich für die Ursache der heißen Quellen halte.\n\nSeht es Euch an. Ich bin sicher, dass Ihr mit einer Menge Fragen zurückkehren werdet.", progress = "Das Wasser der Quellen scheint ein paar höchst eigenartige Eigenschaften zu haben... Ich bin mir immer noch nicht sicher, was das zu bedeuten hat...", completion = "Ja, die Dämonen dort in der flüsternden Schlucht... ich glaube, dass es ihre Anwesenheit ist, die das Land auf diese Weise beeinflusst. Ich werde weiter die hiesigen heißen Quellen beobachten und zusehen, ob ich etwas mehr herausfinden kann.\n\nAn Eurer Stelle würde ich allerdings warten, bis ich ein bisschen stärker wäre, bevor ich mich weiter in die flüsternden Schlucht hineinwagen würde.", objectives = "Befolgt Donova Snowdens Anweisungen und meldet Euch dann wieder bei ihr.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[4861] = { id = 4861, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wütende Wildekin", description = "Hallo, <Bursche/Mädchen>! Ein paar blutrünstige Wildekin haben mich aus meinem Lager im südlichen Winterspring vertrieben! Nun, ich schätze, ich bin irgendetwas zu nahe gekommen, das die Wildekin bewachen.\n\nIch hab es gerade noch geschafft, mit heiler Haut davonzukommen, aber ich fürchte, einer meiner Freunde hatte nicht so viel Glück. Würde es Euch wohl etwas ausmachen, Euch der Gefahr durch die Wildekin zu stellen und zum Lager zu gehen? Ich brauche unbedingt meine Vorräte und hätte auch gern das Amulett zurück, das ich gestern an der Ausgrabungsstätte zu Tage gefördert habe.", completion = "Inmitten der zerstörten Habseligkeiten im Lager steht eine schwer beschädigte Kiste...", objectives = "Findet Jaron Stoneshapers ruiniertes Lager samt dessen Vorräte im südlichen Winterspring.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[4862] = { id = 4862, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Be-Öh-Es-Eh", description = "Ob Ihr es glaubt oder nicht, da draußen gibt es Leute, die gutes Geld selbst für die übelsten der abgerichteten Bestien ausgeben würden!\n\nIch würde ja Bijou zur Spitze schicken, um ein paar dieser Spitzenspinnen-Eier zu sammeln, aber ich habe seit Wochen nichts mehr von ihr gehört. Vielleicht könnt Ihr mir helfen?\n\nIch sag Euch was, {name}. Geht zur Blackrockspitze und sammelt ein paar Spitzenspinnen-Eier für mich. Bringt sie mir, dann werde ich Euch nicht nur etwas Bargeld geben, sondern auch eines der Viecher für Euch abrichten!", progress = "Sind das da Spinnen-Eier in Eurem Säckel oder freut Ihr Euch einfach nur, mich zu sehen?", completion = "Was für ein Haufen! Ich meine, seht Euch nur all diese Eier an! Die sollten eine ordentliche Menge Gold einbringen.\n\nWie versprochen, hier habt Ihr Euer eigenes kleines Tierchen. Lasst Euch nur nicht beißen!", objectives = "Reist zur Blackrockspitze und sammelt 15 Spitzenspinnen-Eier für Kibler.\n\nLogischerweise müsstet Ihr diese Eier in der Nähe von Spinnen finden.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[4863] = { id = 4863, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wütende Wildekin", description = "Ihr seht Euch um und könnt nichts entdecken, was Jaron wohl noch brauchen könnte. Ihr stellt jedoch fest, dass die Kiste, die Ihr fandet, aufgebrochen wurde, als ob es die Wildekin darauf abgesehen hatten...\n\nAls Ihr nach Osten blickt, erkennt Ihr den vagen Umriss eines zurückgelassenen Wagens. Vielleicht findet Ihr Jarons Sachen ja dort. Nachsehen kann nicht schaden.", completion = "Ihr nähert Euch dem Wagen. Es scheint dort nichts weiter für Jaron zu geben. Als Ihr jedoch zu Boden blickt, fallen Euch ein paar Kisten auf, die unbeschädigt aussehen, aber halb im Schnee verborgen sind.", objectives = "Sucht Jaron Stoneshapers zerstörten Wagen.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[4864] = { id = 4864, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wütende Wildekin", description = "Nachdem Ihr den Inhalt des Kastens inspiziert habt, befindet Ihr, dass Jaron die Werkzeuge und anderen Gegenstände darin sicher gebrauchen könnte. Von dem Amulett fehlt jedoch jede Spur.\n\nDie Wildekin scheinen die Landstriche nördlich und östlich von hier zu bewohnen, also beschließt Ihr, dass Euer nächster Schritt sein wird, die Kreaturen aufzustöbern und das Amulett von ihnen einzufordern.", progress = "Aye... Was gibt's Neues?", completion = "Tja, das hatte ich befürchtet zu hören. Hab ich mir doch gedacht, dass diese wahnsinnigen Bestien meine ganzen Habseligkeiten zerstört haben...\n\nAber Ihr habt meine Werkzeuge gefunden und, was noch wichtiger ist, das Amulett! Ich frage mich, warum die Wildekin diesen Gegenstand so heftigst verteidigt haben... Wie auch immer, ich werde es mir zweimal überlegen, ihnen noch einmal in die Quere zu geraten!", objectives = "Klaubt Jarons Vorräte aus dem Schnee und sucht dann die Wildekin, die das Amulett gestohlen haben, von dem Jaron gesprochen hatte.\n\nBringt Jaron Stoneshaper in der Lodge in Winterspring dessen Vorräte und das blaugefiederte Amulett.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[4865] = { id = 4865, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wilde Schlange", description = "Wenn ich es nicht mit eigenen Augen gesehen hätte, würde ich es nie für möglich gehalten haben. Die Rache kam nach Tausend Nadeln!\n\n<Hagar wischt sich den Schweiß von der Stirn.>\n\n{name}, Ihr müsst Euch beeilen! Geht sofort los und sucht Motega Firemane auf. Ihr findet ihn im Weißgipfelposten nordwestlich des Freiwindpostens, entlang der Straße. Er wird wissen, was zu tun ist!", completion = "Rache! Also ist die Legende von Arikara doch wahr. Das ist in der Tat ein Problem, um das wir uns unverzüglich kümmern müssen.", objectives = "Berichtet Motega Firemane von Euren Entdeckungen.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[4866] = { id = 4866, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Muttermilch", description = "Das dürfte eines der stärksten Gifte der Welt sein, {race}!\n\nIch habe bei meinen Ausflügen zur Spitze immer wieder gehört, wie die Leute von Blackrock davon sprachen, wie tödlich es sei. Sie nennen es 'Muttermilch', benannt nach Mutter Glimmernetz, der großen, grausamen Spinne in der Skitterwebhöhle.\n\nAlso, das müsst Ihr mir besorgen: eine frische Probe dieser Milch, die durch EURE Adern fließt. Mir einfach nur die Giftdrüse zu bringen, wäre nicht genug! Bringt sie dazu, Euch zu vergiften, und kommt dann zu mir zurück!\n\nDann... kann ich Euch melken!\n\n<Reibt sich voller Vorfreude die Hände.>", progress = "<Der struppige John kneift Euch.>", completion = "Das wird das beste Bier aller Zeiten.\n\nHe, was habt Ihr denn gedacht, wofür ich das benutze? Als Gift oder so was???\n\nVerrückte Kinder...", objectives = "Ihr findet Mutter Glimmernetz im Herzen der Blackrockspitze. Kämpft mit ihr und bringt sie dazu, Euch zu vergiften. Es kann gut sein, dass Ihr sie sogar töten müsst. Kehrt zum struppigen John zurück, sobald Ihr vergiftet seid, damit er Euch 'melken' kann.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[4867] = { id = 4867, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Urok Schreckensbote", description = "Argh! Das Sprechen fällt schwer!\n\nNehmt diese Notiz! Holt mir mein Mojo.", progress = "Ah! Habt Ihr mein Mojo?", completion = "Aha! Ich kann bereits fühlen, wie meine Macht zu mir zurückkehrt. Und meine Gedanken werden nicht mehr von Uroks Fluch gestört.\n\nDanke, {name}! Bescheidenheit ist unter meiner Würde, aber ich muss Eure Hilfe anerkennen.\n\nUnd ich wünsche Euch Glück auf Euren Reisen durch Blackrockspitze. Ihr seid ein Narr zu denken, Ihr könntet es bis an die Spitze schaffen, aber Euer Mut steht außer Frage.", objectives = "Lest Waroshs Rolle. Bringt Waroshs Mojo zu Warosh.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[4881] = { id = 4881, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auftragsmordplan", description = "Der Tauren Kanati Greycloud war so dreist, in Tausend Nadeln ein Jägerlager aufzuschlagen. Wir müssen ihn töten, damit dieses Jägerlager und alle, die ihm möglicherweise folgen, verschwinden. Wir werden uns dem kleinen Posten südwestlich des großen Aufzugs nähern.", completion = "Die wollen mich töten? Ich werde ihnen zeigen, wie ein Tauren kämpft!", objectives = "Warnt Kanati Greycloud am Weißgipfelposten, dass man vorhat, ihn zu töten.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[4882] = { id = 4882, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geheimnisse bewachen", description = "Ihr seid Euch unsicher bezüglich der Bedeutung der Halskette, die vom Hals des gerade erschlagenen Wildekin stammt. Sie glüht hell, verblasst und wird wieder hell.\n\nTrull Failbane kann Euch vielleicht mehr darüber sagen, da er über sehr großes Wissen über die Wildekin verfügt. Vielleicht solltet Ihr ihn darüber befragen.", progress = "Meldet Ihr Euch für einen weiteren Auftrag?", completion = "Eine bedeutende Entdeckung?", objectives = "Bringt Trull Failbane beim Blutgiftposten das blaugefiederte Amulett.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[4883] = { id = 4883, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geheimnisse bewahren", description = "Auch wenn ich viel über die Eulenbestien weiß, die Ihr in Winterspring erledigt habt, bin ich in der Magie, die sie wirken, nicht wirklich bewandert. Aber ich glaube, dass ich jemanden kenne, der die Kette untersuchen und Euch sagen könnte, was es ist.\n\nNara Wildmane in Thunder Bluff ist eine Expertin auf diesem Gebiet; trefft Euch mit ihr. Viel Glück, {name}.", progress = "Wie kann ich Euch helfen, {name}?", completion = "Die Energie dieser Halskette, {name}. Ich glaube, dass sie nur eine Quelle hat.\n\n\n\nDie Wildekin, nun fehlgeleitet und verwirrt, waren einst nicht so. Sie hatten einst einen Zweck und wurden geleitet, um zu dienen. Die Nachtelfengöttin Elune hat diese Kreaturen geschaffen, um ihre hochheiligsten Gebiete zu bewachen.\n\nDiese Tatsache mag nicht sehr wertvoll erscheinen, aber ich dränge Euch, weiter zu forschen.\n\nIhr werdet es irgendwann erfahren. Danke, dass Ihr mir dies gebracht habt, {name}.", objectives = "Bringt Nara Wildmane das blaugefiederte Amulett.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[4901] = { id = 4901, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wächter des Altars", description = "Ganz oben auf dem Grat liegt das, was ich für einen Altar der Göttin Elune halte. Soweit ich das sagen kann, müssen wir in jeder Höhle fünf Fackeln anzünden. Dann können wir den eigentlichen Altar erreichen.\n\nIch habe einige der Zauberformeln übersetzt, die in den Stein der alten Ruinen von Kel'Theril geritzt sind. Meiner Meinung nach sind sie der Schlüssel, mit dem man den Altar freigeben kann. Ich brauche Eure Hilfe dabei, alle Fackeln anzuzünden, während ich den Zauber rezitiere.\n\nWenn wir Erfolg haben, könnt Ihr Erelas unseren Fund melden!", completion = "Habt Ihr Ranshalla getroffen?", objectives = "Schützt Ranshalla, während sie versucht, den Altar von Elune wieder zu aktivieren. Berichtet Erelas Ambersky in Rut'theran von Eurem Fund.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[4902] = { id = 4902, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wildekin von Elune", description = "Das ist faszinierend!\n\nIch habe mich immer gefragt, was die Wahrheit ist... Nun, Ihr müsst dieses Wissen auf alle Fälle teilen! Geht sofort zum Erzdruiden Fandral Staghelm. Ihr werdet ihn in Darnassus im Zirkel des Cenarius antreffen. Erklärt ihm, was passiert ist, genau so wie Ihr es mir erzählt habt. Ich bin sicher, es wird ihn ebenso interessieren!\n\nDas sind wichtige Informationen, {name}!", completion = "Nur heraus damit, sagt mir, warum Ihr hier seid.\n\nOh, ja? Hmm. Nun ja.\n\nDanke, dass Ihr damit direkt zu mir gekommen seid. Es ist immer am besten, sich direkt an die Spitze zu wenden... Aber... Ja. Die Druiden des Zirkels des Cenarius wissen schon eine ganze Weile von den Wildekin. Dass sie Tiere von Elune und dazu auserwählt sind, die hochheiligsten Orte zu bewachen.\n\nWenn das also auch keine wirklichen Neuigkeiten waren, so muss ich Euch doch für Eure Anstrengungen loben. Hier, nehmt dies... es ist etwas, das mir für eine solche Tat angemessen erscheint.", objectives = "Sprecht mit Erzdruide Fandral Staghelm in Darnassus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[4903] = { id = 4903, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Befehl des Kriegsherrn", description = "Auf Befehl von Kriegsherr Goretooth müssen die nachfolgenden Bewohner der Blackrockspitze eliminiert werden:\n\nDie aufgeblasene Bedrohung, Hochlord Omokk.\n\nDer grausame und erbarmungslose Troll Kriegsmeister Voone.\n\nOberanführer Wyrmthalak, Zuchtmeister der geringen Stadt.\n\nDes Weiteren müsst Ihr alle wichtigen Dokumente zurückbringen, die Ihr möglicherweise findet.\n\nSeid erfolgreich und macht Euch Ehre.\n\nVersagt und seid vergessen.", progress = "<Kriegsherr Goretooth salutiert vor Euch.>", completion = "<Kriegsherr Goretooths mattgrüne Haut wird für einen Augenblick kreideweiß.>", objectives = "Tötet Hochlord Omokk, Kriegsmeister Voone und Oberanführer Wyrmthalak. Findet die wichtigen Blackrockdokumente. Kehrt zum Kriegsherrn Goretooth nach Kargath zurück, sobald Ihr diese Mission erledigt habt.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[4904] = { id = 4904, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Endlich frei", description = "Arnak glaubt, dass wir heiraten werden… aber nachdem ich seinen Antrag abgelehnt hatte, kehrte er in der Nacht zurück und entführte mich. Mein Bruder wollte ihn aufhalten, aber Arnak war einfach zu stark. Er... er tötete meinen Bruder, dann brachte er mich hierher. Mein armer Bruder...\n\n{name}, würdet Ihr mich wohl vom Düsterwolkengipfel hinab geleiten? Bitte... ich muss zu Thalia zurückkehren! Sie macht sich bestimmt große Sorgen um mich.", completion = "Ich danke Euch, {name}. Tief im Inneren wusste ich, dass sie ihren Weg zu mir zurückfinden würde. Sie hat mir von Eurem Mut berichtet und wie Ihr bei ihrer Flucht geholfen habt. Diese Gegenstände gehörten ihrem Bruder. Ich weiß, dass sie wollte, dass Ihr sie bekommt.", objectives = "Geleitet Lakota Windsong vom Düsterwolkengipfel hinab und sprecht dann im Freiwindposten mit Thalia Amberhide.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[4906] = { id = 4906, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weitere Verderbnis", description = "Ein weiterer Satyrstützpunkt unter der Leitung des grausamen Xavaric bedroht den Teufelswald im Norden. Die elenden Verräter und Schwindler zehren von der Verderbnis der im Teufelswald heimischen Kreaturen.\n\nXavathras und seine Diener waren nur Teil eines größeren Plans - ein Mondbrunnen sollte verderbt werden und Xavaric sollte dann die Beute bekommen.\n\nDa Xavathras jetzt beseitigt ist, solltet Ihr diese Aufgabe beenden, {name}. Geht nach Norden und besiegt Xavaric.", completion = "Vielen Dank für Eure Mühen, {name}. Möge Elune Euch beschützen und auf Eurem weiteren Weg leiten.", objectives = "Eridan Bluewind im Teufelswald möchte, dass Ihr Xavaric sowie 8 Jadefeuerhöllenrufer, 8 Jadefeuerverräter und 8 Jadefeuerschwindler tötet. Kehrt zu Eridan zurück, sobald Ihr die Aufgabe erfüllt habt.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[4907] = { id = 4907, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tinkee Steamboil", description = "Hallo, {name}. Erinnert Ihr Euch an Tinkee Steamboil? Tja, sie erinnert sich jedenfalls an Euch! Sie schickte mir eine Nachricht, dass ich nach Euch Ausschau halten soll... sie braucht nämlich nochmals Eure Hilfe. Ich glaube, es hat was mit ihren Drachenstudien zu tun.\n\nIhr solltet mit ihr sprechen. Sie ist in der brennenden Steppe, beim Flammenkamm.", completion = "Felnok hatte Recht! Ich brauche wirklich Hilfe und dieses Mal... wird es wirklich gefährlich werden.\n\nSeid Ihr bereit?", objectives = "Sprecht mit Tinkee Steamboil.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[4921] = { id = 4921, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In der Schlacht vermisst", description = "Wir wurden getrennt, als wir in einem kleinen Taurenlager gemeinsam kämpften - sie hat drei Borstennacken im Alleingang bezwungen. Aber dann waren sie plötzlich in der Überzahl. Ich lockte ein paar fort, dann sah ich, wie sie von Neuankömmlingen überwältigt wurde. Rasend vor Zorn stellte ich mich meinen Feinden, aber da es derer so viele waren, ging ich schon bald zu Boden.\n\nIch kam im Zelt eines Taurendruiden zu mir, der meine Wunden versorgte - er kam zufällig die Goldstraße entlang, als ich fiel.\n\nBitte, {class}, sucht nach einem Lebenszeichen von meiner Frau.", completion = "Ich verstehe. Ich danke Euch, {class}.", objectives = "Sucht Mankriks Frau und kehrt dann zu ihm nach Crossroads zurück.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[4941] = { id = 4941, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eitriggs Weisheit", description = "Rend lebt?\n\nUnmöglich!\n\nEr soll doch schon vor Jahrzehnten getötet worden sein.\n\nBittet Etrigg, seine Weisheit mit Euch zu teilen, {name}. Niemand kennt die Blackrock besser als er, und wenn es wahr ist, was hier geschrieben steht, muss Etrigg davon in Kenntnis gesetzt werden. Niemandem sollte das Recht auf Vergeltung versagt werden.\n\nIhr findet ihn in Orgrimmar.\n\nWenn Ihr mit Etrigg gesprochen habt, beratet Euch mit dem Kriegshäuptling, um von ihm zu erfahren, was er bezüglich dieses Problems zu unternehmen gedenkt.", progress = "Seht Ihr nicht, dass ich nicht gestört werden will?", completion = "<Thrall scheint ob der Nachrichten, die Ihr bringt, bestürzt zu sein.>", objectives = "Sprecht mit Etrigg in Orgrimmar. Wenn Ihr die Angelegenheit mit Etrigg besprochen habt, bittet Thrall um Rat.\n\nIhr erinnert Euch, dass Ihr Etrigg in Thralls Gemächern gesehen habt.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[4961] = { id = 4961, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Säuberung der Kugel von Orahil", description = "Ah, eine Beschwörerkugel - sie muss die Quelle der Besudelung sein. Wir müssen erst den Dämon darin exorzieren, wenn Ihr sie benutzen wollt. Das ist ein Klacks für mich.\n\nIhr habt die schwere Aufgabe. Ihr müsst den Dämon töten, sobald ich ihn freigesetzt habe.\n\nUnd Ihr müsst Euch beeilen. Wenn Ihr zu lange braucht, kehrt er in die Kugel zurück und wir müssen von vorn anfangen!\n\nAlso macht Euch bereit, {name}. Bereitet Eure stärksten Zauber vor, habt Eure Tränke parat und holt einen Freund, wenn Ihr einen habt. Denn das hier wird nicht angenehm.", completion = "Sehr schön, {name}! Diese Lektion wird der Dämon nicht so schnell vergessen. Ihr habt bislang große Stärke und Können gezeigt. Jetzt solltet Ihr wohl mit Eurer gesäuberten Kugel zu Menara zurückkehren, um sie sinnvoll einzusetzen.\n\nViel Glück, {class}. Vielleicht kreuzen sich unsere Wege wieder einmal.", objectives = "Tötet den Dämon der Kugel und sprecht dann mit Tabetha.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[4962] = { id = 4962, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Splitter eines Teufelshundes", description = "Ihr seid also entschlossen, die Seele eines Teufelshundes zu fangen, gut.\n\nNehmt diesen Rubin - mit ihm könnt Ihr die Seele der Kreatur einfangen. Er funktioniert auf ähnliche Weise wie die Zauber, die Ihr bereits kennt: Wenn die Kreatur dem Tode nahe ist, benutzt den Edelstein, er sollte dann den Rest für Euch erledigen.\n\nIch schlage vor, dass Ihr nach Desolace geht und versucht, dort eines Teufelshundes habhaft zu werden. Die sollten geeignet sein.\n\nWenn Ihr Erfolg hattet, bringt den gefangenen Geist und Euren Rubin zu Menara.", progress = "Ja, {name}? Wofür habt Ihr Euch entschieden? Was soll es sein? Höllenbestie oder Teufelshund?\n\nEs ist eine persönliche Entscheidung, die Aufschluss über Eure Stärken und Schwächen bietet. Es kommt durchaus vor, dass {class} ihre bestehenden Fähigkeiten intensivieren, statt solche, die ihnen noch fehlen, aufzubauen. Manchmal ist die Taktik, einen Feind einfach kräftemäßig zu überwältigen, ebenso wirkungsvoll, wie danach zu trachten, ein ausgeglichenerer Zauberer zu werden.", completion = "Ah, der Geist eines Teufelshundes. Gut gemacht, {name}.\n\nWenn ich sowohl den Geist als auch die gesäuberte Kugel habe, werde ich beides miteinander für Euch verbinden... aber erst dann.", objectives = "Nehmt den Felhas-Rubin und benutzt ihn bei einem der Teufelshunde von Desolace. Wenn Ihr Erfolg hattet, bringt Menara Voidrender im Brachland den eingekerkerten Teufelshundgeist und den Felhas-Rubin.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[4963] = { id = 4963, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Splitter einer Höllenbestie", description = "Ihr seid also entschlossen, die Seele einer Höllenbestie zu fangen, gut.\n\nNehmt diesen Smaragd - mit ihm könnt Ihr die Seele der Kreatur einfangen. Er funktioniert auf ähnliche Weise wie die Zauber, die Ihr bereits kennt: Wenn die Kreatur dem Tode nahe ist, benutzt den Edelstein, er sollte dann den Rest für Euch erledigen.\n\nIch schlage vor, dass Ihr nach Desolace geht und versucht, dort einer Höllenbestie habhaft zu werden. Die sollten geeignet sein.\n\nWenn Ihr Erfolg hattet, bringt den gefangenen Geist und Euren Smaragd zu Menara.", progress = "Ja, {name}? Wofür habt Ihr Euch entschieden? Was soll es sein? Höllenbestie oder Teufelshund?\n\nEs ist eine persönliche Entscheidung, die Aufschluss über Eure Stärken und Schwächen bietet. Es kommt durchaus vor, dass {class} ihre bestehenden Fähigkeiten intensivieren, statt solche, die ihnen noch fehlen, aufzubauen. Manchmal ist die Taktik, einen Feind einfach kräftemäßig zu überwältigen, ebenso wirkungsvoll, wie danach zu trachten, ein ausgeglichenerer Zauberer zu werden.", completion = "Ah, der Geist einer Höllenbestie. Gut gemacht, {name}.\n\nWenn ich sowohl den Geist als auch die gesäuberte Kugel habe, werde ich beides miteinander für Euch verbinden... aber erst dann.", objectives = "Nehmt den Infus-Smaragd und benutzt ihn bei einer der Höllenbestien von Desolace. Wenn Ihr Erfolg hattet, bringt Menara Voidrender im Brachland den eingekerkerten Höllenbestiengeist und den Infus-Smaragd.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[4964] = { id = 4964, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die fertig gestellte Kugel von Dar'Orahil", description = "Ich werde sofort mit der Arbeit an Eurer Kugel beginnen und Euren neuen Dämon darin einschließen. Wenn ich damit fertig bin, könnt Ihr entscheiden, ob Ihr ihn lieber in Form eines Stabs oder einer Kugel hättet. Ich fand es schon immer wichtig, dafür zu sorgen, dass jeder Hexenmeister die richtige Waffe bekommt ... Ich wüsste nicht, warum ich jetzt mit dieser Praxis aufhören sollte.", completion = "Es ist vollbracht, {name}. Sagt mir, was Ihr lieber hättet: einen Stab, den Ihr mit beiden Händen führen müsstet, oder eine Kugel, sodass Ihr gleichzeitig noch einen Dolch oder ein Schwert als Waffe führen könnt.\n\nDass Ihr einen Teufelshund besiegt habt, war eine große Leistung. Ich bin mir sicher, dass dieser Gegenstand Euch in derZukunft gute Dienste leisten wird. Übt weiter fleißig Eure Künste, {name}. Ich brenne darauf, bald mehr von Euren Heldentaten zu hören.", objectives = "Wartet, bis Menara Voidrender die Kugel von Dar'Orahil fertig gestellt hat, und sprecht dann noch einmal mit ihr.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[4965] = { id = 4965, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wissen der Kugel von Orahil", description = "Schön, schön, schön... Es ist eine Freude zu sehen, wie Eure Macht wächst, {name}. Ich würde sagen, dass Ihr bald bereit seid, im Brachland mit Menara Voidrender zu sprechen. Falls Ihr noch nie mit ihr gesprochen habt, dann lasst mich Euch sagen, dass ich wohl keinen zweiten Experten wie sie kenne, der so geschickt im Anfertigen von Gegenständen - insbesondere Kugeln - ist, in denen man sogar einen Dämon einkerkern kann, damit er einem einfach und bequem zu Diensten ist.\n\nFalls Ihr interessiert seid, begebt Euch zu Strahads Turm oberhalb von Ratchet im Brachland, dort findet Ihr sie.", completion = "Ah, Ihr sucht nach etwas... Greifbarerem. Da kann ich Euch behilflich sein, wenn Ihr wirklich darauf vorbereitet seid.\n\nEs ist eine willkommene Abwechslung zu sehen, dass jemand unserer Art nach mehr Macht strebt statt nur nach Wissen.\n\nAlso, denkt Ihr, Ihr seid bereit, {name}?", objectives = "Sprecht mit Menara Voidrender im Brachland.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[4966] = { id = 4966, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kanati Greycloud schützen", description = "Es könnte allerdings noch viel mehr Zentauren geben, als ich dachte, deshalb bitte ich Euch, {name}, zusammen mit mir gegen diese gemeinen Auftragsmörder zu kämpfen.", completion = "Danke für Eure Hilfe, {name}. Ohne Euch hätte ich sie nicht abhalten können.", objectives = "Beschützt Kanati Greycloud vor den Angriffen der Zentauren.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[4967] = { id = 4967, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wissen der Kugel von Orahil", description = "Immer noch derselbe Dummkopf... und immer noch auf der Suche nach Dingen der Sterblichen. Ja, es mag Euch arrogant erscheinen, wie ich zu Euch spreche. Ihr steht vor mir und ich muss lachen. Ihr seid jämmerlich!\n\nAber was ich denke, zählt nicht. Es zählt nur, was jene denken, die gewillt sind, sich mit Euch abzugeben! Und obwohl ich anderer Ansicht bin, sind jene, die über ein gewisses Maß an Macht gebieten, der Meinung, dass Ihr mehr verdient.\n\nWenn es das ist, wonach Ihr trachtet, solltet Ihr mit Menara Voidrender im Turm oberhalb von Ratchet sprechen. Ich glaube, Ihr habt sie vor geraumer Zeit schon einmal getroffen.", completion = "Ah, Ihr sucht nach etwas... Greifbarerem. Da kann ich Euch behilflich sein, wenn Ihr wirklich darauf vorbereitet seid.\n\nEs ist eine willkommene Abwechslung zu sehen, dass jemand unserer Art nach mehr Macht strebt statt nur nach Wissen.\n\nAlso, denkt Ihr, Ihr seid bereit, {name}?", objectives = "Sprecht mit Menara Voidrender im Brachland.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[4968] = { id = 4968, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wissen der Kugel von Orahil", description = "Hmm, Ihr habt es also bis hierher geschafft... das ist wahrhaft erstaunlich. Ich dachte, die Verderbnis durch die Kanalisierung des Arkanen hätte sich mittlerweile in Eure Seele geschlichen und Euch in den Wahnsinn getrieben. Sollen wir versuchen, Euch noch ein bisschen weiter aufzubauen?\n\nWenn Ihr Eure Fertigkeiten auf die Probe stellen wollt, sprecht mit Menara Voidrender. Sie ist in Strahads Turm oberhalb von Ratchet zu finden. Sie wird Euch leiten.", completion = "Ah, Ihr sucht nach etwas... Greifbarerem. Da kann ich Euch behilflich sein, wenn Ihr wirklich darauf vorbereitet seid.\n\nEs ist eine willkommene Abwechslung zu sehen, dass jemand unserer Art nach mehr Macht strebt statt nur nach Wissen.\n\nAlso, denkt Ihr, Ihr seid bereit, {name}?", objectives = "Sprecht mit Menara Voidrender im Brachland.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[4969] = { id = 4969, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wissen der Kugel von Orahil", description = "Haha! Das habt Ihr sehr gut gemacht, {class}.\n\nFrüher oder später werden sich selbst Höllenbestien und Schreckenslords vor Euch in den Staub werfen!\n\nAber bis dahin müsst Ihr Euch noch auf die Waffen verlassen, die von Sterblichen geschaffen wurden.\n\nIhr scheint bereit zu sein für ein weiteres solches Werk, und wenn Ihr möchtet, würde Menara Voidrender mit Euch sprechen! Sie ist in der Nähe von Strahads Turm zu finden, der oberhalb der Hafenstadt Ratchet steht. Geht dorthin, wenn Ihr bereit seid.", completion = "Ah, Ihr sucht nach etwas... Greifbarerem. Da kann ich Euch behilflich sein, wenn Ihr wirklich darauf vorbereitet seid.\n\nEs ist eine willkommene Abwechslung zu sehen, dass jemand unserer Art nach mehr Macht strebt statt nur nach Wissen.\n\nAlso, denkt Ihr, Ihr seid bereit, {name}?", objectives = "Sprecht mit Menara Voidrender im Brachland.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[4970] = { id = 4970, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Frostsäblerverpflegung", description = "Wenn Ihr Euch beweisen wollt, könnt Ihr eine sehr einfache, aber sehr wichtige Aufgabe erledigen.\n\nSammelt Fleisch von der Schimäre und den Splitterzahnbären in diesem Gebiet. Bringt es mir, dann kann ich damit die Frostsäbler füttern, die gerade ausgebildet werden.", progress = "Disziplin und Bestimmtheit sind Eure Ziele. Ich werde Euch häufig bitten, einfache Aufgaben zu erledigen; Ihr müsst sie jeweils erfüllen, so gut es Euch möglich ist.", completion = "Danke, dass Ihr mir geholfen habt, {name}. Meine Meinung von Euch wächst mit der Zeit.", objectives = "Sammelt 5 Splitterzahnfleischstücke und 5 Fleischstücke einer Eiswindschimäre für Rivern Frostwind in Winterspring.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[4971] = { id = 4971, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Frage der Zeit", description = "Die Zeitlinie in Andorhal wurde durch eine finstere Kraft verfälscht - wahrscheinlich durch die Geißel! Ich kann versuchen, das Verstreichen der Zeit hier in den Griff zu bekommen und den Schaden zu beheben, aber dazu benötige ich Hilfe, damit ich dabei nicht gestört werde.\n\nTemporale Parasiten - Aas, das sich von den Strängen des veränderten Zeitflusses ernährt, sucht jetzt die Silos von Andorhal heim. Man kann sie nur an der blau pulsierenden Verzerrung erkennen. Sie behindern meine Weissagungen. Bitte helft mir, {name}, indem Ihr diesen Temporalversetzer benutzt, um diese Parasiten auszurotten.", progress = "Temporale Parasiten sind eine Landplage, die immer dann auftritt, wenn sich jemand am Zeitablauf zu schaffen macht. Ich spüre, dass es eine Menge davon gibt, und das beunruhigt mich.\n\nRottet so viele aus, wie Ihr finden könnt. Das wird mir helfen, die sich stetig verschlechternde temporale Lage wieder unter Kontrolle zu bringen. Ich kann es spüren, sobald Ihr Erfolg hattet.", completion = "Es scheint jetzt leichter zu sein, die Zeit wieder zu korrigieren, danke, {name}. Ihr mögt vielleicht nicht ganz verstehen, welche Konsequenzen ein aus den Fugen geratener Zeitablauf, eine gestörte Zeitlinie, haben kann, aber ich weiß es zu schätzen, dass Ihr versteht, wie dringlich es ist, dem Einhalt zu gebieten, was ich mehr und mehr für eine von der Geißel verursachte Bösartigkeit halte.\n\nEs ist wohl angebracht, dass ich Euch für Eure Hilfe belohne, sterbliches Wesen. Die größten Aufgaben stehen Euch noch bevor und ein kleines Schmuckstück als Belohnung wird Euer Schicksal bestimmt nicht beeinflussen. Eure beständige Unterstützung jedoch ist etwas, das für mich und den Drachenschwarm sehr nützlich sein könnte...", objectives = "Benutzt den Temporalversetzer in der Nähe eines der Silos von Andorhal, um die temporalen Parasiten aufzuspüren.\n\nTötet 15 temporale Parasiten und bringt dann den Temporalversetzer zu Chromie im Gasthaus Andorhal in den Westlichen Pestländern.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[4972] = { id = 4972, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tempus fugit", description = "Ich müsst für mich in die jenseits dieses Raumes liegende Welt gelangen, {name}. Lasst es mich Euch erklären.\n\nIhr seht, dass dieser Raum hier anders ist als der Rest von Andorhal. Mein Drachenschwarm agiert auf verschiedene Weise und in vielen verschiedenen Zeitlinien. Um den in Andorhal angerichteten Schaden zu beheben, handle ich jetzt von einer anderen Zeitlinie aus, um sie nicht allzu sehr zu kontaminieren. Um diese Arbeit fortzusetzen, benötige ich Zeitobjekte, die aus einer Zeit stammen, bevor die Seuche auftrat. Ihr findet sie in Schließkassetten in den Ruinen der Gebäude, die einst diese stolze Stadt waren.", progress = "Die Zeitobjekte sind einfache Geräte. Es handelt sich hauptsächlich um Uhren, deren Zeiger stehen blieben, als die Seuche das erste Mal über Andorhal hereinbrach.\n\nDie Zeit bleibt niemals stehen und die Uhren, die Ihr mir bringt, kehren mit unfehlbarer Sicherheit immer wieder zu ihrem Ursprungsort zurück... das heißt, solange die Störungen hier andauern.", completion = "Genau das, was ich brauche, {name}. Danke.\n\nErlaubt mir, Euch hiermit angemessen zu belohnen. Ihr fragt Euch vielleicht jetzt, was Ihr mit einem solchen Gerät anfangen sollt. Vielleicht wisst Ihr nicht einmal, worum es sich dabei genau handelt. Ich kann Euch leider nicht sagen, wann genau es Euch nützlich sein wird. Ihr müsst nur wissen, dass es irgendwann in der Zukunft äußerst nützlich und praktisch sein wird, wenn Ihr es benutzt. Ob Ihr es bis dahin behaltet oder nicht ... das bleibt allein Euch überlassen.", objectives = "Sucht 5 Andorhal-Uhren, die in Schließkassetten überall im Schutt der Stadt zu finden sind. Kehrt mit ihnen zu Chromie ins Gasthaus Andorhal in den Westlichen Pestländern zurück.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[4973] = { id = 4973, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tempus fugit", description = "Falls Ihr gewillt seid, mir noch einmal zu helfen, würde ich Eure Unterstützung dankbar annehmen. Ich nehme Euch gern weitere Uhren ab, die Ihr in den Ruinen von Andorhal findet. Sie helfen mir sicherlich dabei, das Gleichgewicht gegen die unbekannte bösartige Kraft zu erhalten, die hier mit der Zeitlinie herumspielt.\n\nIm Austausch für diese Uhren werde ich Euch einen anderen Gegenstand geben, der sich, wie ich vermute, in der Zukunft für Euch als von großem Wert erweisen wird.", progress = "Die Uhren von Andorhal, ähnlich wie die große Uhr in der Ruine des Rathauses, sind sämtlich um drei Uhr stehen geblieben. Genau zu diesem Zeitpunkt hatte die Seuche die Stadt zum ersten Mal mit voller Wucht getroffen, sich ausgebreitet und jegliches Leben darin erstickt.\n\nSo sehr wir alle es auch bedauern, was an diesem Tag geschah, so sehr hat es doch auch den Zeitfluss geprägt, wie Ihr Sterblichen ihn heute empfindet. Der bronzene Drachenschwarm darf nicht nachlassen, die Zeitlinie zu schützen!", completion = "Habt abermals Dank für Eure Unterstützung. Bitte nehmt dieses Geschenk. Ihr mögt zwar immer noch nicht wissen, wann Ihr einen solchen Gegenstand benutzen könnt, aber vielleicht wird Euch irgendwann der Lauf der Zeit enthüllen, was Euch beschieden ist. Man könnte sagen, ich habe gesehen, dass es sich so ereignen wird, {name}.", objectives = "Sucht 5 Andorhal-Uhren in den Ruinen der Stadt und bringt sie Chromie im Gasthaus Andorhal in den Westlichen Pestländern.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[4974] = { id = 4974, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Für die Horde!", description = "Nur weil der schwarze Drachenschwarm hinter ihm steht, wagt Rend es, solche Ansprüche zu stellen.\n\nIhr, {name}, müsst einen Weg finden, die Hallen des Aufstiegs zu durchqueren. Dahinter findet Ihr den 'Kriegshäuptling' Rend Blackhand. Ihr müsst ihn vernichten... FÜR DIE HORDE!\n\n<Thrall schlägt mit der Faust auf seinen Thron.>\n\nWenn Ihr meine Gemächer das nächste Mal betretet, werdet Ihr seinen Kopf triumphierend in die Höhe halten und ihn Eurem Kriegshäuptling präsentieren. Gelingt Euch das, wird man Euch als Held der Horde ehren.", progress = "<Thrall grunzt.>", completion = "Ihr habt der Streitmacht von Blackrock einen schweren Schlag versetzt, {name}. Da ihr Kriegshäuptling jetzt tot ist, wird die Blackrocklegion erneut im Sumpf des Chaos versinken.\n\nZu Ehren Euer Heldentaten wird Euch das Volk von Kalimdor belohnen!", objectives = "Begebt Euch zur Blackrockspitze und tötet den Kriegshäuptling Rend Blackhand. Nehmt seinen Kopf und kehrt nach Orgrimmar zurück.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[4975] = { id = 4975, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die fertig gestellte Kugel von Noh'Orahil", description = "Ich werde sofort mit der Arbeit an Eurer Kugel beginnen und Euren neuen Dämon darin einschließen. Wenn ich damit fertig bin, könnt Ihr entscheiden, ob Ihr ihn lieber in Form eines Stabs oder einer Kugel hättet. Ich fand es schon immer wichtig, dafür zu sorgen, dass jeder Hexenmeister die richtige Waffe bekommt ... Ich wüsste nicht, warum ich jetzt mit dieser Praxis aufhören sollte.", completion = "Es ist vollbracht, {name}. Sagt mir, was Ihr lieber hättet: einen Stab, den Ihr mit beiden Händen führen müsstet, oder eine Kugel, sodass Ihr gleichzeitig noch einen Dolch oder ein Schwert als Waffe führen könnt.\n\nDass Ihr eine Höllenbestie besiegt habt, war eine große Leistung, und diese Belohnung wird Euch gut zupass kommen. Ich wünsche Euch weiterhin viel Erfolg, {name}.", objectives = "Wartet, bis Menara Voidrender die Kugel von Noh'Orahil fertig gestellt hat, und sprecht dann noch einmal mit ihr.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[4976] = { id = 4976, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ablieferung der gesäuberten Kugel", description = "Bringt die gesäuberte Kugel zurück zu Menara nach Ratchet, {name}. Grüßt sie von mir und passt auf Euch auf. Ich hoffe wirklich, dass Ihr der Versuchung und der Verderbnis widerstehen könnt, die Euch auf Eurem Weg sicherlich begleiten werden.\n\nViel Glück.", progress = "Wie läuft die Suche nach Tabetha und der Kugel, {name}?\n\nTabetha hat sich als mehr als hilfreich erwiesen, wenn es um arkane Dinge geht. Sie wird Euch bestimmt gern helfen, falls es Euch gelingt, sie zu finden.", completion = "Gut gemacht, {name}. Das dürfte reichen.\n\nJetzt müsst Ihr nur noch entscheiden, welchen Dämon ich in der gesäuberten Kugel einkerkern soll. Entscheidet Euch, dann habt Ihr einen wunderbaren neuen Gegenstand, den Ihr benutzen könnt.", objectives = "Bringt die gesäuberte Höllenkugel zu Menara Voidrender ins Brachland.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[4981] = { id = 4981, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Agentin Bijou", description = "Trau niemals einem Goblin. Darauf läuft es doch hinaus, {name}.\n\nSie heißt Bijou und ist eine unserer unzuverlässigsten Agentinnen. Ich habe herausgefunden, dass sie für irgendeinen zwielichtigen Tierhändler namens Kibler außerhalb der brennenden Steppe gearbeitet hat - sie hat uns schlicht und ergreifend hintergangen. Und was noch schlimmer ist, sie hat Gelder der Horde veruntreut, um ihre Machenschaften zu finanzieren.\n\nIch will, dass man sie mir lebend bringt!\n\nZuletzt wurde sie beim Betreten der Blackrockspitze gesehen. Findet sie und bringt sie her.\n\nUnd lasst Euch bloß nicht von ihr umgarnen, {name}.", completion = "Ich kann Euch nicht belügen, {race}. Ich brauchte das Geld! Kibler bezahlt mich sehr, sehr gut - viel besser als es das KEK je könnte.\n\nAber bitte zweifelt nicht an meiner Loyalität! Warum, glaubt Ihr, bin ich wohl hier? Um diesem verrückten Goblin ein paar Eier von exotischen Tieren oder ähnlichen Unfug zu bringen? Nein, nur jemand, der wirklich absolut dämlich ist, würde zur Blackrockspitze kommen, um nach Tieren zu suchen. Tja, ich glaube nicht, dass es allzu viele Leute dieser Art auf der Welt gibt.\n\n\n\nDas würde uns gerade noch fehlen, dass sich solche Leute noch vermehren.", objectives = "Begebt Euch zur Blackrockspitze und findet heraus, was aus Bijou geworden ist.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[4982] = { id = 4982, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bijous Habseligkeiten", description = "Nachts, wenn dieser Ort hier nur leicht bewacht ist, schleiche ich durch die Stadt, mache mir Notizen und schreibe alles auf, was für das KEK strategisch nützlich sein könnte.\n\nLetzte Nacht ist allerdings etwas fürchterlich schief gegangen. Ich bin über einen Stolperdraht getappt und habe einen Alarm ausgelöst. Also habe ich mein Spionagezeug versteckt und bin auf Tauchstation gegangen! Leider kann ich nicht zurück, um meine Ausrüstung zu holen. Sie haben die Patrouillen verdoppelt und verdreifacht! All diese Informationen sind verloren.\n\nHolt mir meine Habseligkeiten, dann kehre ich freiwillig zum KEK zurück.", progress = "Glück gehabt?", completion = "Ihr habt es geschafft! Sobald Lexlort diese Pläne hat, wird er all die üblen Dinge vergessen, die er mir antun wollte.\n\n{name}, Ihr seid mein Held!", objectives = "Sucht Bijous Habseligkeiten und bringt sie ihr. Ihr erinnert Euch daran, dass sie erwähnte, ihre Sachen auf der untersten Ebene der Stadt versteckt zu haben.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[4983] = { id = 4983, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bijous Aufklärungsbericht", description = "Bringt Lexlort diesen Bericht. Er wird meinen Namen reinwaschen und dem KEK bestimmt einen strategischen Vorteil gegenüber diesen Orcs verschaffen.\n\nIch soll mit Euch kommen? Dafür habe ich noch viel zu viel zu tun. Geht jetzt, diese Berichte werden gebraucht, je eher, desto besser!", progress = "Wo ist der Goblin???", completion = "Eines muss man ihr lassen, sie hat es wieder einmal geschafft, sich aus einer heiklen Situation herauszulavieren! Diese Berichte werden sich als unschätzbar erweisen, wenn wir es wieder mit den Orcs des Blackrockklans zu tun bekommen.\n\nNatürlich werdet Ihr für Eure harte Arbeit belohnt werden.", objectives = "Bringt Bijous Aufklärungsbericht zu Großmeister Lexlort nach Kargath.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[4984] = { id = 4984, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Tierwelt leidet auch", description = "Allein konnte ich nicht viel tun, um die Geißel zu bezwingen. Aber ich kam dennoch hierher, um zu versuchen, den an der Natur angerichteten Schaden zu lindern. Die Tiere leiden unter der Seuche, die das Land noch immer plagt, und finden weder Gnade noch Frieden. Ich bitte Euch fortzusetzen, was ich hier nicht beenden konnte.\n\nEs gibt für diese leidenden Tiere keine Rettung, nur eine gnädige und sanfte Erlösung. Sucht die kranken Wölfe auf, die sich hier in der Nähe befinden, und tötet sie. Bitte, {name}, macht ihrem Leiden ein Ende - Ihr würdet damit auch meinen Kummer lindern.", progress = "Die von der Seuche infizierten Wölfe müssen getötet werden, {name}. Die Krankheit, an der sie leiden, ist unheilbar. Ich habe es versucht... Ich habe es versucht, bis ich mich selbst mit dieser Seuche angesteckt habe.", completion = "Ich... Ich spüre, dass die Seelen der Wölfe, die Ihr getötet habt, jetzt endlich Ruhe finden. Sie - und ich - danken Euch für die gnädige Befreiung.\n\nDie Wölfe sind jedoch nicht die Einzigen, die an diesem verfluchten Ort leiden, {name}. Bitte, ich benötige noch einmal Eure Hilfe.", objectives = "Tötet 8 kranke Wölfe und kehrt dann zu Mulgris Deepriver auf dem trostlosen Feld in den Westlichen Pestländern zurück.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[4985] = { id = 4985, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Tierwelt leidet auch", description = "Östlich von hier, etwa da, wo die Östlichen Pestländer beginnen, streiften einst stolze und herrliche Grizzlys durch das Land. Die von der Geißel freigesetzte Seuche hat auch auf diese Wildtiere übergegriffen. Jetzt ziehen sie durchs Land und leiden sehr, während ihre Muskeln steif werden und ihr Fell und Fleisch langsam verrotten.\n\nIch bitte Euch, auch sie von ihrem Elend zu erlösen. Das einzige Heilmittel für sie ist ein schneller Tod, beigebracht durch Eure Hand.", progress = "Ich höre Eure Schritte, {name}. Meine Sehkraft ist geschwunden, aber ich kann immer noch Dinge in meiner Umgebung spüren. Habt Ihr die kranken Grizzlys von ihrem Elend erlöst?", completion = "Ich weiß, dass die Grizzlys tot sind und ihre Qual ein Ende hat. Ich... Ich habe da noch etwas für Euch. Ich habe es auf diesem... diesem Ast niedergeschrieben, weil ich fühle, dass meine Zeit in diesem Reich zu Ende geht.\n\nJa... Ich habe das Ende erreicht. Habt nochmals Dank... die Kreaturen dieses verfluchten Landes können in Frieden ruhen... und das werde ich jetzt auch.\n\nDer Druide seufzt noch einmal tief auf, dann folgt ein rasselndes Geräusch des Todes. Sein Körper liegt reglos auf dem Boden der Hütte.", objectives = "Tötet 8 kranke Grizzlys und kehrt dann zu Mulgris Deepriver auf dem trostlosen Feld in den Westlichen Pestländern zurück.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[4986] = { id = 4986, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Glyphenverzierter Eichenast", description = "Die leblose Hand des Tauren hält einen erstaunlich gesund aussehenden Eichenast umklammert. Als Ihr den Ast untersucht, entdeckt Ihr Glyphen druidischer Art, die in die Rinde geritzt sind.\n\nIhr nehmt den Ast und stellt fest, dass er sich warm anfühlt. Viel wärmer, als er sich anfühlen sollte. Vor Eurem inneren Auge erscheint das Bild des Teldrassil-Baumes - genau gesagt von Darnassus - und die Worte \"Zirkel des Cenarius\" liegen Euch auf der Zunge. Es scheint, als hätte man dem Ast die Information mitgegeben wohin er zu bringen sei.", progress = "Ich heiße Euch im Namen des Zirkels des Cenarius in dieser Enklave willkommen, {class}. Was können wir für Euch tun?", completion = "Das... ist ziemlich seltsam. Dieser Druide - ein Taurendruide noch dazu - hat Euch eine Menge wertvoller Informationen bezüglich des Ausmaßes der Seuche der Geißel anvertraut. Es überrascht mich, dass ein Tauren einem wie Euch, {race}, Informationen überlassen würde, noch dazu freiwillig, wenn es stimmt, was Ihr sagt. Wir können sie aber wirklich gut gebrauchen. Vielleicht sind die Tauren ja doch nicht so weit von Cenarius abgefallen, wie Fandral meint...\n\nÄhm, wie dem auch sei, bitte nehmt dies als Zeichen des Danks des Zirkels des Cenarius.", objectives = "Nach der Magie zu urteilen, mit der der glyphenverzierte Eichenast erfüllt ist, hatte der Taurendruide wohl gewollt, dass Ihr den Ast zum Zirkel des Cenarius nach Darnassus bringt. Bittet einen der Druiden dort um Hilfe.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[4987] = { id = 4987, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Glyphenverzierter Eichenast", description = "Die leblose Hand des Tauren hält einen erstaunlich gesund aussehenden Eichenast umklammert. Als Ihr den Ast untersucht, entdeckt Ihr Glyphen druidischer Art, die in die Rinde geritzt sind.\n\nIhr nehmt den Ast und stellt fest, dass er sich warm anfühlt. Viel wärmer, als er sich anfühlen sollte. Vor Eurem inneren Auge erscheint das Bild von Thunder Bluff in Mulgore - genau gesagt von der Anhöhe der Ältesten - und die Worte \"Zirkel des Cenarius\" liegen Euch auf der Zunge. Es scheint, als hätte man dem Ast die Information mitgegeben, wohin er zu bringen sei.", progress = "Ich heiße Euch im Namen des Zirkels des Cenarius in dieser Enklave willkommen, {class}. Was können wir für Euch tun?", completion = "Das ist von Mulgris, sagt Ihr? Wir haben gehört, dass er danach trachtete, den leidenden Kreaturen der Pestländer zu helfen, aber das ist jetzt doch etwas unerwartet... und ziemlich traurig. Mulgris ist... war ein guter Freund. Ich werde sehr um ihn trauern.\n\nSeine Bemühungen waren Dank Eures Eifers jedoch nicht umsonst. Auf diesem Ast sind sehr viele Lehren über die Seuche festgehalten, die die Geißel über das Land gebracht hat. Wir werden alles eingehend untersuchen. Was Euch betrifft... bitte nehmt dies. Das ist das Mindeste, das wir zum Dank für Eure Mühen tun können.", objectives = "Nach der Magie zu urteilen, mit der der glyphenverzierte Eichenast erfüllt ist, hatte der Taurendruide wohl gewollt, dass Ihr den Ast zum Zirkel des Cenarius nach Thunder Bluff bringt. Bittet einen der Druiden dort um Hilfe.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[5001] = { id = 5001, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bijous Habseligkeiten", description = "Normalerweise gebe ich mich nicht mit Euresgleichen ab, {race}, aber mir scheint, ich stecke hier in einer Zwickmühle. Wisst Ihr, meine Mission hier ist für die Horde von allergrößter Wichtigkeit. Die Informationen, die ich hier gesammelt habe, betreffen jedoch auch das Wohlergehen der Allianz. Ihr könnt mir glauben, ich bin wahrlich kein Freund der Allianz, aber die Gefahr durch die Blackrock ist größer als nur ein Haufen Orcs.\n\nIhr helft mir, meine Habseligkeiten zu finden, dann helfe ich Euch mit ein paar Informationen aus, die sich für Euresgleichen als nützlich erweisen könnten.\n\nAbgemacht?", progress = "Glück gehabt?", completion = "Da brat mir doch einer... Wo habt Ihr denn das gefunden???", objectives = "Sucht Bijous Habseligkeiten und bringt sie ihr. Viel Glück!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[5002] = { id = 5002, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nachricht an Maxwell", description = "Ich bin ein Goblin, der zu seinem Wort steht, {race}. Und jetzt hört gut zu.\n\nDiese Orcs werden vom schwarzen Drachenschwarm vor allem als Packesel und Kanonenfutter missbraucht!\n\nIhr wahrer Anführer ist kein Geringerer als Nefarian, die Brut von Deathwing. Ich habe auch den Aufenthaltsort der Untergebenen von Nefarian in diesem Teil der Zitadelle entdeckt.\n\nBringt diese Karte zu Marshal Maxwell in der brennenden Steppe. Auf ihr ist der Aufenthaltsort dieser Teufelskreaturen eingezeichnet, um es einfacher zu machen.", progress = "Ah, {name}. Wir haben uns lange nicht gesehen.", completion = "Das passt zu einem großen Teil dessen, was wir bereits wissen. Dennoch ist es interessant und höchst unerfreulich.\n\nDie Markierungen auf dieser Karte werden sich bei der Ausdünnung der Blackrockbedrohung als wertvoll erweisen.", objectives = "Begebt Euch in die brennende Steppe und leitet Bijous Informationen an Marshal Maxwell weiter.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[5021] = { id = 5021, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Besser spät als nie", description = "Das Paket muss ausgeliefert werden... sonst bin ich hier gefangen!\"\n\nWie ein Flüstern zieht das Wehklagen einer verängstigten Frau durch das Haus. In einer Ecke im oberen Stockwerk kauert eine weibliche, geisterhafte Gestalt. Sie scheint sich ihrer Umgebung nicht ganz gewahr zu sein und ist sich Eurer nur vage bewusst.\n\n\"Seid Ihr hier, um mein Paket auszuliefern? Bitte, bevor es noch viel schlimmer wird! Ich wollte hier wegreiten. Es sollte immer noch bei meinem Pferd sein... oder komme ich zu spät?", completion = "Ein Paket in der Scheune, das Ihr sonst übersehen hättet, fällt Euch nun zwischen Zerfall und Ruin ins Auge. Vielleicht ist es das, worüber der Geist von Janice Felstone gesprochen hat...", objectives = "Das wilde Gebrabbel der Geisterfrau deutete darauf hin, dass sie ein Paket ausliefern musste. Sie behauptete, dass es dort war, wo auch ihr Pferd war. Darüber, wo das Pferd jetzt ist oder wohin das Paket ausgeliefert werden muss, sagt der Geist nichts.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[5022] = { id = 5022, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Besser spät als nie", description = "Ihr hebt das Paket auf und wischt eine dünne Schicht aus Staub und Schmutz ab, mit der es bedeckt ist. Es ist mit hastig hingekritzelter Schrift an eine Emma Felstone in Stormwind adressiert; die Auslieferung des Pakets war für einen Tag vor über vier Jahren geplant.\n\nOb Emma Felstone überhaupt noch lebt, ist nicht klar. Aber man weiß, dass im Rathaus von Stormwind Unterlagen über die Bevölkerung der Stadt aufbewahrt werden. Sie werden von den königlichen Disponenten des Volkszählungsbüros von Stormwind verwaltet.", progress = "Willkommen im Volkszählungsbüro von Stormwind. Wenn Ihr Informationen über unsere Bevölkerung benötigt, dann kann ich Euch helfen.", completion = "Ein Paket für eine Emma Felstone, sagt Ihr? Letzte bekannte Adresse war Stormwind, vor vier Jahren? Tja, lasst mich mal nachsehen...\n\nNach dem, was wir wissen, gab es vor ungefähr vier Jahren eine Emma Felstone in der Stadt. Na ja, ich sollte sagen möglicherweise - diese Volkszählung, auf die ich mich beziehe, liegt fünf Jahre zurück und ich habe keinen Bericht darüber, dass sie die Stadt verlassen hat. Das bedeutet aber nicht, dass sie immer noch hier ist.\n\nWartet einen Moment... dieses Paket könnte nicht vielleicht für die alte Emma sein, oder?", objectives = "Wendet Euch an die königlichen Disponenten von Stormwind, um etwas über den Aufenthaltsort von Emma Felstone herauszufinden. Normalerweise findet sich ein Volkszählungsbeamter im Rathaus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[5023] = { id = 5023, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Besser spät als nie", description = "Ihr hebt das Paket auf und wischt eine dünne Schicht aus Staub und Schmutz ab, mit der es bedeckt ist. Es ist mit hastig hingekritzelter Schrift an einen Jeremiah Felstone aus Lordaeron adressiert; die Auslieferung des Pakets war für einen Tag vor über vier Jahren geplant.\n\nOb Jeremiah Felstone überhaupt noch lebt, ist nicht klar. Aber man weiß, dass Undercity, früher bekannt als Lordaeron, Unterlagen über die Bevölkerung der Stadt aufbewahrt. Sie werden von den königlichen Vorarbeitern des Volkszählungsbüros von Undercity verwaltet.", progress = "Seid Ihr hier, weil Ihr die Hilfe des Volkszählungsbüros von Undercity sucht, oder nur, um mich zu fragen, ob jemand, den Ihr kanntet, tot ist? Ich werde das häufig gefragt.", completion = "Ein Paket für einen Jeremiah Felstone, und seine letzte bekannte Adresse war Lordaeron... Ich sollte Euch helfen können.\n\nJeremiah Felstone war vor der Seuche in der Stadt. Tja, ich sollte sagen, der 'ehemalige' Jeremiah Felstone - einige der Verlassenen haben ihren Nachnamen abgelegt, um sich ihrer früheren Identitäten zu entledigen. Dieser Fall ist keine Ausnahme; der ehemalige Jeremiah Felstone ist jetzt unter dem Namen Jeremiah Payson bekannt.\n\nSekunde... ist er nicht der Kakerlakenverkäufer?", objectives = "Wendet Euch an die königlichen Vorarbeiter von Undercity, um etwas über den Aufenthaltsort von Jeremiah Felstone herauszufinden. Normalerweise findet sich ein Volkszählungsbeamter in der Nähe der Gilden- und Wappenrock-Registrierung.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[5041] = { id = 5041, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vorräte für Crossroads", description = "Die Karawane, die angegriffen wurde, führte Vorräte mit sich, die wir dringend benötigen.\n\nIhr wart bisher tapfer genug, den Grimmhauerstamm zu bekämpfen, und ich werde Euch bitten, es erneut zu tun. Dieses Mal wüsste ich aber gern, ob ich Euch bitten könnte, nach unseren verlorenen Vorräten Ausschau zu halten. Ihr könnt sie wahrscheinlich in ihren Lagern finden; die Stacheleber werden durch ihre schändlichen Taten fett.\n\nDie Einwohner von Crossroads wären in Eurer Schuld.", progress = "Wie läuft Eure Suche nach den Vorräten, {name}? Ich schätze, die Stacheleber werden unter Eurer Kraft schnell fallen.", completion = "Haha! Danke, {name}! Das wird uns höchst dienlich sein. Ihr seid ein Segen für Crossroads und die Horde. Wenn ich etwas für Euch tun kann, dann lasst es mich bitte wissen.", objectives = "Findet die Crossroads-Vorratskisten und bringt sie zu Thork im Brachland zurück.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[5042] = { id = 5042, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Agammagans Kraft", progress = "Ich benötige 4 Blutsplitter, wenn Ihr Agammagans Kraft wünscht, {race}.\n\nEure Feinde werden vor Eurer Kraft erzittern, wenn Ihr über diesen Segen verfügen würdet. \n\nDie größten Krieger der Grimmhauer sind mit solcher Stärke ausgestattet!", completion = "Wenn nur Quetschzahn frei wäre, um diejenigen zu dezimieren, die ihn betrogen haben! <schnaubt>\n\nIch danke Euch, dass Ihr durch das Sammeln dieser Splitter noch mehr Borstennacken vernichtet habt. Setzt Eure Arbeit bitte weiter fort und ich werde Euch weiterhin helfen. <schnaubt>" }
quests[5043] = { id = 5043, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Agammagans Beweglichkeit", progress = "Man sagt, dass die größten Späher meines Stammes in ihrer Genauigkeit unübertroffen seien und kein Schurke <schnaubt> ihrer Schnelligkeit im Kampf standhalten könne.\n\nBringt mir 4 Blutsplitter und ich werde Euch noch flinker machen als jeder lebende Stacheleber.", completion = "Möge Eure Zielgenauigkeit unfehlbar sein und Eure Waffe Euch nie im Stich lassen, {race}.\n\nAgammagans Geist ist mit Euch. Kehrt  zu mir zurück, wenn Ihr wünscht. Quetschzahn wird Euch wieder segnen, wenn der große Gott der Eber mich als würdig ansieht." }
quests[5044] = { id = 5044, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weisheit von Agammagan", progress = "Die Schamanen und Geomanten der Stacheleberstämme <schnaubt> nutzen die Kraft von Agammagan im Kampf und bei ihren Ritualen, {race}.\n\nWenn auch Ihr die zusätzliche Macht von Agammagans Segen für Eure Zauber wünscht, dann bringt mir 4 Blutsplitter, und Quetschzahn wird Euch helfen.", completion = "Eure Feinde sollten Euch noch mehr fürchten, {race}. \n\nErzählt Quetschzahn Geschichten von Eurer Schlauheit im Kampf, wenn wir uns das nächste Mal treffen - sei es in diesem Leben oder im nächsten." }
quests[5045] = { id = 5045, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Steigerung des Geistes", progress = "Krieger aller Art <schnaubt> benötigen einen starken Geist. Er treibt Euch zu größeren Leistungen, wenn alle Hoffnung verloren ist. Das ist den Grimmhauern nicht <schnaubt> unbekannt. Wir sind ein spiritueller Stamm... wir sind stolzer auf unsere Verbindung zu Agammagan als auf unsere Leistungsfähigkeit <schnaubt> im Kampf.\n\nBringt mir 4 Blutsplitter und ich werde Euch für den Kampf segnen. <schnaubt>", completion = "Unsere größten Krieger und unsere größten <schnaubt> Schamanen würden Eure Willenskraft beneiden, {race}.\n\nErledigt noch mehr dieser Borstennacken, wissend, dass sie Euch nicht stoppen können!" }
quests[5046] = { id = 5046, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Klingenhaut", progress = "Alle, die <schnaubt> in den Kampf eintreten, benötigen Schutz. Ihre Knochen müssen stark sein. Ihre Haut zäh. <schnaubt> Mein Stamm weiß das auch und um den natürlichen Schutz zu verstärken, den wir durch unsere Stacheln und unsere Haut erhalten, <schnaubt> rufen wir Agammagan an, uns vor Schaden zu schützen, bevor wir in den Krieg ziehen.\n\nBringt mir 4 Blutsplitter <schnaubt> und ich werde Euch den gleichen Schutz gewähren.", completion = "Zieht in den Krieg, {race}." }
quests[5047] = { id = 5047, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pip Quickwit, zu Euren Diensten!", description = "Ihr findet Malyfous Darkhammer in Everlook, {class}. Sagt ihm, dass Pip absolut in Ordnung ist und dass der Anzug perfekt funktioniert.\n\nDann gebt ihm dies:\n\n<Pip gibt Euch ein leuchtendes Fleischstück.>\n\nIch riss es aus den Innereien des Viechs während meines 'Urlaubs.'\n\nIch wette Malyfous könnte Euch eine recht genaue Einschätzung dessen geben, was er mit Teilen eines solchen Monsters tun kann!\n\nOh, ich schätze Ihr wisst nicht, wo Everlook ist, was? Geht nach Winterspring, <Bursche/Mädel>!", progress = "Ja?", completion = "Lebendig? Anzug funktioniert? Und was haben wir denn hier?", objectives = "Sprecht mit Malyfous Darkhammer in Everlook.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[5048] = { id = 5048, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Emma die Nette", description = "Sie ist ein bisschen zänkisch und vielleicht nicht so ganz richtig im Kopf... aber diese Akten deuten darauf hin, dass die alte Emma zu den Informationen passt, die wir über Emma Felstone haben.\n\nVielleicht habt Ihr die alte Emma durch die Stadt streifen sehen... sie redet mit sich selbst, meistens sinnloses Geplapper. Sie tut aber nichts und niemandem weh, also lassen die Leute sie meist gewähren.\n\nAlles in allem würde ich sagen, dass die alte Emma tatsächlich Emma Felstone ist. Ihr könntet sie fragen, ob ihr Nachname Felstone ist.", progress = "Ich würde Euch sagen, dass Ihr von meinem Grundstück verschwinden sollt, aber wie Ihr seht, habe ich keines.", completion = "Mein Name ist tatsächlich Emma Felstone... Ihr seid seit Jahren die erste Person, die mich so nennt. Wer... wer seid Ihr?\n\nIhr sagt, Ihr kennt... meine Schwester?! Ist sie noch am Leben? Wem mache ich etwas vor, natürlich ist sie es nicht. Als in Lordaeron die Seuche ausbrach, musste ich mit dem Schlimmsten rechnen. So viele aus meiner Familie starben... oder Schlimmeres. Hier bin ich nun, die verrückte alte Emma, ganz allein. Was seid Ihr, ein Grabräuber oder so? Sucht Ihr nach Eurem nächsten Opfer?\n\nWas? Ihr habt ein Paket für mich, von meiner Schwester?", objectives = "Sucht die alte Emma in Stormwind und findet heraus, ob sie tatsächlich Emma Felstone ist. Wenn sie es ist, dann möchte sie vielleicht das Paket haben, das Janice Felstone für sie gepackt hat.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[5049] = { id = 5049, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Jammer des Jeremiah", description = "Nach den Informationen, die ich finden konnte, ist die Person, die Ihr sucht - und der vorgesehene Empfänger des Pakets -, Jeremiah Payson, der Kakerlakenverkäufer von Undercity.\n\nIch war immer der Meinung, dass es einer besonderen Gabe bedarf, um... Kakerlaken zu verkaufen. Zweifellos seid Ihr jetzt auf einer recht epischen Reise, {class}. Ich werde Euch Euren weltverändernden Bestrebungen überlassen. Erlaubt mir aber, ein Teil Eures Meisterwerks zu sein und zu enthüllen, dass er sich in der Nähe der Bank aufhält und unter einem der Gehwege herumkriecht.", progress = "Jedes Mal, wenn jemand auf eine Kakerlake tritt, muss ich weinen. Bitte, bringt mich nicht zum Weinen.", completion = "Ich habe diesen Namen seit Jahren nicht mehr benutzt... aber ja, an einem gewissen Punkt in meinem Leben - vor diesem glorreichen Unleben - war das mein Nachname.\n\nIhr behauptet, meine Schwester gekannt zu haben... oder vielmehr, kürzlich mit meiner Schwester gesprochen zu haben?\n\nDie ist tot.\n\nSeit vier Jahren.\n\nWisst Ihr, wenn meine Knochen nicht bereits so brüchig wären, wäre ich versucht, mir meinen Fuß an Eurem Hinterteil zu brechen. Ihr seid ein echter Aasgeier, eh?\n\n Was? Ihr habt ein Paket für mich, von meiner Schwester?", objectives = "Sucht Jeremiah Payson in Undercity und findet heraus, ob er tatsächlich Jeremiah Felstone ist. Wenn er es ist, dann möchte er vielleicht das Paket haben, das Janice Felstone für ihn gepackt hat.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[5050] = { id = 5050, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Glücksbringer", description = "Es scheint, dass ich bei Euch falsch lag, {name}, und dafür schulde ich Euch eine Entschuldigung. Meine Schwester hat einige persönliche Dinge geschickt, einschließlich, was witzig genug ist, die Urkunde zum Teufelssteinfeld. Ich denke, ich werde im Moment darauf verzichten, ihn zu beanspruchen.\n\nWenn der Geist meiner Schwester weiterhin an den Hof gebunden ist und keine Ruhe finden kann, bitte ... könntet Ihr dies wohl zu ihr bringen? Es ist die Hälfte eines Glücksbringers, den sie einst hatte. Die andere Hälfte hatte ihr Ehemann.\n\nVielleicht wird sie ihren Frieden finden, wenn sie weiß, dass ich diese Dinge habe.", progress = "John, Liebling... bist du das? Mir ist plötzlich so kalt...", completion = "Ihr gebt den halben Glücksbringer der Erscheinung zurück. Sie sieht erst ihn und dann erwartungsvoll Euch an.\n\n\"Liebling, wo ist deine Hälfte des Glücksbringers? Wir können nur zusammen sein, wenn wir beide Hälften haben. Liebling... kannst du mich sehen?\"", objectives = "Bringt Janice Felstone in den Westlichen Pestländern die Hälfte ihres Glücksbringers zurück.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[5051] = { id = 5051, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zwei Hälften vereint", description = "Der arme Geist plappert weiter:\n\n\"Mir ist so kalt, John. Bring mir deinen Glücksbringer und wir werden vereint sein! Schnell, John, bevor die Seuche uns in grauenhafte Bestien verwandelt! Ich kann dich nicht sehen, John... aber ich weiß, dass du nah bist. Ich fühle dich in meiner Nähe.\"\n\nVielleicht solltet Ihr die zweite Hälfte des Glücksbringers suchen und das Amulett wieder zusammensetzen... es könnte sein, dass der Geist von Janice Felstone genau das sucht.", progress = "John, lass dich nicht von den Ghuls erwischen... lass nicht zu, dass die Ghuls mich erwischen... böse Ghuls... unser Glücksbringer wird uns schützen.", completion = "Ihr übergebt den zusammengesetzten Glücksbringer dem Geist von Janice Felstone. Als sie nach ihm greift, geht fast sofort eine Veränderung mit ihr vor. Ihre Astralgestalt schimmert und sie sieht Euch mit klaren, aber traurigen Augen an.\n\n\"Ihr habt mich befreit ... Ich werde diesen Glücksbringer nicht mehr benötigen. Nehmt ihn bitte und vielleicht wird er Euch den Trost geben, den er mir gegeben hat.\"", objectives = "Sucht auf dem Teufelssteinfeld in den Westlichen Pestländern nach der anderen Hälfte des Glücksbringers und setzt ihn wieder zusammen.\n\nGebt den Glücksbringer Janice Felstone auf demTeufelssteinfeld in den Westlichen Pestländern.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[5052] = { id = 5052, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blutsplitter von Agammagan", description = "Zusammen mit diesen Dornen wirkte sich das Blut <schnaubt> auf andere Aspekte der Erde aus: blutrote Steine gemischt mit anderen Mineralien. Die Borstennacken graben diese Splitter aus und tragen sie als Totems <schnaubt> für Kraft im Kampf und als Totems für ihre Magie. <schnaubt>\n\nIch kenne die Geheimnisse dieser Magie.\n\nBringt Quetschzahn einen dieser Blutsplitter, um zu zeigen, dass Ihr verstanden habt. Bringt Quetschzahn viele dieser Splitter und er wird Euch mit Stachelebermagie segnen - der Magie von Agammagan! <schnaubt>", progress = "Unsere Stämme finden sich in den dornigen Gegenden des Brachlandes zusammen <schnaubt>, da sie heilige Orte sind, aber keiner ist so heilig wie Razorfen. Agammagans Körper bildet die Gesamtheit des Razorfen <schnaubt>, aber die Hügel sind besonders geschützt, da der Eingang aus seinem großen Maul gefertigt ist! <schnaubt> Er wird die mit Haut und Haar verschlingen, die ihm nicht treu ergeben sind, und ihre Körper ausspucken, nachdem er sie zerkaut hat! <schnaubt>\n\nAgammagan hat seinen Körper zurückgelassen, um uns zu schützen, und er gibt uns von seinem Geist, damit wir ihn schützen können. <schnaubt>", completion = "Ah, Ihr versteht also. <schnaubt> Meine Worte waren in Euren Ohren nicht verloren, {race}. Quetschzahn mag eingekerkert sein, aber kein Käfig kann Agammagans Macht stoppen! \n\nDie Berührung des Splitters, das Gefühl... es ist schon lange her, {race}.\n\nWisst Ihr, wie es ist? Wenn man seiner Macht beraubt wird?\n\nAber das ist eine andere Geschichte. Ich habe Euch Informationen versprochen. Ich habe Euch Agammagans Macht versprochen. Meine Leute haben Quetschzahn den Rücken zugewandt. Nun lasse ich Euch auf sie los.", objectives = "Bringt Quetschzahn im Camp Taurajo im Brachland einen Blutsplitter.\n\nSammelt weitere Blutsplitter, wenn Ihr von ihm mit Agammagans Macht gesegnet werden möchtet.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[5054] = { id = 5054, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ursius von den Splitterzahnbären", description = "In den schneebedeckten Bergen von Winterspring pirscht sich ein geschickter Jäger an seine Beute an... Ich spreche vom Splitterzahnbären Ursius, einer flinken und schlauen Bestie.\n\nIch schicke Euch nun gegen ihn. Er zieht durch die wogenden Hügel im Nordwesten von Everlook. Findet und jagt ihn, bevor er Eure Absicht erkennt.\n\nAlle, die bisher gegen Ursius gezogen sind, haben schnell herausgefunden, dass sie die Beute waren und er der Jäger. Also seht Euch vor.", completion = "Das war keine einfache Aufgabe und trotzdem wart Ihr erfolgreich. Aber denkt nicht, Ihr hättet mich so einfach beeindruckt, {name}.", objectives = "Storm Shadowhoof in Everlook in Winterspring möchte, dass Ihr Ursius tötet.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[5055] = { id = 5055, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brumeran von den Eiswindschimären", description = "Geschickt und schlau gleitet Brumeran leise über die schneebedeckte Landschaft des südlichen Winterspring. Lasst Euch aber nicht von Ihrem graziösen Auftreten verleiten zu glauben, dass sie harmlos sei. Alle, die ihren Weg kreuzen, bezahlen einen hohen Preis dafür und häufig mit ihrem eigenen Leben.\n\nSucht Brumeran von den Eiswindschimären. Besiegt sie und kehrt dann wieder zu mir zurück.", completion = "Ja. Ihr seid zurückgekehrt. Jetzt glaube ich, dass Ihr von Natur aus ein wahrer Jäger seid. Ihr seid den wildesten Kreaturen gegenübergetreten... und Ihr seid zurückgekehrt. Damit habt Ihr meine Erwartungen übertroffen.\n\nIhr seid nun bereit für meine letzte Bitte.", objectives = "Storm Shadowhoof in Everlook in Winterspring möchte, dass Ihr Brumeran tötet.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[5056] = { id = 5056, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shy-Rotam", description = "Im nördlichen Winterspring sammeln sich große Katzen rund um einen großen Orientierungspunkt, dem Frostsäblerfelsen. Die Anführerin dieser Katzen ist unter dem Namen Shy-Rotam bekannt. Wenn Ihr die Matriarchin der Frostsäbler besiegen würdet, würde Euch das großen Respekt in den Augen der anderen {race} einbringen.\n\nGeht erneut nach Winterspring und sammelt dort hochheiliges Fleisch von den Frostsäblern. Sucht den Stein von Shy-Rotam und legt das Fleisch dort ab. Wenn Ihr es dort platziert, ruft das Shy-Rotam herbei... und sie wird kochen vor Wut.\n\nWappnet Euch vor ihrem Zorn und besiegt sie.", completion = "Ihr habt sowohl Eure Stärke als auch Eure Entschlusskraft bewiesen. Viele weitere Herausforderungen liegen vor Euch, aber ich habe Euch bereits so viel beigebracht, wie ich konnte.", objectives = "Storm Shadowhoof in Everlook in Winterspring möchte, dass Ihr Shy-Rotam besiegt.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[5057] = { id = 5057, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Frühere Abenteuer", description = "Schon bevor Ihr mit mir spracht, {name}, habe ich von Euren Abenteuern gehört... dass Ihr den unerschütterlichen Willen habt, Euch selbst zu beweisen, und dass Ihr als {class} außerordentliche Fähigkeiten besitzt. Und nun weiß ich, dass diese Dinge wahr sind.\n\nWer wie Ihr herausragt, ist der Anerkennung würdig. Bringt diesen Gutschein zu einem Freund von mir in Thunder Bluff namens Melor Stonehoof. Ich bin sicher, dass er sich an Euch und das, was Ihr vor so langer Zeit erreicht habt, erinnern wird. Sprecht mit ihm über Eure jüngsten Siege und vergesst nicht, was Ihr heute erreicht habt.", completion = "Wir lernen aus den Erfahrungen unseres Lebens, {name}. Ich bin sicher, dass Ihr durch die Euren nur stärker und weiser geworden seid. Ihr seid innerlich gewachsen, seitdem wir das letzte Mal miteinander gesprochen haben.\n\nNehmt dies als Erinnerung an die schwierigen Aufgaben, die Ihr als {class} bewältigt habt, {race}, und wisset, dass Euch mein Respekt und meine Bewunderung immer sicher sein werden.", objectives = "Bringt Storm Shadowhoofs Gutschein zu Melor Stonehoof in Thunder Bluff.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[5058] = { id = 5058, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mrs. Dalsons Tagebuch", sourceObjective = "Ein Tagebuch mit vergilbten Seiten liegt aufgeschlagen da, sodass man den letzten Eintrag lesen kann:\n\n\"Ich weiß nicht, was passieren wird, jetzt, wo Harold sich verwandelt hat. Es hat mich meine ganze Kraft gekostet, ihn zu dem einzigen Ort zu schleppen, den ich finden konnte, in dem er sicher eingesperrt ist und nicht herauskommen kann. Den Schlüssel habe ich bei mir und ich kann nur beten, dass es funktionieren wird...\n\nIch hoffe, ich schaffe es, hier herauszukommen, aber dazu brauche ich Geld. Unsere ganzen Sachen sind alle im Schrank, glaube ich... und jetzt, wo ich darüber nachdenke - trägt Harold den Schlüssel dazu nicht bei sich?\n\nIch muss darüber schlafen. Im Augenblick bin ich todmüde.\"", sourceObjectiveStatus = "unverified-source-field" }
quests[5059] = { id = 5059, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weggeschlossen", progress = "Der von Splittern gezeichnete Türrahmen des Plumpsklos sieht aus, als ob wiederholt und unablässig versucht worden wäre, die Tür gewaltsam zu öffnen. Sie ist derzeit von außen fest verschlossen.\n\nAls Ihr an der Tür rüttelt, hört Ihr aus dem Inneren ein kehliges Stöhnen! Was auch immer sich im Inneren befindet, es klingt nicht freundlich.", completion = "Mit dem Schlüssel, den Ihr bei dem Skelett der ehemaligen Mrs. Dalson gefunden habt, schließt Ihr die Tür zum Plumpsklo auf. Ein blutdurstiger Ghul, der wer weiß wie lange dort gefangen war, springt aus dem Schuppen.\n\nAls Ihr das markerschütternde Gekreisch des Ghuls hört, mit dem er auf Eure Anwesenheit reagiert, wird Euch klar, dass der einstige Bauer Dalson nicht mehr zu retten ist." }
quests[5060] = { id = 5060, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weggeschlossen", progress = "Vor Euch steht ein sehr stabiler Schrank, sicher verschlossen mit einem eingebauten Schloss. Die Vorderseite des Schranks ist mit tiefen Kratzern und Riefen übersät. Offensichtlich sind das die Zeichen zahlreicher und gewaltsamer fehlgeschlagener Versuche, die Geheimnisse zu enthüllen, die der Schrank derzeit verbirgt.\n\nWenn Ihr diesen Schrank öffnen wollt, müsst Ihr den Schlüssel finden.", completion = "Der Schlüssel aus den ghulischen Überresten des Bauern Dalson passt perfekt in das Schloss. Die Türen des Schranks schwingen auf und enthüllen verschiedene Gegenstände, die intakt sind und recht wertvoll erscheinen." }
quests[5061] = { id = 5061, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wassergestalt", description = "Ihr habt die notwendigen Lektionen gemeistert, die alle jungen Druiden lernen, bevor sie einen Wasseraspekt annehmen können. Kehrt jetzt zu Eurem Lehrer Mathrengyl Bearwalker nach Darnassus zurück. Zeigt ihm Euren Anhänger und beweist ihm damit, dass Ihr bereit seid zu lernen, was er Euch lehren kann. Er wird Eure Ausbildung abschließen und Euch ermöglichen, eins mit dem Wasser zu werden.\n\nAuf Wiedersehen. Wir werden uns wieder sprechen.", progress = "Eure Rückkehr nach Darnassus kommt nicht überraschend, doch ich werde einen Beweis dafür benötigen, dass Ihr die Lektionen in Moonglade gelernt habt, bevor ich Euch Eure Wassergestalt lehre.\n\nHabt Ihr den Anhänger des Seelöwen?", completion = "Sehr beeindruckend, {name}. Ihr seid bereit, Eure Wassergestalt zu erlernen, und ich habe das Vergnügen, sie Euch zu lehren.\n\nAußerdem übergebe ich Euch als Anerkennung Eurer Leistungen während der beiden Prüfungen diesen Gegenstand. Ich hoffe, Ihr werdet ihn als eine wertvolle Ergänzung Eurer Ausrüstung als Beschützer der Natur und Bewahrer des Gleichgewichts ansehen.", objectives = "Kehrt nach Darnassus zurück und zeigt Mathrengyl Bearwalker den Anhänger des Seelöwen.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[5062] = { id = 5062, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hochheiliges Feuer", description = "Arikara ist eine tödliche Kreatur, die schnell beseitigt werden muss. Um sie zur Strecke zu bringen, müsst Ihr das hochheilige Feuer des Lebens anzünden - so wird Arikara beschworen.\n\nGeht nun und holt eine seltene Pflanze, die Brandpulveragave. Wenn Ihr genug Agaven gesammelt habt, sucht den Rat von Magatha Grimmtotem auf der Anhöhe der Ältesten in Thunder Bluff. Sie ist eine mächtige Schamanin, die die Agavenpflanze verzaubern kann, um ein Pulver zu erzeugen, das das Feuer entzünden kann.\n\nReist in Richtung Osten zum Siedenden Teich und sammelt Brandpulveragaven.", progress = "So, Motega Firemane schickt Nachricht von Arikara... nun, das sind böse Neuigkeiten.\n\n<Magatha sieht sich um.>\n\nArikara ist eine tödliche Kreatur, die nur geboren wurde, um Rache gegen die zu suchen, die ruchlose Taten begangen haben.\n\n<Magatha lächelt.>", completion = "Gut, Ihr habt die benötigte Menge Brandpulveragaven gesammelt. Dieses seltene Kraut, das man nur in Tausend Nadeln findet, wird helfen, das schlafende hochheilige Feuer des Lebens zu erwecken.\n\n<Magatha beginnt, die Brandpulveragaven zu verzaubern.>", objectives = "Sammelt 10 Scheffel Brandpulveragaven und beratet Euch dann mit Magatha Grimmtotem auf der Anhöhe der Ältesten in Thunder Bluff.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[5063] = { id = 5063, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kappe des scharlachroten Wissenden", description = "Eine feinere Kappe werdet Ihr niemals sehen. Aus dem makellosen Balg der Bestie werden unsere Experten den phänomenalsten Hut schaffen, den ein Gaukler jemals zu tragen träumte!\n\nFünfzig Goldstücke zusammen mit den aufgeführten Gegenständen und Euer Kopf wird von der Kappe des scharlachroten Wissenden geziert:\n\n*Einen makellosen Balg der Bestie.\n\n*Ausgefranste Monstrositätenstickereien.\n\n*Arkankristalle.\n\n*Verzauberter scharlachroter Faden.\n\nMERKT AUF!", objectives = "Um die Kappe des scharlachroten Wissenden herzustellen, müsst Ihr die folgenden Dinge zu Malyfous Darkhammer bringen: 1 makelloser Balg der Bestie; 5 ausgefranste Monstrositätenstickereien; 8 Arkankristalle; 5 verzauberte scharlachrote Fäden.\n\nIhr müsst außerdem 50 Goldstücke für die Herstellung des Gegenstandes zahlen.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[5064] = { id = 5064, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grimmtotemspionage", description = "{name}, Ihr habt uns in der Vergangenheit gut gedient, sodass ich Euch jetzt eine wichtige Mission anvertraue. Der Grimmtotemklan plant etwas, das niemand wissen soll. Drei Agenten unbekannter Herkunft wurden gesehen, wie sie die Grimmtotem in den vergangenen Wochen besuchten. Wir haben entdeckt, dass diese geheimnisvollen Botschaften im Düsterwolkengipfel in verschiedenen Truhen verwahrt werden.\n\n{name}, wenn Ihr bei dieser gefährlichen Mission erfolgreich seid, werde ich Euch entsprechend belohnen.", progress = "Habt Ihr entdeckt, was die Grimmtotem vorhaben?", completion = "Großes Geistertotem! Das sind wahrlich schlimme Neuigkeiten. Ich muss für alle nur möglichen Fälle Pläne entwickeln.\n\n{name}, wie versprochen ist hier Eure Belohnung für Euren mutigen Dienst.", objectives = "Sucht die drei geheimen Notizen im Düsterwolkengipfel und bringt sie zurück.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[5065] = { id = 5065, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die verlorenen Schrifttafeln von Mosh'aru", description = "Der Troll, mit dem Ihr gesprochen habt, hat Euch nicht die Wahrheit gesagt. Die beiden Schrifttafeln, die Ihr von ihm erhalten habt, sprachen davon, die Essenz von Hakkar zu bewahren, aber an dieser Legende ist noch mehr. Ich habe sie lange studiert und herausgefunden, dass es sechs Schrifttafeln von Mosh'aru gibt, nicht zwei! Sechs!\n\nUnd ich fürchte, dass uns die Geheimnisse, die die anderen enthalten, nicht gefallen werden.\n\nSucht die dritte und vierte Schrifttafel von Mosh'aru. Sie befinden sich in den Östlichen Pestländern, im Besitz der Moosschindertrolle. Sucht sie und bringt sie mir.", progress = "Habt Ihr die Schrifttafeln? Ich fürchte, dass ihre Texte eine große Bedrohung für unsere Welt enthüllen werden.", completion = "Ihr habt sie gefunden! Großartig!\n\nIch danke Euch, {name}. Ich werde diese Texte durchgehen und ihre Bedeutung entschlüsseln.\n\nIhr aber habt eine andere Aufgabe...", objectives = "Bringt Ausgrabungsleiter Ironboot in Tanaris die dritte und vierte Schrifttafel von Mosh'aru.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[5066] = { id = 5066, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Ruf zu den Waffen: Die Pestländer!", description = "Hört her, hört her! Alle Helden werden ersucht, aufzumerken!\n\nDas Königreich Stormwind ruft zu den Waffen! Alle einsatzfähigen Individuen sind hiermit angehalten, gegen die dunkle Bedrohung durch die Geißel in den nördlichen Ländern der östlichen Königreiche zu den Waffen zu greifen! Es gibt Gerüchte über neue Bedrohungen, die sich aus den Ruinen der Pestländer erheben!\n\nHelden der Welt... Sucht Kommandant Ashlam Valorfist auf, der seinen Stützpunkt an der Chillwindspitze errichtet hat, nördlich des Alteracgebirges!", completion = "Willkommen in den Pestländern. Dies ist eine der gefährlichsten Grenzen in Azeroth, besonders aufgrund der sich abzeichnenden Bedrohung durch die Geißel im Norden und Nordosten. Ich bin froh zu hören, dass der Ruf der Pflicht und des Dienstes an der Allgemeinheit bei Euch nicht auf taube Ohren gestoßen ist!\n\nWenn Ihr bereit seid, Eure Hände schmutzig zu machen, gibt es hier am Rand der Pestländer für fähige Helden viel zu tun.", objectives = "Sucht Kommandant Ashlam Valorfist auf. Sein Stützpunkt befindet sich an der Chillwindspitze, nördlich des Alteracgebirges.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[5067] = { id = 5067, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gamaschen von Arcana", description = "Wenn die Herstellung eines solchen Gegenstandes auch noch nie erfolgreich bewerkstelligt wurde, so wird sie doch für möglich erachtet - unter den richtigen Umständen.\n\nSollte der Sucher des Arkanums wünschen, Gamaschen mit immenser Kraft magiezuerfüllen, so muss er Folgendes suchen:\n\n*Einen makellosen Balg der Bestie.\n\n*Ausgefranste Monstrositätenstickereien.\n\n*Arkanitbarren.\n\n*Frostraunens Balsamierungsflüssigkeit.\n\nMERKT AUF!", objectives = "Um die Gamaschen von Arcana herzustellen, müsst Ihr die folgenden Dinge zu Malyfous Darkhammer bringen: 1 makelloser Balg der Bestie; 5 ausgefranste Monstrositätenstickereien; 5 Arkanitbarren; 5 Einheiten Frostraunens Balsamierungsflüssigkeit.\n\nIhr müsst außerdem 50 Goldstücke für die Herstellung des Gegenstandes zahlen.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[5068] = { id = 5068, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brustplatte des Blutdurstes", description = "Es heißt, dass nur eine einzige Brustplatte des Blutdurstes jemals geschaffen wurde und dass sie für die legendäre Auftragsmörderin Garona gemacht wurde. Ob diese Welt jemals eine weitere sehen wird, ist zu bezweifeln.\n\nWie dem auch sei! Unsere meisterlichen Handwerker können den Gegenstand reproduzieren, wenn die notwendigen Komponenten vorhanden sind:\n\n*Ein makelloser Balg der Bestie.\n\n*Ausgefranste Monstrositätenstickereien.\n\n*Arkanitbarren.\n\n*Die Haut des Schattens.\n\nMERKT AUF!", objectives = "Um die Brustplatte des Blutdurstes herzustellen, müsst Ihr die folgenden Dinge zu Malyfous Darkhammer bringen: 1 makelloser Balg der Bestie; 10 ausgefranste Monstrositätenstickereien; 5 Arkanitbarren; 5 Häute des Schattens.\n\nIhr müsst außerdem 50 Goldstücke für die Herstellung des Gegenstandes zahlen.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[5081] = { id = 5081, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Maxwells Mission", description = "Diese Informationen füllen die Lücken in unseren sonst einwandfreien Geheimdienstdaten über die Blackrockspitze.\n\nDer Angriff muss entscheidend sein, {name}.\n\nZuerst muss ihr Kriegsmeister, der Troll Voone, vernichtet werden. Ohne seine Kampfpläne werden die Blackrockorcs im Chaos versinken.\n\nDann müsst Ihr den Ogerhochlord Omokk ausschalten. Die feigen Oger von Blackrock sind ohne seine Führungskraft machtlos.\n\nSchließlich noch der Oberanführer der Zitadelle: Wyrmthalak. Wenn Wyrmthalak tot ist, ist ihre zentrale Kommandoeinheit ohne Leitung.", completion = "Gut gemacht, {name}. Zumindest habt Ihr uns mehr Zeit verschafft - äußerst wertvolle Zeit.", objectives = "Reist zur Blackrockspitze und schaltet Kriegsmeister Voone, Hochlord Omokk und Oberanführer Wyrmthalak aus. Kehrt zu Marshal Maxwell zurück, wenn Eure Aufgabe erledigt ist.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[5082] = { id = 5082, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bedrohung durch die Winterfelle", description = "Ich kam nach Winterspring, um die heißen Quellen von Frostfire zu untersuchen. Mir ist aufgefallen, dass das Wasser... merkwürdige Eigenschaften zu haben scheint. Ich konnte die Quelle aber noch nicht entdecken, und um die Wahrheit zu sagen, hatte ich in letzter Zeit durch die Furbolgs der Winterfelle einige Schwierigkeiten.\n\nSie scheinen von den Quellen angezogen zu werden, genau wie ich. Mittlerweile wachen sie extrem eifersüchtig über das Wasser und lassen mich nicht einmal in die Nähe der beiden größeren Quellen, die von hier aus im Norden liegen.\n\nIch würde meine Studien aber gern fortsetzen. Könntet Ihr mir wohl helfen?", completion = "Ich danke Euch vielmals, {name}! Jetzt kann ich mich hier wieder an die Arbeit machen.\n\nHabt Ihr im Lager der Winterfelle irgendetwas Interessantes gefunden?", objectives = "Donova Snowden in Winterspring möchte, dass Ihr 8 Pfadfinder der Winterfelle, 8 Höhlenbehüter der Winterfelle und 8 Totemiker der Winterfelle erledigt.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[5083] = { id = 5083, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feuerwasser der Winterfelle", description = "Diese Phiole, die Ihr bei den Winterfellfurbolgs aufgehoben habt, ist leer, aber Ihr könnt im Inneren ein paar Tropfen einer merkwürdigen grünen Flüssigkeit sehen; sie scheint fast zu glühen.\n\nIst es etwas Wichtiges?\n\nDonova Snowden könnte Euch wahrscheinlich mehr sagen, da sie nun schon einige Zeit bei den heißen Quellen in Winterspring lagert.", progress = "Was habt Ihr da gefunden?", completion = "Ihr habt dies von den Winterfellfurbolgs?", objectives = "Bringt das leere Feuerwasserfläschchen zu Donova Snowden in Winterspring.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[5084] = { id = 5084, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Verderbnis erliegen", description = "Diese grünliche Flüssigkeit... sie erinnert mich ein wenig an den Schlamm, den ich bei meiner Reise durch den Teufelswald sah. Und ich habe einige Läufer der Winterfelle gesehen, die die Furbolgs der Holzschlundfeste passierten... Vielleicht haben diese Dinge etwas mit dem Fläschchen zu tun, das Ihr gefunden habt, {name}.\n\nEs gibt eine große Gruppe Furbolgs direkt hinter der Holzschlundfeste im Teufelswald. Es ist der so genannte Stamm der Totenwaldfelle. Er wurde durch den Fel verderbt und in den Wahnsinn getrieben. Warum seht Ihr Euch dort nicht um und schaut, ob Ihr Beweise für irgendwelche Beziehungen zwischen den Winterfellfurbolgs und den Totenwaldfellen findet?", completion = "Im Kessel blubbert eine faulige, ekelerregend riechende Substanz...", objectives = "Durchsucht das Furbolglager der Totenwaldfelle im nördlichen Teil des Teufelswalds nach einem Hinweis.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[5085] = { id = 5085, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geheimnisvoller Glibber", description = "Die grünliche Substanz in dem Kessel scheint der zu ähneln, die Ihr in dem Fläschchen gefunden habt. Dieses merkwürdige zähflüssige Zeug könnte genauso verderbt sein wie die Furbolgs, die es geschaffen haben...\n\nFalls die Winterfellfurbolgs es verwenden, bedeutet das, dass sie bald genauso verderbt sein werden wie der Stamm der Totenwaldfelle?\n\nEs wäre das Beste, Donova von Euren Funden zu berichten und ihr eine Probe aus dem Kessel mitzubringen.", progress = "Ich hoffe, Ihr habt etwas gefunden, {name}. Die Winterfelle werden immer aggressiver!", completion = "Ihr seid sehr einfallsreich, {name}. Glaubt Ihr, dass die Furbolgs der Winterfelle im Lager der Totenwaldfelle waren?", objectives = "Berichtet Donova Snowden von Euren Entdeckungen.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[5086] = { id = 5086, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Toxinschrecken", description = "Ich habe die Probe untersucht, die Ihr mitgebracht habt. Ganz sicher bin ich mir nicht, aber ich glaube doch, dass sie Spuren von toxischen Elementen enthält. Die einzige Möglichkeit, das zu bestätigen, besteht darin, einige Proben als Vergleich zu sammeln.\n\nIch glaube, dass sich die Furbolgs der Totenwaldfelle diese Elemente möglicherweise von anderen verderbten Kreaturen im Teufelswald holen, vor allem von den Elementaren, die im Eisenwald leben und Toxinschrecken genannt werden.\n\nSammelt einige Proben zum Vergleich für mich. Aber seid vorsichtig: Es ist dort sehr gefährlich!", progress = "Ich glaube, wir verstehen so langsam, was hier geschieht, {name}.", completion = "Ich muss diese Substanz mit der vergleichen, die Ihr in dem Kessel gefunden habt, und dann werden wir sicherlich mehr wissen.", objectives = "Sammelt 3 Toxinschrecken-Tröpfchen für Donova Snowden in Winterspring.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[5087] = { id = 5087, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Läufer der Winterfelle", description = "Sehr interessant, {name}...\n\nWenn diese toxische Substanz mit dem Wasser aus den heißen Quellen gemischt wird, verliert sie ihre Toxizität und behält lediglich die Fähigkeit zurück, Kreaturen vorübergehend zu beeinflussen, die sie einnehmen. Darum verteidigen die Winterfelle die heißen Quellen wohl so vehement - sie brauchen sie, um ihr Feuerwasser zu läutern.\n\nWir müssen das hier stoppen... den Kontakt zwischen den Winterfellen und den Totenwaldfellen abschneiden. Eine Gruppe von Läufern ist zwischen ihrem Dorf und dem Teufelswald unterwegs. Sucht und besiegt sie und stehlt ihre Lieferung.", progress = "Wir werden ja sehen, was geschieht, wenn die Winterfelle ihr Feuerwasser nicht bekommen!", completion = "<Donova untersucht den Inhalt der Kiste.>\n\nIch frage mich, ob der Verzehr dieser Substanz die Furbolgs aggressiver macht. Sie wirken irgendwie viel größer...", objectives = "Sucht die Läufer der Winterfelle und hindert sie daran, ihre Lieferung zum Lager der Winterfelle zu bringen.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[5088] = { id = 5088, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arikara", description = "Bringt dieses aufbereitete und geläuterte Brandpulver nach Tausend Nadeln und werft es in das hochheilige Feuer des Lebens. Es befindet sich beim Düsterwolkengipfel auf einer isolierten Nadel, wo sie ihre Toten beerdigen.\n\nDie Verzauberung, die ich in das Brandpulver eingewoben habe, wird Arikara für Euch beschwören, {name}.\n\nIch fürchte, dass sie Cairne Bloodhoof bedrohen könnte; die Lehren der Tauren haben sich zu sehr verändert und möglicherweise ist Arikara darüber erzürnt. Tut schnell etwas, bevor alles verloren ist, {class}!", progress = "Habt Ihr die heimtückische Schlange Arikara erschlagen, {name}?", completion = "Das ergibt keinen Sinn. Warum sollte Arikara hinter Cairne Bloodhoof her sein? Magatha kann sich nicht irren, sie ist unsere mächtigste Schamanin.\n\n<Motega schüttelt seinen Kopf.>\n\nWie dem auch sei, Eure große Tat für die Horde soll nicht unbemerkt bleiben - wählt bitte einen dieser Gegenstände als Belohnung für Eure Hilfe.", objectives = "Erschlagt Arikara. Bringt ihre Überreste und das Brandpulver zu Motega Firemane im Weißgipfelposten als Beweis für Eure Tat.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[5089] = { id = 5089, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "General Drakkisaths Befehl", description = "Dem Kadaver der besiegten Schlange entnehmt Ihr etwas, das wie ein Schreiben von einiger Bedeutung aussieht. Es ist ein Brief des Vorgesetzten, General Drakkisath, bezüglich des Protokolls.\n\nEuer Instinkt sagt Euch, dass Ihr ihn zu Marshal Maxwell bringen solltet.", progress = "Was habt Ihr denn da, {name}?", completion = "Es wird spannend...", objectives = "Bringt den Befehl von General Drakkisath zu Marshal Maxwell in der brennenden Steppe.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[5090] = { id = 5090, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Ruf zu den Waffen: Die Pestländer!", description = "Hört her, hört her! Alle Helden werden ersucht, aufzumerken!\n\nDas Königreich Stormwind ruft zu den Waffen! Alle einsatzfähigen Individuen sind hiermit angehalten, gegen die dunkle Bedrohung durch die Geißel in den nördlichen Ländern der östlichen Königreiche zu den Waffen zu greifen! Es gibt Gerüchte über neue Bedrohungen, die sich aus den Ruinen der Pestländer erheben!\n\nHelden der Welt... Sucht Kommandant Ashlam Valorfist auf, der seinen Stützpunkt an der Chillwindspitze errichtet hat, nördlich des Alteracgebirges!", completion = "Willkommen in den Pestländern. Dies ist eine der gefährlichsten Grenzen in Azeroth, besonders aufgrund der sich abzeichnenden Bedrohung durch die Geißel im Norden und Nordosten. Ich bin froh zu hören, dass der Ruf der Pflicht und des Dienstes an der Allgemeinheit bei Euch nicht auf taube Ohren gestoßen ist!\n\nWenn Ihr bereit seid, Eure Hände schmutzig zu machen, gibt es hier am Rand der Pestländer für fähige Helden viel zu tun.", objectives = "Sucht Kommandant Ashlam Valorfist auf. Sein Stützpunkt befindet sich an der Chillwindspitze, nördlich des Alteracgebirges.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[5091] = { id = 5091, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Ruf zu den Waffen: Die Pestländer!", description = "Hört her, hört her! Alle Helden werden ersucht, aufzumerken!\n\nDas Königreich Stormwind ruft zu den Waffen! Alle einsatzfähigen Individuen sind hiermit angehalten, gegen die dunkle Bedrohung durch die Geißel in den nördlichen Ländern der östlichen Königreiche zu den Waffen zu greifen! Es gibt Gerüchte über neue Bedrohungen, die sich aus den Ruinen der Pestländer erheben!\n\nHelden der Welt... Sucht Kommandant Ashlam Valorfist auf, der seinen Stützpunkt an der Chillwindspitze errichtet hat, nördlich des Alteracgebirges!", completion = "Willkommen in den Pestländern. Dies ist eine der gefährlichsten Grenzen in Azeroth, besonders aufgrund der sich abzeichnenden Bedrohung durch die Geißel im Norden und Nordosten. Ich bin froh zu hören, dass der Ruf der Pflicht und des Dienstes an der Allgemeinheit bei Euch nicht auf taube Ohren gestoßen ist!\n\nWenn Ihr bereit seid, Eure Hände schmutzig zu machen, gibt es hier am Rand der Pestländer für fähige Helden viel zu tun.", objectives = "Sucht Kommandant Ashlam Valorfist auf. Sein Stützpunkt befindet sich an der Chillwindspitze, nördlich des Alteracgebirges.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[5092] = { id = 5092, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Weg räumen", description = "Da die westlichen und nördlichen Straßen in die Stadt von Andorhal gut befestigt sind, habe ich vor, über die weniger gut verteidigte östliche Straße anzugreifen. Die Geißel verlässt sich auf den Puffer von Untoten, die Sorrow Hill heimsuchen, als erste Verteidigungslinie. Wenn wir nach Andorhal vordringen wollen, müssen wir es über Sorrow Hill tun.\n\nEure erste Aufgabe besteht darin, den Weg durch Sorrow Hill zu säubern. Dünnt die Masse der Skelette und Ghuls aus, die das Gebiet heimsuchen. Meldet Euch wieder bei mir, wenn das erledigt ist!", completion = "Mission erfüllt, {name}! Das war sehr gut gespielt.\n\nErlaubt mir, Eure bisherige Arbeit mit einigen Münzen aus dem Staatsschatz von Stormwind zu belohnen. Ich empfehle Euch, es für Material auszugeben, das Euch bei der nächsten Mission helfen wird... einer, die Euch in die Ruinen von Andorhal hineinführen wird.\n\nSeid bereit! Seid wachsam!", objectives = "Tötet 10 Skelettschinder und 10 sabbernde Ghuls in Sorrow Hill.\n\nKehrt zu Kommandant Ashlam Valorfist an der Chillwindspitze, Westliche Pestländer, zurück.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[5093] = { id = 5093, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Ruf zu den Waffen: Die Pestländer!", description = "Helden der Welt, höret mich - die Horde ruft zum schnellen Aufmarsch!\n\nAlle einsatzfähigen Personen werden zu den Waffen gerufen, um gegen die Geißel zu ziehen! Es gibt Gerüchte über neue Bedrohungen, die sich aus den Ruinen der östlichen Königreiche erheben! Sie lauern östlich von Undercity, in den nördlichen Ausläufern der Länder, die als Pestländer bekannt sind!\n\nHelden der Welt - sucht Hochexekutor Derrington auf. Er hat seinen Stützpunk am Bollwerk östlich von Tirisfal aufgeschlagen!", completion = "Willkommen in den Pestländern. Dies ist eine der gefährlichsten Grenzen in Azeroth, vor allem aufgrund der sich abzeichnenden Bedrohung durch die Geißel im Osten und noch weiter östlich. Ich bin froh zu hören, dass der Ruf der Pflicht und des Dienstes für die Horde bei Euch nicht auf taube Ohren gestoßen ist!\n\nWenn Ihr bereit seid, Eure Hände schmutzig zu machen, gibt es hier am Rand der Pestländer für fähige Helden viel zu tun.", objectives = "Sucht Hochexekutor Derrington auf. Sein Stützpunk befindet sich am Bollwerk, östlich von Tirisfal und Undercity.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[5094] = { id = 5094, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Ruf zu den Waffen: Die Pestländer!", description = "Helden der Welt, höret mich - die Horde ruft zum schnellen Aufmarsch!\n\nAlle einsatzfähigen Personen werden zu den Waffen gerufen, um gegen die Geißel zu ziehen! Es gibt Gerüchte über neue Bedrohungen, die sich aus den Ruinen der östlichen Königreiche erheben! Sie lauern östlich von Undercity, in den nördlichen Ausläufern der Länder, die als Pestländer bekannt sind!\n\nHelden der Welt - sucht Hochexekutor Derrington auf. Er hat seinen Stützpunk am Bollwerk östlich von Tirisfal aufgeschlagen!", completion = "Willkommen in den Pestländern. Dies ist eine der gefährlichsten Grenzen in Azeroth, vor allem aufgrund der sich abzeichnenden Bedrohung durch die Geißel im Osten und noch weiter östlich. Ich bin froh zu hören, dass der Ruf der Pflicht und des Dienstes für die Horde bei Euch nicht auf taube Ohren gestoßen ist!\n\nWenn Ihr bereit seid, Eure Hände schmutzig zu machen, gibt es hier am Rand der Pestländer für fähige Helden viel zu tun.", objectives = "Sucht Hochexekutor Derrington auf. Sein Stützpunk befindet sich am Bollwerk, östlich von Tirisfal und Undercity.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[5095] = { id = 5095, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Ruf zu den Waffen: Die Pestländer!", description = "Ihr Helden dieser Welt, höret mich - die Horde ruft zum schnellen Aufmarsch!\n\nAlle einsatzfähigen Personen werden zu den Waffen gerufen, um gegen die Geißel zu ziehen! Es gibt Gerüchte über neue Bedrohungen, die sich aus den Ruinen der östlichen Königreiche erheben! Sie lauern östlich von Undercity, in den nördlichen Ausläufern der Länder, die als Pestländer bekannt sind!\n\nZögert nicht lange, ihr Helden! Sucht Hochexekutor Derrington auf! Er hat seinen Stützpunk am Bollwerk östlich von Tirisfal aufgeschlagen.", completion = "Willkommen in den Pestländern. Dies ist eine der gefährlichsten Grenzen in Azeroth, vor allem aufgrund der sich abzeichnenden Bedrohung durch die Geißel im Osten und noch weiter östlich. Ich bin froh zu hören, dass der Ruf der Pflicht und des Dienstes für die Horde bei Euch nicht auf taube Ohren gestoßen ist!\n\nWenn Ihr bereit seid, Eure Hände schmutzig zu machen, gibt es hier am Rand der Pestländer für fähige Helden viel zu tun.", objectives = "Sucht Hochexekutor Derrington auf. Sein Stützpunk befindet sich am Bollwerk, östlich von Tirisfal und Undercity.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[5096] = { id = 5096, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scharlachrote Ablenkung", description = "Vor Andorhal müssen wir die Bedrohung durch den anrückenden Scharlachroten Kreuzzug von Hearthglen niederschlagen. Dessen Lager wurde zwischen dem Teufelssteinfeld und Dalsons Tränenfeld aufgeschlagen, wodurch wir gleichzeitig einen Konflikt mit der Geißel und dem Kreuzzug riskieren müssen.\n\nMein Plan ist, sie gegeneinander auszuspielen, indem wir Euch schicken, um das Kommandozelt zu zerstören, das sie errichtet haben. Benutzt dazu die Flaschenflammen aus dieser Kiste mit Brandsätzen. Sobald es vernichtet ist, richtet Ihr dieses Banner der Geißel bei dem Zelt auf. Mit etwas Glück werden sie uns ignorieren und sich auf Rache gegen die Geißel konzentrieren.", progress = "Ein Überraschungsangriff auf die schwache Vorhut des Scharlachroten Kreuzzugs wird uns genügend Zeit verschaffen, um gen Andorhal zu marschieren. Ich erwarte, dass Ihr von Eurem Erfolg berichten wollt!\n\nNachdem dies erfolgreich ausgeführt ist, müssen wir sorgfältig und schnell sein. Wir haben weder das Material noch die Männer, um sowohl die Geißel als auch den Scharlachroten Kreuzzug gleichzeitig zu bekämpfen, wenn sie unserem kleinen Trick nicht glauben.", completion = "Das habt Ihr hervorragend gemacht, {name}! Euer Angriff auf den Scharlachroten Kreuzzug wird uns Zeit verschaffen. Ich habe einen meiner besten Späher geschickt, um das Lager zu beobachten und sicherzustellen, dass die Kräfte des Kreuzzugs, die zur Verstärkung der Position anrücken, den Köder schlucken.\n\nNachdem sich der Druck auf uns verringert hat, sollten wir dann eine Mission nach Andorhal riskieren können und eine wichtige noch dazu. Ich möchte gern, dass Ihr auch diese ausführt, da Ihr bisher so erfolgreich wart.", objectives = "Zieht zum Basislager des Scharlachroten Kreuzzugs zwischen dem Teufelssteinfeld und Dalsons Tränenfeld und zerstört sein Kommandozelt.\n\nLasst das Banner der Geißel im Lager wehen und kehrt dann zu Hochexekutor Derrington am Bollwerk in den Westlichen Pestländern zurück.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[5097] = { id = 5097, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Turm um Turm", description = "Durch die Verwendung eines magischen Gegenstandes, einer Signalfackel, können wir Ziele unserer Wahl für künftige Aktionen durch unsere Truppen markieren. Was das angeht, glauben wir, dass die Geißel die Wachtürme von Andorhal nutzt, um die Bewegungen ihrer Truppen zu kontrollieren.\n\nEure Mission: Durchbrecht die Verteidigung von Andorhal, um Signalfackeln an allen vier Wachtürmen zu platzieren. Ihr müsst im Eingang eines jeden Turmes stehen, um das Signal zu platzieren; es wird dann den Turm markieren. Die Signalfackel hat nur fünf Ladungen, nutzt sie also weise!", progress = "Wenn die Türme markiert sind, werden sie zu Zielen der obersten Priorität für unseren Angriff auf Andorhal. Ich vermute, dass die Hauptbedrohung von Andorhal auftauchen wird, wenn wir die Türme neutralisiert haben. Von dem Punkt an gibt es einen offenen Kampf um die Kontrolle der Stadt!\n\nIhr seid zurück, um von Eurem Erfolg zu berichten, ja? Vergesst nicht die Signalfackel, wir müssen die Kontrolle über unser Material bewahren.", completion = "Meine Priester melden, dass unsere Signalsucher extrem starke Signale von allen vier Türmen empfangen! Ich wage zu sagen, dass Ihr eine weitere Mission mit umfassendem und absolutem Erfolg ausgeführt habt! Erneut gut gespielt, {name}!\n\nMit der Markierung der Türme sind unsere Angriffsvorbereitungen jetzt abgeschlossen. Die Zeit ist gekommen, um den Kampf zur Geißel zu bringen!", objectives = "Markiert mit der Signalfackel jeden Turm in Andorhal; Ihr müsst im Eingang jedes Turmes stehen, um ihn erfolgreich zu markieren.\n\nWenn alle vier Türme markiert sind, bringt Ihr die Signalfackel zu Kommandant Ashlam Valorfist an der Chillwindspitze, Westliche Pestländer, zurück.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[5098] = { id = 5098, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Turm um Turm", description = "Durch die Verwendung eines magischen Gegenstandes, einer Signalfackel, können wir Ziele unserer Wahl für künftige Aktionen durch unsere Truppen markieren. Was das angeht, glauben wir, dass die Geißel die Wachtürme von Andorhal nutzt, um die Bewegungen ihrer Truppen zu kontrollieren.\n\nEure Mission: Durchbrecht die Verteidigung von Andorhal, um Signalfackeln an allen vier Wachtürmen zu platzieren. Ihr müsst im Eingang eines jeden Turmes stehen, um das Signal zu platzieren; es wird dann den Turm markieren. Die Signalfackel hat nur fünf Ladungen, nutzt sie also weise!", completion = "Meine Hexenmeister melden, dass unsere Signalsucher extrem starke Signale von allen vier Türmen empfangen! Ihr habt meine Befehle mit dem Geschick und der Präzision eines erfahrenen Veterans ausgeführt. Euer Dienst an der Horde wird einmal mehr aufmerksam notiert, {name}!\n\nMit der Markierung der Türme sind unsere Angriffsvorbereitungen jetzt abgeschlossen. Die Zeit ist gekommen, um den Kampf zur Geißel zu bringen!", objectives = "Markiert mit der Signalfackel jeden Turm in Andorhal; Ihr müsst im Eingang jedes Turmes stehen, um ihn erfolgreich zu markieren.\n\nWenn alle vier Türme markiert sind, bringt Ihr die Signalfackel zu Hochexekutor Derrington am Bollwerk, Westliche Pestländer, zurück.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[5102] = { id = 5102, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "General Drakkisaths Niedergang", description = "Wir kämpfen an zwei Fronten gegen diese Biester: Von unserer Hauptstadt Stormwind aus bekämpfen wir sie von innen, und hier, in der brennenden Steppe, tragen wir den Kampf an ihre Türschwelle. Wir müssen wachsam sein, {name}. Niemand soll von unserem Zorn verschont werden, da keiner der Unseren verschont wurde, als der Feind bei unseren Heimen und Familien zuschlug.\n\nFindet diesen General Drakkisath und erledigt ihn!\n\nDie Aufgabe ist sicherlich nicht einfach, aber die Belohnungen werden großartig sein.", completion = "Wir werden bestimmt als Nächstes gegen ihre Großdrachenlords ziehen. Gut gemacht, mutiger Soldat der Allianz! Wirklich hervorragend.", objectives = "Begebt Euch zur Blackrockspitze und schaltet General Drakkisath aus. Kehrt zu Marshal Maxwell zurück, wenn Eure Aufgabe erledigt ist.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[5103] = { id = 5103, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heißer, feuriger Tod", description = "Das Einzige, was von diesem Menschen übrig geblieben ist, sind einige verkohlte Knochen. Er scheint in Armeslänge dessen gestorben zu sein, hinter dem er her war - ungebrannten Plattenstulpen.\n\nVielleicht solltet Ihr die Stulpen nehmen und aus dem Feuer verschwinden?", completion = "Was zum...", objectives = "Jemand auf dieser Welt muss doch wissen, was mit diesen Stulpen zu tun ist. Viel Glück!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[5121] = { id = 5121, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Oberhäuptling der Winterfelle", description = "Wir wissen leider immer noch nicht, warum die Furbolgs diese merkwürdige Substanz einnehmen. Aber ich glaube, es wäre das Beste, das zu unterbinden, bevor es ausufert.\n\nDie Furbolgs der Winterfelle sind normalerweise kein aggressiver Stamm und diese Änderung ihres Verhaltens führt mich zu der Annahme, dass sie Befehle ihres Häuptlings ausführen. Wir werden wohl den Schaden, der bereits angerichtet ist, nicht mehr beheben können, aber ich denke, wenn ihr Anführer erledigt ist, wird es zumindest nicht schlimmer werden.\n\nBegebt Euch nach Osten zum Lager der Winterfelle.", completion = "Vielen herzlichen Dank, {name}. Ich hoffe zu meinen Studien zurückkehren zu können, ohne Angst, dass ich in einen Hinterhalt gerate. Nehmt dies bitte als Belohnung.", objectives = "Donova Snowden in Winterspring möchte, dass Ihr den Oberhäuptling der Winterfelle besiegt.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[5122] = { id = 5122, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Medaillon des Glaubens", progress = "Die Macht dieser Kapelle gibt mir die Kraft, der Verderbnis in meinem Herzen zu widerstehen. Wenn ich sie verlasse, werde ich zu einem Todesritter. Aber es gibt ein Medaillon, das Medaillon des Glaubens, das mir so viel Kraft geben wird, dass ich trotzdem gehen kann.\n\nBitte, {name}, findet das Medaillon für mich. Es wird von Malor dem Eifrigen bewacht, einem wahnsinnigen Mitglied der Scharlachroten Bruderschaft. Er lebt tief in der scharlachroten Bastion im westlichen Stratholme.", completion = "Ihr habt das Medaillon bekommen! Jetzt kann ich die Kapelle verlassen und meine Pflicht erfüllen.\n\nDiese Pflicht besteht darin, die Bestie zu töten, die dabei half, mich und so viele meiner Brüder und Schwestern zu verderben: Baron Rivendare!" }
quests[5123] = { id = 5123, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das letzte Stück", description = "Das Logbuch, das Ihr bei dem Oberhäuptling gefunden habt, scheint recht ausführlich zu sein, aber nachdem Ihr einige Seiten durchgesehen habt, stellt Ihr fest, dass Ihr den Text nicht lesen könnt. Die Zeichen sind so kunstlos und schlecht geformt, dass Ihr nicht sicher seid, ob überhaupt jemand sie lesen kann.\n\nAber vielleicht kann Donova Euch sagen, was sie bedeuten ...", progress = "Was habt Ihr da, {name}?", completion = "Ich frage mich, was das alles bedeutet... Ich kann mir keinen Reim darauf machen...", objectives = "Bringt das kunstlos geschriebene Logbuch zu Donova Snowden in Winterspring.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[5124] = { id = 5124, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feurige Plattenstulpen", description = "Beim Barte Thaurissans!\n\nWo habt Ihr sie gefunden?\n\nNoch wichtiger: Seid Ihr bereit, Euch von ihnen zu trennen? Natürlich würde ich solch eine noble Geste belohnen.\n\nIch sag Euch was, {name}. Wenn Ihr mir diese ungebrannten Stulpen gebt, werde ich Euch beibringen, wie Ihr selbst welche herstellen könnt. Ihr müsst nur die Teile für mich besorgen, damit ich das genaue Rezept benutzen kann.\n\nAbgemacht?\n\nHier ist die Liste dessen, was ich benötige. Ich werde das nicht-verzauberte Thorium selbst übernehmen, da Ihr ja die Stulpen liefert.", progress = "Zeit ist Geld, {name}, und ich habe von beidem nicht viel.", completion = "Wie versprochen, {name}, hier ist Euer Rezept! Ich werde Euch für Eure harte Arbeit und Hingabe außerdem noch etwas extra geben. Was sollte ich sonst mit dem Zeug hier tun...", objectives = "Bringt Malyfous Darkhammer 6 verzauberte Thoriumbarren, 2 Essenzen des Feuers und 4 Sternrubine. Ihr müsst außerdem Eure ungebrannten Plattenstulpen abgeben.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[5125] = { id = 5125, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aurius' Abrechnung", sourceObjective = "{name}, ich sterbe... aber meine Seele ist gerettet. Dafür schulde ich Euch mehr, als man mit Worten ausdrücken kann. Bitte, nehmt dies... und kämpft weiter so mutig, {class}!", sourceObjectiveStatus = "unverified-source-field" }
quests[5126] = { id = 5126, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lorax' Geschichte", description = "Der Satyr wandert auf und ab und spricht mit sich selbst. Möchtet Ihr ihn ansprechen?", completion = "<Lorax lacht.>", objectives = "Sprecht mit Lorax. Hört, was er zu sagen hat.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[5127] = { id = 5127, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Dämonenschmiede", description = "Lorax macht Geschäfte, aber er akzeptiert sie nicht von unbedeutenden Sterblichen.\n\nEinen Handel kann ich aber mit Euch machen... nehmt diese Pike, sie ist mit mächtigen Fel-Energien getränkt. Wenn Ihr Goraluk Hammerbruch findet, erschlagt ihn und treibt diese Pike durch sein sterbendes Herz. Er hat seine Seele verschachert und daher werde ich seine Seele bekommen. Bringt die Pike und die Brustplatte zurück, die der Dieb gestohlen hat, und ich werde Euch das beibringen, was er lernen sollte.", progress = "Seid nicht versucht...", completion = "Unseren Pakt habt Ihr nicht gebrochen. Die Seele nahm ich. Die Belohnung werde ich geben.", objectives = "Begebt Euch zur Blackrockspitze und sucht Goraluk Hammerbruch. Erschlagt ihn und wendet dann die blutbefleckte Pike auf seine Leiche an. Nachdem seine Seele abgesaugt wurde, wird die Pike seelenbefleckt sein.\n\nIhr müsst außerdem die ungeschmiedete runenbedeckte Brustplatte finden.\n\nBringt die seelenbefleckte Pike und die ungeschmiedete runenbedeckte Brustplate zu Lorax in Winterspring.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[5128] = { id = 5128, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Worte des Oberhäuptlings", description = "Die Winterfelle sind für mich keine Bedrohung mehr, aber wenn Ihr immer noch herausfinden möchtet, was die Furbolgs dazu brachte, dieses merkwürdige Feuerwasser herzustellen und zu konsumieren, solltet Ihr Kelek Skykeeper aufsuchen.\n\nEr gehört zu einer Gruppe, die als Smaragdkreis bekannt ist, Druiden, die sich ihrer Arbeit im Teufelswald widmen und das Land von der Verderbnis heilen.\n\nKelek hat viel Erfahrung mit den Furbolgs im Teufelswald und kann Euch vielleicht mehr über das Logbuch sagen.\n\nNochmals danke, {name}.", progress = "Der Smaragdkreis ist allen freundlich gesinnt, {race}. Was kann ich für Euch tun?", completion = "Ja, wenn Ihr es mich eine Weile untersuchen lasst, kann ich es für Euch vielleicht übersetzen.\n\n<Kelek blättert durch die Seiten.>\n\nWenn ich es ganz durchgesehen habe, werde ich Euch eine Nachricht schicken.\n\nDanke, dass Ihr dies mit mir teilt, {name}. Man weiß sehr wenig über die Winterfellfurbolgs.", objectives = "Bringt das kunstlos geschriebene Logbuch zu Kelek Skykeeper im südlichen Teil des Teufelswalds.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[5141] = { id = 5141, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drachenlederverarbeitung", description = "Drachenlederverarbeitung ist nicht einfach, aber sie ist sehr einträglich. Ich werde Euch beibringen, wie man diese feine Panzerrüstung fertigt, aber nur, wenn Ihr bestimmten Bedingungen zustimmt.\n\nMit der Wahl dieses Weges erklärt Ihr Euch einverstanden, niemals die Kunst der Elementarlederverarbeitung oder der Stammeslederverarbeitung zu erlernen. An der Spitze des Handwerks ist nur Platz für eine der drei. Des Weiteren werde ich eine Probe Eurer besten Arbeit aus dem Bereich der Skorpidrüstung benötigen. Schließlich benötige ich noch einen Beweis für Eure Fähigkeit, die Hauptzutat des Handwerks zu erlangen: Schuppen der Drachkin.", progress = "Wenn Ihr bereit seid, eine dauerhafte Entscheidung zu treffen, indem Ihr ein Drachenlederer werdet, dann bin ich bereit, Euch als Schüler aufzunehmen. Bringt mir einfach die Dinge, um die ich gebeten habe und wir werden mit Eurer Ausbildung beginnen.", completion = "Ich muss Euch loben... es bedarf eines starken Willens, eine dauerhafte Entscheidung zu treffen, wie Ihr es gerade getan habt. Ich versichere Euch, Drachenlederverarbeitung wird sich als profitabler und lohnender Weg für Euch erweisen.\n\nUm in Zukunft die Kunst zu trainieren, sprecht einfach mit mir, und ich werde Euch das Wissen verfügbar machen, das Ihr noch als das Eure erwerben müsst.", objectives = "Bringt 2 feste Skorpidbrustplatten, 2 feste Skorpidhandschuhe und 10 Drachenschuppen zu Peter Galen in Azshara.\n\nWenn Ihr diese Aufgabe abschließt, werdet Ihr Zugang zur Kunst der Drachenlederverarbeitung erhalten.\n\nIhr könnt dann allerdings weder Elementarlederverarbeitung noch Stammeslederverarbeitung erlernen; seid also vorher sicher, dass dies der Weg ist, dem Ihr folgen wollt.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[5142] = { id = 5142, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Klein-Pamela", description = "So viele von uns sind im Kampf von Darrowshire gefallen. So viele starben... und noch Schlimmeres.\n\nAls die Schlacht begann, versteckte ich meine Nichte Pamela, und ich weiß nicht, was mit ihr geschehen ist. Ich bin nur ein wandernder Geist, aber mein Herz möchte dennoch Pamelas Schicksal kennen.\n\nBitte, {class}. Könnt Ihr nach Darrowshire gehen und nach ihr suchen? Es liegt im Osten, hinter Gahrrons Trauerfeld.", completion = "Hallo. Ich bin Pamela, und wie heißt Ihr?", objectives = "Sucht Pamela Redpath.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[5143] = { id = 5143, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stammeslederverarbeitung", description = "Um die Kunst der Stammeslederverarbeitung zu erlernen, müsst Ihr verstehen, wie urzeitlich die Natur wirklich ist; ich weiß, dass Ihr bereits die Kunst der Herstellung von Wildlederrüstungen gemeistert habt, und ich bin bereit, Eure Ausbildung abzuschließen.\n\nDoch wisset dies, {class}: Durch die Wahl dieses Weges erklärt Ihr Euch einverstanden, niemals die Kunst der Drachenlederverarbeitung oder der Elementarlederverarbeitung zu erlernen. Ihr könnt nur eine dieser drei Künste erlernen. Bringt mir des Weiteren die feinsten Proben Eurer Wildlederrüstungen. Von diesem Punkt aus werden wir dann beginnen, an Eurem Können zu arbeiten.", progress = "Die Natur ist eine Kraft, die besänftigt werden muss, bevor Ihr hoffen könnt zu lernen, wie ihr Wille für Eure Ledergewänder zu beugen ist. Bringt mir Euer Geschenk für diese Kraft und ich werde sicherstellen, dass Ihr erhört werdet.", completion = "Ihr habt Eure besten Geschenke gebracht und die Natur wird bald zulassen, dass Ihr sie Eurem Willen entsprechend beugt. Wenn ich meine Unterweisung beendet habe, wird Eure Arbeit eine Naturgewalt in sich selbst sein.\n\nUm in Zukunft die Kunst zu trainieren, sprecht einfach mit mir, und ich werde Euch das Wissen verfügbar machen, das Ihr noch als das Eure erwerben müsst.", objectives = "Bringt eine Wildlederweste und einen Wildlederhelm zu Caryssia Moonhunter in Feralas.\n\nWenn Ihr diese Aufgabe abschließt, werdet Ihr Zugang zur Kunst der Stammeslederverarbeitung erhalten.\n\nWenn Ihr diese Aufgabe abschließt, werdet Ihr allerdings weder Drachenlederverarbeitung noch Elementarlederverarbeitung erlernen können; seid also vorher sicher, dass dies der Weg ist, dem Ihr folgen wollt.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[5144] = { id = 5144, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elementarlederverarbeitung", description = "Elementarlederverarbeitung ist, was ich kann, und wenn Ihr bereit seid, Eure Gedanken den größeren Mächten der Substanz zu öffnen, werde ich mit Euch alles teilen, was es zu lernen gibt.\n\nDoch wisset dies, {class}: Durch die Wahl dieses Weges erklärt Ihr Euch einverstanden, niemals die Kunst der Drachenlederverarbeitung oder der Stammeslederverarbeitung zu erlernen. Ihr könnt nur eine dieser drei Künste erlernen. Des Weiteren benötige ich einen angemessenen Beweis, dass Ihr im Einklang mit den Elementen der Natur steht. Bringt mir dafür die reinsten Essenzen von Feuer, Wasser, Erde und Wind.", progress = "Für die Herstellung dieser Art von lederner Rüstung bedarf es der Geduld und der Hingabe. Wenn Ihr Euch einmal auf die Elemente eingelassen habt, gibt es kein Zurück mehr. Bringt mir einen Beweis Eures Wertes und wir werden beginnen.", completion = "Ihr habt Eure Entscheidung getroffen und die Elemente akzeptieren Euch. Wenn ich meine Unterweisung beendet habe, werdet Ihr die Willenskraft haben, die feinsten Ledergewänder zu fertigen.\n\nUm in Zukunft die Kunst zu trainieren, sprecht einfach mit mir, und ich werde Euch das Wissen verfügbar machen, das Ihr noch als das Eure erwerben müsst.", objectives = "Bringt 2 Herzen des Feuers, 2 Kugeln des Wassers, 2 Erdenkerne und 2 Odem des Windes zu Sarah Tanner in die sengende Schlucht.\n\nWenn Ihr diese Aufgabe abschließt, werdet Ihr Zugang zur Kunst der Elementarlederverarbeitung erhalten.\n\nWenn Ihr diese Aufgabe abschließt, werdet Ihr allerdings weder Drachenlederverarbeitung noch Stammeslederverarbeitung erlernen können; seid also vorher sicher, dass dies der Weg ist, dem Ihr folgen wollt.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[5145] = { id = 5145, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drachenlederverarbeitung", description = "Drachenlederverarbeitung ist nicht einfach, aber sie ist sehr einträglich. Ich werde Euch beibringen, wie man diese feine Panzerrüstung fertigt, aber nur, wenn Ihr bestimmten Bedingungen zustimmt.\n\nMit der Wahl dieses Weges erklärt Ihr Euch einverstanden, niemals die Kunst der Elementarlederverarbeitung oder der Stammeslederverarbeitung zu erlernen. An der Spitze des Handwerks ist nur Platz für eine der drei. Des Weiteren werde ich eine Probe Eurer besten Arbeit aus dem Bereich der Skorpidrüstung benötigen. Schließlich benötige ich noch einen Beweis für Eure Fähigkeit, die Hauptzutat des Handwerks zu erlangen: Schuppen der Drachkin.", progress = "Wenn Ihr bereit seid, eine dauerhafte Entscheidung zu treffen, indem Ihr ein Drachenlederer werdet, dann bin ich bereit, Euch als Schüler aufzunehmen. Bringt mir einfach die Dinge, um die ich gebeten habe, und wir werden mit Eurer Ausbildung beginnen.", completion = "Ich muss Euch loben... es bedarf eines starken Willens, eine dauerhafte Entscheidung zu treffen, wie Ihr es gerade getan habt. Ich versichere Euch, Drachenlederverarbeitung wird sich als profitabler und lohnender Weg für Euch erweisen.\n\nUm in Zukunft die Kunst zu trainieren, sprecht einfach mit mir, und ich werde Euch das Wissen verfügbar machen, das Ihr noch als das Eure erwerben müsst.", objectives = "Bringt 2 feste Skorpidbrustplatten, 2 feste Skorpidhandschuhe und 10 Drachenschuppen zu Thorkaf Dragoneye im Ödland.\n\nWenn Ihr diese Aufgabe abschließt, werdet Ihr Zugang zur Kunst der Drachenlederverarbeitung erhalten.\n\nIhr könnt dann allerdings weder Elementarlederverarbeitung noch Stammeslederverarbeitung erlernen; seid also vorher sicher, dass dies der Weg ist, dem Ihr folgen wollt.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[5146] = { id = 5146, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elementarlederverarbeitung", description = "Elementarlederverarbeitung ist, was ich kann, und wenn Ihr bereit seid, Eure Gedanken den größeren Mächten der Substanz zu öffnen, werde ich mit Euch alles teilen, was es zu lernen gibt.\n\nDoch wisset dies, {class}: Durch die Wahl dieses Weges erklärt Ihr Euch einverstanden, niemals die Kunst der Drachenlederverarbeitung oder der Stammeslederverarbeitung zu erlernen. Ihr könnt nur eine dieser drei Künste erlernen. Des Weiteren benötige ich einen angemessenen Beweis, dass Ihr im Einklang mit den Elementen der Natur steht. Bringt mir dafür die reinsten Essenzen von Feuer, Wasser, Erde und Wind.", progress = "Für die Herstellung dieser Art von lederner Rüstung bedarf es der Geduld und der Hingabe. Wenn Ihr Euch einmal auf die Elemente eingelassen habt, gibt es kein Zurück mehr. Bringt mir einen Beweis Eures Wertes und wir werden beginnen.", completion = "Ihr habt Eure Entscheidung getroffen und die Elemente akzeptieren Euch. Wenn ich meine Unterweisung beendet habe, werdet Ihr die Willenskraft haben, die feinsten Ledergewänder zu fertigen.\n\nUm in Zukunft die Kunst zu trainieren, sprecht einfach mit mir, und ich werde Euch das Wissen verfügbar machen, das Ihr noch als das Eure erwerben müsst.", objectives = "Bringt 2 Herzen des Feuers, 2 Kugeln des Wassers, 2 Erdenkerne und 2 Odem des Windes zu Brumn Winterhoof in den Arathi-Bergen.\n\nWenn Ihr diese Aufgabe abschließt, werdet Ihr Zugang zur Kunst der Elementarlederverarbeitung erhalten.\n\nWenn Ihr diese Aufgabe abschließt, werdet Ihr allerdings weder Drachenlederverarbeitung noch Stammeslederverarbeitung erlernen können; seid also vorher sicher, dass dies der Weg ist, dem Ihr folgen wollt.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[5147] = { id = 5147, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GESUCHT: Arnak Grimmtotem", description = "Gesucht: Arnak Grimmtotem\n\nArnak der Ausgestoßene wird wegen ruchloser Verbrechen des Mordes und der Entführung gesucht. Ansehnliche Belohnungen winken dem, der mutig genug ist, diesen Verbrecher der Gerechtigkeit zuzuführen.\n\nArnak wurde zuletzt auf den Klippen in der Nähe des Düsterwolkengipfels gesehen. Zeigt dem Klippenbehüter Longhorn im Freiwindposten den Beweis Eurer Tat, um die Belohnung zu beanspruchen.", progress = "Habt Ihr Neuigkeiten über diesen mordlustigen Arnak Grimmtotem?", completion = "Ha! Na, das sind doch ausgezeichnete Neuigkeiten! Ich dachte langsam, er würde nie der Gerechtigkeit zugeführt werden!\n\nHier, bitte schön, {name}... und vielen Dank. Die Neuigkeiten von Arnaks widerlichen Taten brachten mein Blut zum Sieden!", objectives = "Erschlagt Arnak Grimmtotem und bringt den Beweis Eurer Tat zu Klippenbehüter Longhorn im Freiwindposten.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[5148] = { id = 5148, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stammeslederverarbeitung", description = "Um die Kunst der Stammeslederverarbeitung zu erlernen, müsst Ihr verstehen, wie urzeitlich die Natur wirklich ist; ich weiß, dass Ihr bereits die Kunst der Herstellung von Wildlederrüstungen gemeistert habt, und ich bin bereit, Eure Ausbildung abzuschließen.\n\nDoch wisset dies, {class}: Durch die Wahl dieses Weges erklärt Ihr Euch einverstanden, niemals die Kunst der Drachenlederverarbeitung oder der Elementarlederverarbeitung zu erlernen. Ihr könnt nur eine dieser drei Künste erlernen. Bringt mir des Weiteren die feinsten Proben Eurer Wildlederrüstungen. Von diesem Punkt aus werden wir dann beginnen, an Eurem Können zu arbeiten.", progress = "Die Natur ist eine Kraft, die besänftigt werden muss, bevor Ihr hoffen könnt zu lernen, wie ihr Wille für Eure Ledergewänder zu beugen ist. Bringt mir Euer Geschenk für diese Kraft und ich werde sicherstellen, dass Ihr erhört werdet.", completion = "Ihr habt Eure besten Geschenke gebracht und die Natur wird bald zulassen, dass Ihr sie Eurem Willen entsprechend beugt. Wenn ich meine Unterweisung beendet habe, wird Eure Arbeit eine Naturgewalt in sich selbst sein.\n\nUm in Zukunft die Kunst zu trainieren, sprecht einfach mit mir, und ich werde Euch das Wissen verfügbar machen, das Ihr noch als das Eure erwerben müsst.", objectives = "Bringt eine Wildlederweste und einen Wildlederhelm zu Se'Jib im Schlingendorntal.\n\nWenn Ihr diese Aufgabe abschließt, werdet Ihr Zugang zur Kunst der Stammeslederverarbeitung erhalten.\n\nWenn Ihr diese Aufgabe abschließt, werdet Ihr allerdings weder Drachenlederverarbeitung noch Elementarlederverarbeitung erlernen können; seid also vorher sicher, dass dies der Weg ist, dem Ihr folgen wollt.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[5149] = { id = 5149, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pamelas Puppe", description = "Meine Tante Marlene hat gesagt, ich soll in unserem Haus bleiben, weil mein Vater in den Kampf ziehen muss. Mein Vater ist der mutigste Mann auf der ganzen Welt!\n\nAber ich bin schon so lange hier und er ist nicht gekommen, um mich abzuholen. Manchmal kommen böse Leute und flüstern mir etwas zu und ich will, dass mein Vater sie wegjagt, aber er ist nicht hier!\n\nUnd manchmal, wenn es dunkel wird, möchte ich mit meiner Puppe spielen, aber das kann ich nicht, weil ich sie in der Stadt gelassen habe.\n\nKönnt Ihr vielleicht meine Puppe für mich suchen?", progress = "Habt Ihr meine Puppe gefunden?", completion = "Ihr habt sie gefunden! Ihr habt meine Puppe gefunden! Oh, danke!", objectives = "Sucht Pamelas Puppe.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[5150] = { id = 5150, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dadanga ist hungrig!", progress = "Dadanga sieht zu Euch auf, während Ihr auf sie zu geht. Sie scheint auf etwas zu hoffen...\n\nSie hat wahrscheinlich Hunger!\n\nIm Krater muss irgendetwas wachsen, was die perfekte Leckerei für einen riesigen Pflanzenfresser ist. Dadanga ist ein großes Mädchen; was immer Ihr ihr bringt... es muss viel davon sein!", completion = "Als Ihr die Triebe vor sie hinlegt, scheint Dadanga erfreut zu sein.\n\nSie stubst ein kleines, braun eingepacktes Paket in Eure Richtung, quasi als Austausch für den Leckerbissen!" }
quests[5151] = { id = 5151, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hyperkondensator-Dingsda", description = "Ich bin der einzige Überlebende des Angriffs der Zentauren auf unsere Karawane! Ein rarer, aber mächtiger Panther bewacht mein bestes Dingsda, das um seinen Hals geschlungen ist. Ha! Sogar die Zentauren erzittern in Anwesenheit dieser wilden Bestie!\n\nHier ist der Schlüssel zu dem Käfig. Sie haben alles dorthin gebracht, ihn aber in Ruhe gelassen. Erledigt diese Bestie, bringt meinen Hyperkondensator zurück und ich werde Euch belohnen.\n\nDie überfallene Karawane befindet sich nördlich von hier.", progress = "Habt Ihr meinen Hyperkondensator?", completion = "Mein Hyperkondensator! Damit werde ich einige Zeit beschäftigt sein, bis ich herausgefunden habe, was er macht...", objectives = "Erschlagt die Bestie und bringt den Hyperkondensator sowie den Pantherkäfigschlüssel zu Wizlo Bearingshiner zurück.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[5152] = { id = 5152, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tante Marlene", description = "Oh, ich bin ja so einsam. Wo ist meine Familie? Tante Marlene hat mir gesagt, ich soll hier bleiben, aber dann ist sie weggegangen und nicht wiedergekommen! Und mein Papa... habt Ihr ihn gesehen?\n\nVielleicht weiß Tante Marlene, wo er ist. Sie lebt in der Nähe von Andorhal, in einem Haus im Süden. Ich glaub, es war auf einem Hügel... sie sagt, es wäre auf einem Hügel.\n\nBitte, {name}. Wir sind doch jetzt Freunde! Könnt Ihr für mich mit meiner Tante sprechen?", completion = "Ihr habt Pamela gesehen? Wie geht es ihr? Ist sie am Leben?? Oh nein! Die arme Pamela! Sie war so jung und so ein fröhliches Kind...\n\nSie weiß nicht, was mit ihrem Vater geschehen ist, nicht wahr? Mit meinem Bruder Joseph...\n\nNein... sie könnte nicht verstehen, was mit Joseph geschehen ist. Und selbst wenn sie es könnte, ich habe nicht das Herz, es ihr zu sagen...", objectives = "Sprecht mit Marlene, südlich der Ruinen von Andorhal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[5153] = { id = 5153, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein seltsamer Historiker", description = "Ich wünschte, Joseph könnte wieder bei seiner Tochter sein, aber das geht nicht. Seine Seele wurde von der Geißel verdreht und er wurde zu einem Monster. Oh, er ist verloren!\n\nAber vielleicht können wir sein Schicksal ändern.\n\nDurchsucht die Gräber draußen nach Josephs Denkmal. Sein Körper ist nicht dort, da er vor Jahren zertrampelt und zerschmettert wurde, aber unter dem Denkmal liegt sein Ehering. Bringt den Ring zu Chromie ... das ist eine merkwürdige Gnomin mit sehr merkwürdigen Kräften.\n\nChromie hält sich in dem zerstörten Gasthaus im nordwestlichen Teil von Andorhal auf.", progress = "Ihr habt einen guten Zeitpunkt für Euren Besuch gewählt. Ihr seid nicht zufälligerweise aus der Zukunft, oder?", completion = "Was ist das? Ein Ehering? Lasst mich mal sehen...\n\nAh! Dieser Ring steckte einst an der Hand eines großen Mannes, aber in der Vergangenheit dieses Mannes geschah eine große Tragödie.\n\nSeid Ihr hier, um ihm zu helfen? Für ihn ist jetzt alles zu spät... aber vielleicht können wir ihm in der Vergangenheit helfen!", objectives = "Bringt Josephs Ehering zu Chromie.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[5154] = { id = 5154, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Annalen von Darrowshire", description = "Um Joseph Redpath zu retten, müssen wir zuerst seine Vergangenheit enthüllen. Wir können sie den 'Annalen von Darrowshire' entnehmen, einem Buch, das im Rathaus von Andorhal aufbewahrt wird.\n\nBringt mir dieses Buch. Wir können etwas über Josephs Schicksal erfahren ... und es mit etwas Glück ... ändern!", progress = "Habt Ihr das Buch gefunden, {name}?", completion = "Sehr schön, Ihr habt es gefunden!\n\nHabt Ihr es gelesen? Wird Joseph Redpath erwähnt? Falls er erwähnt wird, dann können wir ihn vielleicht retten!\n\nAh. Die 'Annalen von Darrowshire' erzählen eine sehr beunruhigende Geschichte. Darin heißt es, dass Joseph Redpath während des Kampfes verderbt wurde und sich in die Ränge der Geißel eingereiht hat! Dann verriet er die Verteidiger von Darrowshire.\n\nDas ist ein übles Schicksal. Wir sollten versuchen, dieses Schicksal zu ändern, so das möglich ist, meint Ihr nicht?", objectives = "Bringt die 'Annalen von Darrowshire' zu Chromie in Andorhal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[5155] = { id = 5155, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Streitmacht von Jaedenar", description = "Wenn ich Euch in dieser Angelegenheit vertrauen soll, müsst Ihr Euch zuerst als vertrauenswürdig erweisen.\n\nIch muss sicher sein, dass Ihr ein Feind des Schattenrates seid - seine Mitglieder sind für viele böse Taten nah und fern verantwortlich.\n\nReist tiefer in den Teufelswald hinein. Im Westen werdet Ihr einen Pfad sehen, der nach Jaedenar führt. Dort schmiedet der Rat Pläne zusammen mit der Brennenden Legion.\n\nBetretet die Tiefen eines der von ihnen bewohnten verderbten Grabhügel und macht sie nieder. Kehrt zu mir zurück, wenn Ihr dies erledigt habt. Dann weiß ich, dass Ihr uns wirklich helfen wollt.", completion = "Gut, {name}! Wenn ihre Anzahl abgenommen hat, können wir sie weiter bedrängen.\n\nWie war Euer erster Eindruck ihrer Macht? Waren sie so stark, wie ich dachte? Stärker? Oder vielleicht waren sie überhaupt keine Herausforderung für Euch... Das wäre nun wirklich eine Überraschung!\n\nWir können die Einzelheiten Eurer Taten später erörtern. Jetzt müssen wir uns auf andere Dinge konzentrieren.", objectives = "Betretet Jaedenar und erschlagt 4 Hunde von Jaedenar, 4 Gardisten von Jaedenar, 6 Adepten von Jaedenar und 6 Kultisten von Jaedenar, bevor Ihr zu Greta Mosshoof im Teufelswald zurückkehrt.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[5156] = { id = 5156, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Verderbnis überprüfen", description = "Im Norden, entlang der östlichen Straße im so genannten Shatter Scar-Tal, liegt ein Bereich, wo im letzten großen Krieg Höllenbestien herbeigerufen wurden; die Krater zernarben immer noch das Land, so wie die Höllenbestien selbst.\n\nIch möchte gern zwei Dinge wissen. Erstens, durchstreifen immer noch entropische Elementare das Gebiet? Und zweitens, sind die Krater immer noch mit dem verderbten, stinkenden Wasser gefüllt, das sich dort vor Jahren gesammelt hat? Würdet Ihr das für mich überprüfen, {name}? Seid aber vorsichtig, die Höllenbestien zerstören alles, was ihren Weg kreuzt.", completion = "Schön, dass Ihr am Leben seid, {name}. Nicht schön ist, dass das Wasser immer noch existiert. Ich hatte gehofft, zumindest eine reine Wasserquelle hier im Teufelswald zu finden. Es sieht so aus, als wäre meine Suche fehlgeschlagen. Gäbe es sie, wäre der Prozess der Heilung des Landes wesentlich vereinfacht worden.\n\nIch werde mich also damit befassen müssen, die Waldkreaturen zu retten, die ich retten kann. Gleichzeitig vernichte ich die, die so verderbt wurden, dass sie nicht nur für sich selbst, sondern auch für Reisende, die durch diesen einst so mächtigen Wald ziehen, eine Gefahr sind.", objectives = "Sucht und zerstört 2 entropische Bestien und 2 entropische Schrecken, während Ihr das Shatter Scar-Tal erforscht. Nachdem Ihr überprüft habt, ob die Krater immer noch mit verderbtem Fel-Wasser gefüllt sind, kehrt zu Taronn Redfeather im Teufelswald zurück.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[5157] = { id = 5157, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verderbtes Wasser sammeln", description = "Tief in Jaedenar liegt die Schattenfeste - die Hauptfestung der Verderbnis und des Bösen.\n\nDer Schattenrat verfügt über Schutzzauber in Form von Kohlenpfannen, die seinen Unterschlupf umgeben. Wenn ich durch Wahrsagen noch weitere Informationen über unseren Feind herausfinden soll, müssen diese Kohlenpfannen gelöscht werden. Dann sollte ich den Rat ausspionieren und herausfinden können, wer ihn anführt.\n\nBitte, nehmt diese Feldflasche und füllt sie am Mondbrunnen im Zentrum von Jaedenar, wenn Euch dies möglich ist. Kommt dann zu mir zurück.", progress = "Wenn wir Wasser vom Mondbrunnen haben, werden wir es läutern und dazu verwenden, die Kohlenpfannen des Schutzes in der Schattenfeste zu löschen. Das würde mir ausreichend Zeit geben, um noch tiefer in die Kammern hineinzusehen und zu erkennen, wer diesen ... Kult tatsächlich anführt.\n\nIch bete, dass die Erdenmutter mit uns ist.", completion = "Das dürfte reichen, {name}.\n\nJetzt müssen wir das Wasser nur noch läutern lassen, bevor wir es auf die Kohlenpfannen anwenden. Das sollte nicht schwierig sein - es ist nur eine kleine Reise dafür erforderlich.\n\nHoffentlich können wir das schnell erledigen.", objectives = "Bringt die leere Feldflasche zum Mondbrunnen im Zentrum von Jaedenar und füllt sie, bevor Ihr zu Greta Mosshoof im Teufelswald zurückkehrt.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[5158] = { id = 5158, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spirituelle Hilfe suchen", description = "Bringt das verderbte Wasser ins Brachland, {name}. Südlich von Ratchet, versteckt entlang des Ufers, hält sich eine alte Freundin von mir auf, eine Schamanin namens Islen Waterseer. Sie ist eine mächtige Schamanin, die uns helfen wird. Ihre Verbindung zu den Geistern des Wassers war immer stark. Dass unsere Aufgabe edel ist, sollte ausreichen, um sie und die Geister des Wassers dazu zu bringen, bei dieser Aufgabe zu helfen.\n\nIhr dürftet sie in einem kleinen Lager direkt am Wasser finden. Ach ja, {name}, ignoriert die Piraten ... sie sind nur eine Plage und keine Bedrohung für Euch.", progress = "Ich spüre, dass Ihr nicht nur ein einfacher Reisender seid, der den Weg nach Ratchet sucht. Kommt, setzt Euch und ruht Euch in unserem Lager aus. Sprecht mit mir, wenn Ihr bereit seid.", completion = "Ah, Ihr müsst das Wasser aus diesem Mondbrunnen säubern lassen. Es erscheint edel genug, die Kräfte der Bosheit im Teufelswald stoppen zu wollen, aber die Entscheidung liegt nicht bei mir, ob dieses Wasser geläutert wird. Ich werde die Geister des Wassers fragen - es wird an ihnen liegen zu entscheiden, ob der Grund gerecht ist.\n\nGebt mir einen Augenblick und ich werde ihnen von Eurer Bitte berichten. Ich hoffe, dass sie Eurem Anliegen genauso wohlwollend gegenüberstehen wie ich.", objectives = "Bringt das verderbte Mondbrunnenwasser in das Brachland zu Islen Waterseer.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[5159] = { id = 5159, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gesäubertes Wasser wird zum Teufelswald gebracht", description = "Dankt den Geistern, {name}. Sie sind diejenigen, die Euch zu Hilfe kamen, nicht ich.\n\nIch gebe Euch nun dieses geläuterte Wasser. Richtet Greta bitte meine Grüße und meine besten Wünsche aus. Sie kämpft mit etwas viel Größerem als die meisten von uns... wie sie sicherlich bald herausfinden wird.\n\nDer Schattenrat ist keine Kraft, die man unterschätzen sollte, {name}. Vergesst das nicht.\n\nGeht jetzt. Nehmt das Wasser und kehrt zu Greta zurück.", progress = "Ah, wie ich sehe, seid Ihr zurückgekehrt, {name}. Gut. Habt Ihr Islen im Brachland gefunden? Oder müssen wir einen anderen Weg finden, unsere Ziele zu erreichen?", completion = "Das sollte mehr als genug Wasser für unsere Zwecke sein.\n\nIch freue mich zu hören, dass Islen uns helfen konnte. Ihre Kraft mit den Wassergeistern war immer stark. Außerdem ist sie weise und es kommt selten vor, dass die Geister ihre Absichten nicht gutheißen. Die Tatsache, dass beide unsere Aufgabe abgesegnet haben, gibt mir die Hoffnung, dass wir auf dem rechten Weg sind.", objectives = "Bringt das geläuterte Mondbrunnenwasser zu Greta Mosshoof im Teufelswald.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[5160] = { id = 5160, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die oberste Beschützerin", description = "Reist nach Kalimdor, {race}. Unser Schwarm ist in der frostigen Landschaft von Winterspring zu Hause. Wenn Ihr Winterspring erreicht habt, sucht die Höhlen von Mazthoril.\n\nAuf den eisigen Böden von Mazthoril werdet ihr Kobaltrunen finden. Haltet eine meiner Schuppen in der Hand und stellt Euch auf eine Rune. Ihr werdet dann zu Haleh transportiert, unserer obersten Beschützerin.\n\nGebt ihr die Schuppe, damit sie weissagen kann, was ich hier an diesem verlorenen Ort gesehen und gefühlt habe.", progress = "Es ist schön, Euch zu sehen, {name}.", completion = "Die Aspekte bestehen darauf, dass wir uns aus den Angelegenheiten der Sterblichen heraushalten. In dieser Welt ist das aber nicht immer möglich - besonders, wenn einer der Unseren solche Erlasse verächtlich missachtet.", objectives = "Begebt Euch nach Winterspring und sucht Haleh. Gebt ihr Awbees Schuppe.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[5161] = { id = 5161, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Zorn des blauen Drachenschwarms", description = "Wir verstehen, was die verfluchte Brut von Deathwing zu tun versucht, und wir wissen, dass das unterbunden werden muss.\n\nDurch den Schutz, den Blackrock Nefarian bietet, wird es für uns immer schwieriger zu intervenieren.\n\nWir können aber Euch, sterbliches Wesen, ermächtigen - solltet Ihr Euch dafür entscheiden.\n\nDer Weg, der vor Euch liegt, ist voller Gefahren. Ihr müsst Euch entscheiden, ob Ihr unsere Hilfe annehmt. Denkt darüber nach und sprecht erneut mit mir, wenn Ihr eine Entscheidung getroffen habt.", completion = "So soll es geschehen...", objectives = "Sprecht mit Haleh, wenn Ihr weitermachen wollt.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[5162] = { id = 5162, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Zorn des blauen Drachenschwarms", description = "Das Arkane kontrolliere ich und das Arkane wird Euch zu Eurem nächsten Ziel senden.\n\nWenn Ihr bereit seid, wird die Reise beginnen. Ihr werdet Euch zu den Pestländern begeben und mit Jeziba sprechen.\n\nEr ist ein Sterblicher, so weise wie die Uralten und so geduldig wie die unbewegliche Erde. Sucht ihn in Andorhal.", completion = "Ich bin Jeziba, vielen bekannt als der Bildhauer. Was ich forme, sind aber keine Statuen, sondern Helden.", objectives = "Sprecht mit Jeziba in den Pestländern. Er wohnt in Andorhal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[5163] = { id = 5163, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sind wir endlich da, Yeti?", description = "Es ist alles bereit, {name}!\n\nAlso, ich habe meinen Freunden bereits eine Nachricht geschickt und ihnen gesagt, dass ich eine Überraschung für sie habe. Und hier kommt Ihr ins Spiel!\n\nIch werde Euch meinen mechanischen Yeti geben und Ihr müsst sie überraschen, indem Ihr jeden meiner Freunde aufsucht, den Yeti einschaltet und zu ihnen schickt.\n\n Nachdem Ihr ihn Legacki in Everlook, Sprinkle in Gadgetzan und Quixxil in Marshals Zuflucht gezeigt habt, kehrt zurück und berichtet mir, was geschehen ist!\n\nBitte bringt mir meinen Yeti dann wieder zurück.", progress = "Ich kann es gar nicht erwarten zu hören, wie meine Freunde reagieren!\n\nDas werden sie niemals erwarten!", completion = "Ha! Die werden es sich jetzt zweimal überlegen, bevor sie sich wieder über meine Ideen lustig machen!\n\nIch danke Euch für Eure Hilfe, {name}. Ohne Euch hätte ich nicht so viel Spaß haben können!", objectives = "Nehmt Umis mechanischen Yeti und erschreckt ihre Freunde damit:\n\nLegacki in Everlook (Winterspring)\nSprinkle in Gadgetzan (Tanaris)\nQuixxil in Marshals Zuflucht (Un'Goro Krater)\n\nWenn Ihr damit fertig seid, bringt den mechanischen Yeti zu Umi zurück.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[5164] = { id = 5164, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verzeichnis der Abtrünnigen", description = "Haleh hätte kein feineres Instrument der Gerechtigkeit wählen können. Lest das 'Verzeichnis der Abtrünnigen' und werdet erleuchtet.\n\nFalls Ihr durchhaltet... falls Ihr tut, was von Euch verlangt wurde... falls Ihr überlebt... werdet Ihr ein Held sein.", completion = "Hunderte und Hunderte von Seiten voller Textfetzen und Symbole bilden den Großteil dieses Buches.", objectives = "Lest das 'Verzeichnis der Abtrünnigen'.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[5165] = { id = 5165, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Übergießen der Flammen des Schutzes", description = "Jetzt müsst Ihr nach Jaedenar zurückkehren. Die Kohlenpfannen sind wahrscheinlich über die ganze Schattenfeste verteilt. Übergießt jede ihrer Flammen, und der Schutz, den der Rat eingerichtet hat, wird zumindest für eine kurze Zeit erlöschen. Ich werde warten, dass dies geschieht. Wenn es so weit ist, werde ich einen tiefen Blick in die Feste werfen und versuchen herauszufinden, wer der Kopf dieser Bestie ist. Dann, und nur dann, werden wir sehen, ob wir sie direkt angreifen.", completion = "Ich konnte Euch durch meine Zauber sehen, als die Flamme der letzten Kohlenpfanne erstarb. Gut gemacht, {name}.\n\nIch habe einige Dinge in Erfahrung gebracht, bevor die Hexenmeister des Schattenrates ihre Zauber erneut wirken konnten. Hoffentlich wird es ausreichen.\n\nNun denn, ruht Euch aus. Ich werde Euch dann berichten, was ich erfahren habe.", objectives = "Übergießt die Flammen der vier Kohlenpfannen des Schutzes in der Schattenfeste im Teufelswald mit dem geläuterten Mondbrunnenwasser.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[5166] = { id = 5166, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brustplatte des Chromatischen Drachenschwarms", description = "Das Schmieden einer mächtigen Brustplatte zum Schutz gegen die unerbittlichen Angriffe des chromatischen Drachenschwarms ist eigentlich recht ironisch.\n\nDie Schuppen der Bestien, die wir bekämpfen, müssen an einen makellosen Knochenpanzer eines alten chromatischen Drachens oder Großdrachens genäht werden. Derzeit ist nicht bekannt, ob es überhaupt welche gibt, und wir sollten hoffen, dass es niemals welche geben wird.\n\nUnd dann ist da noch die vielleicht schwierigste aller Komponenten: das Blut von Helden.\n\nDer Bildhauer muss diese Kreation dann schmieden.", progress = "Ihr habt weise gewählt, {race}.", completion = "Habt Ihr noch immer nicht verstanden? Die Reise war das Ziel. Könnt Ihr nicht die Narben des Kampfes fühlen? Den Schmerz, den Ihr ertragen habt?\n\nDa Ihr die Tortur überlebt habt, seid Ihr nun ein mächtigeres Wesen. Viel mächtiger. Diese Brustplatte ist nur ein Spiegelbild Eurer eigenen angeborenen Fähigkeiten.", objectives = "Um die Brustplatte des chromatischen Drachenschwarms zu schmieden, müsst Ihr die folgenden Gegenstände zu Jeziba dem 'Bildhauer' bringen:\n\n1 chromatischer Knochenpanzer.\n\n10 glänzende chromatische Schuppen.\n\n10 Einheiten Blut von Helden.\n\n10 ausgefranste Monstrositätenstickereien.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[5167] = { id = 5167, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beinplatten des chromatischen Widersetzers", description = "Der Knochenpanzer eines erwachsenen chromatischen Drachen wird benötigt, um die Grundlage der Gamaschen zu fertigen. Glänzende chromatische Schuppen werden dann auf das Grundgerüst aufgebracht und im Blut der Helden verzaubert. Schließlich muss noch die geschmeidige Haut des Schattens auf die inneren Schienbeinschützer aufgebracht werden.", objectives = "Um die Beinplatten des chromatischen Widersetzers zu schmieden, müsst Ihr die folgenden Gegenstände zu Jeziba dem 'Bildhauer' bringen:\n\n1 chromatischer Knochenpanzer.\n\n10 glänzende chromatische Schuppen.\n\n10 Einheiten Blut von Helden.\n\n5 Häute des Schattens.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[5168] = { id = 5168, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Helden von Darrowshire", description = "Die Helden von Darrowshire haben einen Platz in meinem Herzen und das Buch, das Ihr mir gebracht habt, die 'Annalen von Darrowshire', erzählt ihre Geschichten.\n\nEs berichtet von dem Paladin Davil Lightfire und davon, wie der Kreuzzug seinen Buchband zum Rathaus von Hearthglen brachte.\n\nEinige Passagen handeln auch von meinem Bruder, Captain Redpath. Nach seinem Verrat wurde sein Schild zerschmettert und weggeworfen und liegt nun am unwahrscheinlichsten aller Orte - in der Nähe von Gahrrons Trauerfeld.\n\nSammelt diese Relikte, {name}. Denn Verhängnis und Tragik umgeben sie.", progress = "Habt Ihr die Relikte, {name}?", completion = "Ihr habt den Buchband und den Schild!\n\nIhre Geschichte ist mit der Geschichte von Darrowshire verbunden und irgendwie weiß ich, dass das Schicksal sie wieder zusammenführen wird.", objectives = "Bringt Davils Buchband und Redpaths Schild zu Carlin Redpath.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[5181] = { id = 5181, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bösewichte von Darrowshire", description = "Die 'Annalen von Darrowshire' berichten von den Bösewichten dieser Schlacht. Sie berichten, wie der Ghullord Horgus der Verheerer von Kräften der Allianz während der Schlacht vernichtet wurde. Seine Leiche wurde in einen See geworfen, nordwestlich von Corins Kreuzung, und sein Schädel ist noch dort.\n\nMarduk der Schwarze wurde nie besiegt, aber sein sagenhaftes Schwert wurde zertrümmert und ging verloren. Es liegt auf dem Grund der Schlucht westlich von Corins Kreuzung.\n\nBringt diese Gegenstände zurück, {name}. Ich weiß nicht, warum, aber ich bin sicher, dass ihr Schicksal in Euren Händen liegt.", progress = "Habt Ihr den Schädel und das Schwert gefunden, {name}?", completion = "Ihr habt sie gefunden! Gut gemacht, {name}! Diese Relikte enthalten eine Macht, die ich nicht ganz verstehe, eine Macht, die Ihr eines Tages beherrschen werdet.\n\nSie wecken aber auch dunkle Erinnerungen in meinen Gedanken, Erinnerungen an Tod und Verrat und an die letzte Nacht von Darrowshire...", objectives = "Bringt den Schädel von Horgus und das zertrümmerte Schwert von Marduk zu Carlin Redpath in der Kapelle des hoffnungsvollen Lichts.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[5201] = { id = 5201, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eindringlinge der Winterfelle", description = "Meine Anwesenheit bleibt den Meisten verborgen, {name}. Es gibt aber eine Störung, die hier in Winterspring fest verankert zu sein scheint: die Winterfellfurbolgs.\n\nObwohl ich die Furbolgs nie direkt angegriffen habe, scheinen sie wahnsinnig zu sein, alles, was in ihrem Weg steht, scheint sie zu ängstigen. Ich habe beobachtet, wie sie zahllose Kreaturen erschlagen haben, die das Pech hatten, einfach zur falschen Zeit am falschen Ort zu sein.\n\nIch bin ihrer Einmischungen müde ... helft mir bitte, indem Ihr sie bekämpft. Erschlagt die Furbolgs und haltet sie vom Frostsäblerfelsen fern.", completion = "Ich bin erleichtert zu hören, dass wir uns zumindest für kurze Zeit über die Eindringlinge der Winterfelle keine Sorgen machen müssen.\n\nIhr beginnt Beharrlichkeit zu zeigen, {name}.", objectives = "Rivern Frostwind möchte, dass Ihr 5 Schamanen der Winterfelle und 5 Ursa der Winterfelle erschlagt.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[5202] = { id = 5202, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein merkwürdiger roter Schlüssel", description = "Der kleine rote Schlüssel scheint aus einem Knochenmaterial gemacht zu sein. Er liegt schwer in Eurer Hand, wirkt aber trotzdem sehr zerbrechlich. Warum sollte ein Mitglied des Schattenrats solch ein Ding haben? Vielleicht gibt es etwas in Jaedenar, was dieser merkwürdige Schlüssel aufschließen kann.", progress = "Ich beginne mich zu fragen, ob ich diesem Käfig jemals entkommen werde.\n\nEs ist nur eine Frage der Zeit, bevor sie mich irgendeinem der Dämonen opfern, die sie anbeten. Diese Monster!", completion = "Der Schlüssel, Ihr habt ihn gefunden! Bitte, gebt ihn mir, damit ich endlich entkommen kann!", objectives = "Durchsucht Jaedenar, um herauszufinden, wofür der blutrote Schlüssel verwendet wird.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[5203] = { id = 5203, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rettung aus Jaedenar", description = "Aber so sehr es mich auch schmerzt, es gibt eine Sache, die zuerst erledigt werden muss. Ich muss Treys Schwert Lightforge finden und aus der Schattenfeste entkommen, um meinen Vorgesetzten zu berichten, was hier geschieht. Könntet Ihr mir helfen, {name}?\n\nUnsere Ausrüstung ist nicht weit von hier und Ihr habt bereits bewiesen, dass Ihr den Weg an die Spitze überleben könnt.\n\nNachdem wir entkommen sind, werde ich nach Darnassus gehen, und Euch würde ich bitten, meine Freundin Jessir in der Nähe der Grenze zu Ashenvale aufzusuchen. Sie sollte sich eigentlich im Lager des Smaragdkreises hier in der Nähe mit uns treffen.\n\nWas sagt Ihr dazu, {name}? Würdet Ihr mir nochmals helfen?", completion = "Ihr wart es, der Arko bei der Flucht geholfen hat? Ich bin ja so froh, dass Ihr mich gefunden habt. Sie kam vor nicht allzu langer Zeit auf ihrem Weg nach Darnassus hier vorbei. Sie hatte Lightforge im Schlepptau und nahm sich nicht einmal die Zeit, um mit den Druiden zu sprechen, um sich heilen zu lassen. Sie sagte, es wäre viel zu dringend.\n\nAber sie berichtete mir von Eurer Begegnung mit dem Geist von Trey. Was für ein schreckliches Schicksal für einen Ritter der Silberhand. Sie zeigte es nicht, aber ich weiß, dass der Gedanke, einen ihrer engsten Freund zu verlieren, sie im Inneren zerreißt.", objectives = "Bringt Arko'narin dorthin, wo Lightforge und ihre Ausrüstung aufbewahrt werden, und beschützt sie dann bei eurer Flucht aus der Schattenfeste. Sucht danach Jessir Moonbow im Teufelswald auf und lasst sie wissen, was mit ihren Freunden geschehen ist.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[5204] = { id = 5204, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vergeltung des Lichts", description = "Sie möchte so tun, als ob es ihr gut ginge. Sie möchte gern, dass ich denke, sie sei stark genug, um mit alledem selbst fertig zu werden, aber ich weiß es besser. Treys Tod und zu hören, welche Folter er erdulden musste, wird sie lange Zeit verfolgen, und es gibt nichts, was wir tun können, um das zu stoppen. Aber wir können ihr ein wenig Frieden geben!\n\n{name}, kehrt zur Schattenfeste zurück, tötet Treys Folterknecht und sucht seine Überreste. Es gibt keinen Grund, dass wir nicht all diese Dinge zu Ende bringen können, während Arko'narin auf ihre eigene Art trauert.", progress = "Ihr untersucht den Körper und es gibt keinen Zweifel, dass dies die Überreste des Ritters der Silberhand, Trey Lightforge, sind. Einen Moment lang denkt Ihr an Arko'narin und fragt Euch, ob Euch jemals in Eurem Leben jemand so viel bedeutet hat, wie dieser Mann der gefangenen Nachtelfin bedeutete, der Ihr kürzlich bei der Flucht aus der Schattenfeste geholfen habt.\n\nNachdem Ihr in einem weiteren Augenblick Eure Gedanken gesammelt habt, wisst Ihr, dass Ihr die Überreste des Paladins nicht zu Jessir zurückbringen könnt, ohne zuvor seinen Folterknecht zu töten.", completion = "Ihr sammelt die Überreste des Paladins so sorgfältig wie möglich ein und erinnert Euch daran, dass zumindest sein Geist von jeglichem Schmerz oder Leiden erlöst wurde, das über ihn gebracht worden war.", objectives = "Kehrt nach Jaedenar zurück und tötet den Sukkubus Rakaiah, bevor Ihr die Überreste von Trey Lightforge sucht.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[5206] = { id = 5206, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Marodeure von Darrowshire", description = "Chromie sagte, dass die von Euch gesammelten Relikte Reagenzien für einen mächtigen Zauber seien und dass noch eines fehle: Schädel von Angehörigen der Geißel, die an der Schlacht von Darrowshire teilnahmen.\n\nNehmt diesen Kristall und jagt um ihrer Schädel willen Champions der Geißel. Der Kristall ist verzaubert: Wenn ein Held an der Schlacht teilnahm, dann wird er, wenn Ihr ihn über dessen Schädel haltet, widerhallen. Bringt mir diese widerhallenden Schädel.\n\nGeht, {name}. Ihr könnt Champions der Geißel im giftigen Tal im Norden und im Fungustal im Westen finden.", progress = "Habt Ihr die Schädel? Chromie sagte, sie wären äußerst wichtig für ihren Zauber, und dieser Zauber gäbe uns die Chance, Darrowshire zu retten.", completion = "Ihr habt sie gefunden! Großartig!\n\nWenn ich auch nicht genau weiß, inwiefern sie uns helfen werden, so spüre ich doch ihre Macht und fühle es in meinen Knochen, dass sie irgendwie mit meinem Heimatdorf Darrowshire verbunden sind.", objectives = "Bringt 5 widerhallende Schädel und den mystischen Kristall zu Carlin Redpath in den Östlichen Pestländern.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[5210] = { id = 5210, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bruder Carlin", description = "Die 'Annalen von Darrowshire' haben mit Hilfe meiner Magie an ihrem Ende Seiten hinzugewonnen, und nun erstreckt sich die Geschichte auch über den Kampf hinaus. Eine der zusätzlichen Passagen berichtet von einem anderen Redpath, Carlin, der Josephs Verrat überlebt hat. Carlin befindet sich jetzt in den Pestländern im Osten, bei der Kapelle des hoffnungsvollen Lichts.\n\nNehmt das Buch und sprecht mit ihm.", progress = "Ihr kommt aus dem Westen? Wie ergeht es dem Rest von Lordaeron? Ich weiß, dass Andorhal verloren ist, aber hat die Geißel schon Tirisfal erreicht?", completion = "Was ist mit diesem Buch? 'Die Annalen von Darrowshire'? Das war mein Heim vor dem Krieg... mein Heim vor der Schlacht, die es zerstörte! Warum habt Ihr mir dieses Buch gebracht?\n\nAber seht doch nur hier! Am Ende sind Seiten, die Geschichten von den Tagen nach der Schlacht erzählen! Hier ist eine Passage über mich! Und eine über meinen Bruder Joseph! Ist dieses Buch echt?\n\nWir müssen die Wahrheit erfahren!", objectives = "Bringt die erweiterten 'Annalen von Darrowshire' zu Carlin Redpath in den Östlichen Pestländern.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[5211] = { id = 5211, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verteidiger von Darrowshire", description = "Viele der Verteidiger fielen in der Schlacht von Darrowshire. Und viele ziehen erneut umher als grässliche Diener der Geißel! Sucht diese armen Seelen und beendet ihr Elend!\n\nJagt Menschenfresserghuls, plappernde Ghuls und kranke Schinder. Viele dieser Satanskreaturen waren einst gute Leute aus Darrowshire und die Zerstörung ihrer Formen wird ihre Seelen befreien.\n\nIhr werdet sie im Pestwald und bei Corins Kreuzung finden, ebenso wie in anderen Geißelfestungen in den östlichen Pestländern.", progress = "Die armen Verteidiger von Darrowshire rufen in meinen Träumen nach mir, {name}. Ihr müsst sie befreien!", completion = "Es ist gut zu hören, dass Ihr die gequälten Seelen meiner Brüder gefunden und befreit habt. Mein Herz wird weniger weinen, da es weiß, dass zumindest einige der Verteidiger von Darrowshire nicht mehr länger in der widerlichen Dienerschaft der Geißel gefangen sind.", objectives = "Befreit 15 Geister von Darrowshire und kehrt dann zu Carlin Redpath zurück.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[5212] = { id = 5212, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Fleisch lügt nicht", description = "Die Apotheker der Verlassenen sind nicht die einzigen Wesen auf dieser Welt, die in den Wissenschaften bewandert sind.\n\nIch erforsche die Seuche schon seit Jahren, {race}. Wir dachten zuerst, dass die Stärke der Seuche langsam schwand, aber was ich hier in den Pestländern entdeckt habe, ist alarmierend. Die Kraft der Seuche scheint zu wachsen!\n\nIch muss mehr Tests durchführen! Die mächtigste Quelle der Seuche ist das besudelte Fleisch der vor kurzem Infizierten. Begebt Euch nach Stratholme und bringt mir Proben, {name}.", progress = "Manche behaupten, dass ich mir zu viele Sorgen mache - ihnen sage ich: 'Ihr macht euch nicht genug Sorgen!'", completion = "Etwas hat sich in der chemischen Struktur der aktiven Wirkstoffe der Seuche verändert. Es sind mehr Daten erforderlich.", objectives = "Sammelt 20 verseuchte Fleischproben in Stratholme und bringt sie zu Betina Bigglezink zurück. Ihr vermutet, dass Ihr besagte Fleischproben bei jeder Kreatur in Stratholme finden könnt.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[5213] = { id = 5213, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der aktive Wirkstoff", description = "Ihr müsst tiefer nach Stratholme vordringen, {name}.\n\nHinter den ersten Toren werdet Ihr die Ziggurats finden. Wir wissen, dass die Geißel große Macht aus diesen Gebäuden zieht. Durchsucht die Ziggurats und kehrt mit den Informationen zurück, die Ihr aufspürt.", progress = "Wir stehen kurz davor herauszufinden, was dieser neue aktive Wirkstoff der Seuche sein kann!", completion = "Erstaunlich! Es wird Monate dauern, das zu sezieren und zu analysieren. Die Argentumdämmerung dankt Euch für Eure Bemühungen, {name}.\n\nMit unserem Segen, dürft ihr nun zwischen diesem Siegel der Dämmerung und dieser Rune der Dämmerung wählen. Ihr könnt diese Insignien anstelle einer Anstecknadel der Argentumdämmerung benutzen, um in unserem Namen Geißelsteine zu sammeln. Sprecht mich im Falle eines Verlusts einfach an und ich werde Euch einen Ersatz beschaffen.", objectives = "Reist nach Stratholme und durchsucht die Ziggurats. Sucht neue Geißeldaten und bringt sie zu Betina Bigglezink zurück.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[5214] = { id = 5214, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der große Ezra Grimm", description = "Schrecklich... was mit Ezra geschehen ist. Wisst Ihr, die Stadt wurde geplündert und Ezra wollte seine wertvollen Dinge nicht zurücklassen. Das Letzte, woran ich mich erinnere, ist, dass er sagte: 'Ich verbrenne lieber alles, bevor ich zulasse, dass sie irgendwas in ihre verdammten, schmutzigen Pfoten kriegen!'\n\nIch rauche ja auch ganz gern mal eine Zigarre, aber ich bin kein Idiot. Ich habe Ezra und sein reizendes Geschäft an dem Tag verlassen. Ich nehme an, dass er in den Flammen unterging, aber wenn es eine Chance gibt, dass auch nur ein Kasten seines berühmten Tabaks noch intakt ist...\n\nWas sagt Ihr dazu, {name}? Sucht Ihr einen Kasten für den alten Smokey?", sourceObjective = "Sucht Ezra Grimms Raucherladen in Stratholme und bergt einen Kasten von Grimms Tollem Tabak. Kehrt zu Smokey LaRue zurück, wenn Eure Aufgabe erledigt ist.", progress = "Ich halte das nicht aus, {name}! Ihr müsst mir helfen! Ich sterbe!", completion = "Oh süße, süße Zigarre, wie ich dich vermisst habe...", sourceObjectiveStatus = "unverified-source-field" }
quests[5215] = { id = 5215, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Geißelkessel", description = "In den Ländern des ehemaligen Lordaeron befinden sich acht Kessel - vier hier im Westen und vier weitere versteckt im Osten. Diese Kessel speien Gifte in die Luft und verbreiten die Seuche für die Geißel im ganzen Land.\n\nDie nekromantische Macht von Kel'Thuzad ist zu stark, um diese Kessel gänzlich zu schließen, aber wir glauben zu wissen, wie wir sie zu unserem Vorteil nutzen könnten. Meine rechte Hand, die Hohepriesterin MacDonnell, wird Eure Kontaktperson für diesen Auftrag sein; sie wird die Einweisung fortsetzen.", completion = "Möge die Macht des Lichts in diesen dunklen Zeiten auf Euch scheinen, {class}. Ich bin erfreut, als Eure Koordinatorin für unseren Plan zur Sabotage der Kessel der Geißel zu dienen.\n\nUnser Ziel wird darin bestehen, die Zusammensetzung der Seuche, die die Kessel erzeugen, in etwas zu verwandeln, das sich negativ auf die Geißel auswirkt. Um diese Veränderung zu bewirken, müsst Ihr freien Zugriff auf jeden der vier Kessel sicherstellen, die es in den Westlichen Pestländern gibt.\n\nMacht Euch bereit, oh Held, ein glorreicher Kampf gegen die niederträchtige Geißel steht Euch bevor!", objectives = "Sprecht mit der Hohepriesterin MacDonnell an der Chillwindspitze, Westliche Pestländer.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[5216] = { id = 5216, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ziel: Teufelssteinfeld", description = "Von den vier Kesseln, die sich hier im Westen befinden, ist derjenige, der sich auf dem Teufelssteinfeld befindet, wohl der, zu dem der Zugang am einfachsten ist. Die Geißel hat hier Truppen mit weniger Erfahrung positioniert, sie sollten aber trotzdem nicht unterschätzt werden.\n\nGeht zum Teufelssteinfeld, nordwestlich von Andorhal, und befasst Euch dort mit dem Kessellord. Wir glauben, dass er einen Schlüssel hat, der den Zugang zu dem Kessel freigeben wird. Wenn er frei ist, benutzt diese Flasche, um dem Kessel eine Probe des Giftes zu entnehmen; wir benötigen sie für die Entwicklung eines Gegenwirkstoffs.", progress = "Die Zugangsklappe zum Kessel bleibt fest verschlossen. Um sie zu öffnen, müsst Ihr den Schlüssel finden.", completion = "Der Schlüssel, den Ihr dem Kessellord Gallenschlund abgenommen habt, passt perfekt zu der Zugangsklappe. Ein fauliger Geruch entweicht der geöffneten Klappe, während eine unbekannte Mischung aus konzentrierten Substanzen im Kessel umherwirbelt.\n\nDie Flasche passt perfekt unter einen kleinen Hahn, sodass Ihr eine Probe für die Schattenpriesterin Vandis am Bollwerk entnehmen könnt.", objectives = "Geht zum Teufelssteinfeld im den Westlichen Pestländern. Sucht nach dem dortigen Kessellord und besiegt ihn. Er könnte einen Schlüssel haben, der den Zugang zu dem Kessel ermöglicht. Ihr müsst die leere Flasche: Teufelssteinfeld bei Euch haben, um eine Probe des Giftes zu entnehmen, das sich in dem Kessel findet.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[5217] = { id = 5217, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr zum Chillwind-Lager", description = "Ihr füllt die Flasche mit einer ausreichenden Menge des giftiges Gebräus aus dem Kessel, sodass es für eine Probe zur Untersuchung reicht.\n\nMit dem Gift in der Hand ist es Zeit, zur Hohepriesterin MacDonnell an der Chillwindspitze zurückzukehren, um die Mission abzuschließen.", progress = "Willkommen in der relativen Sicherheit der Chillwindspitze, {name}. Welche Fortschritte könnt Ihr bezüglich der Kessel berichten?", completion = "Gut gemacht {name}... Alchimist Arbington sollte in der Lage zu sein, dies umgehend zu analysieren und ein Gegenmittel zu entwickeln, das wir dann in den Kessel geben. Wenn wir genug davon in die Luft pumpen können, sind wir vielleicht in der Lage, alle hier präsenten Mitglieder der Geißel zu schwächen.\n\nDiese Aktion wird sich ohne Zweifel über längere Zeit hinziehen; wir müssen der Mischung in diesen Kesseln ständig unsere Reagenzien hinzufügen. Wenn wir das aufrechterhalten können, werden wir einen großen Vorteil über die Geißel haben, wenn die Zeit für den Kampf gekommen ist!", objectives = "Bringt die gefüllte Flasche: Teufelssteinfeld zur Hohepriesterin MacDonnell an der Chillwindspitze, Westliche Pestländer.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[5218] = { id = 5218, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Kessel des Teufelssteinfelds", progress = "Der Seuchenkessel der Geißel steht vor Euch und speit große Mengen Toxin in die Luft. Eine kleine, unauffällige Zugangsklappe befindet sich in der großen Plattform des Kessels.\n\nDa Ihr den Kessellord bereits besiegt und seinen Schlüssel an Euch genommen habt, könnt Ihr die geeigneten Reagenzien in den Kessel geben, um ein Gegenmittel gegen die Seuche zu schaffen.", completion = "Nach Hinzufügen der Reagenzien zu dem Gemisch des Kessels beginnt sich die Farbe und Beschaffenheit der Wolke zu ändern, die er ausspeit. Angehörige der Geißel, die sich irgendwo in der Nähe des Kessels befinden, scheinen zu straucheln, als die neuen Komponenten in die Umgebung gelangen." }
quests[5219] = { id = 5219, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ziel: Dalsons Tränenfeld", description = "Einer der Seuchenkessel befindet sich auf dem Feld eines ehemaligen Bauernhauses, das jetzt Dalsons Tränenfeld genannt wird. Tja, wir werden heute keine Tränen vergießen, wenn wir der Geißel in die Quere kommen und sie an ihren eigenen Dämpfen ersticken lassen!\n\nBegebt Euch zu Dalsons Tränenfeld, ziemlich genau nördlich von Andorhal, und eliminiert den Kessellord dort. Er sollte, wie der Letzte auch, einen Schlüssel haben, durch den Ihr an den Kessel gelangen könnt. Benutzt diese Flasche, um eine Probe aus dem Kessel zu entnehmen; jeder Kessel enthält ein jeweils für ihn einzigartiges Gebräu aus Toxinen, das nur er benutzt.", progress = "Die Zugangsklappe zum Kessel bleibt fest verschlossen. Um sie zu öffnen, müsst Ihr den Schlüssel finden.", completion = "Der makabre Schlüssel des Kessellords gleitet problemlos in ein Schlüsselloch und verschwindet dann, wodurch Ihr permanenten Zugriff darauf habt. Kunstlose, zähflüssige Sekrete pulsieren durch die geschwungenen Röhren im Unterbau des Kessels.\n\nDie Flasche passt perfekt unter einen kleinen Hahn, sodass Ihr eine Probe für die Schattenpriesterin Vandis am Bollwerk entnehmen könnt.", objectives = "Begebt Euch zu Dalsons Tränenfeld in den Westlichen Pestländern, um den dortigen Kessellord zu suchen und zu besiegen. Verwendet dann seinen Schlüssel, um Zugang zum Kessel zu erhalten. Ihr müsst die leere Flasche: Dalsons Tränenfeld bei Euch haben, um eine Probe des Giftes zu entnehmen, das sich in dem Kessel findet.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[5220] = { id = 5220, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr zum Chillwind-Lager", description = "Vorsichtig füllt Ihr so viel, wie Ihr für eine sinnvolle Probe für nötig erachtet, von dem Sekret aus dem Kessel in die Flasche.\n\nMit dem Gift in der Hand ist es Zeit, zur Hohepriesterin MacDonnell an der Chillwindspitze zurückzukehren, um die Mission abzuschließen.", progress = "Wir wissen, dass sich in jedem Kessel ein anderes Gemisch von Reagenzien befindet, mit denen das Seuchen verursachende Toxin erzeugt wird. Dementsprechend müssen wir auch ein Gegenmittel entwickeln, das für jeden Kessel einzigartig ist. Eure Probe von Dalsons Tränenfeld wird der Schlüssel sein, um den einzigartigen Reagenzienbedarf für diesen Kessel zu bestimmen.", completion = "Ah, darin ist mehr als genug für die Untersuchungen. Gut gemacht, {name}!\n\nJetzt liegt der nächste Schritt bei uns. Wir werden eine Liste von Reagenzien erstellen, die in Kombination mit dem, was sich bereits in dem Kessel befindet, als Gegenmittel wirken.\n\nWir können dies allerdings nur umsetzen, indem die Reagenzien direkt in den Kessel gegeben werden. Alchimist Arbington dürfte weitere Informationen darüber haben, also sprecht so bald wie möglich mit ihm.", objectives = "Bringt die gefüllte Flasche: Dalsons Tränenfeld zur Hohepriesterin MacDonnell an der Chillwindspitze, Westliche Pestländer.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[5221] = { id = 5221, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Kessel von Dalsons Tränenfeld", progress = "Der Seuchenkessel der Geißel steht vor Euch und speit große Mengen Toxin in die Luft. Eine kleine, unauffällige Zugangsklappe befindet sich in der großen Plattform des Kessels.\n\nDa Ihr den Kessellord bereits besiegt und seinen Schlüssel an Euch genommen habt, könnt Ihr die geeigneten Reagenzien in den Kessel geben, um ein Gegenmittel gegen die Seuche zu schaffen.", completion = "Nach Hinzufügen der Reagenzien zu dem Gemisch des Kessels beginnt sich die Farbe und Beschaffenheit der Wolke zu ändern, die er ausspeit. Angehörige der Geißel, die sich irgendwo in der Nähe des Kessels befinden, scheinen zu straucheln, als die neuen Komponenten in die Umgebung gelangen." }
quests[5222] = { id = 5222, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ziel: Das trostlose Feld", description = "Zwei Kessel wurden erfolgreich geöffnet. Auf diese könnt Ihr jetzt zwar unbegrenzt zugreifen, aber wir möchten immer noch, dass Ihr die beiden verbleibenden öffnet. Damit erhielten wir weitere Möglichkeiten, den Gegenwirkstoff einzusetzen!\n\nDieses Mal werdet Ihr Euch um den Kessel des trostlosen Felds kümmern. Er befindet sich ziemlich genau östlich von Andorhal, relativ nahe bei den zerstörten Stadtmauern. Eliminiert auch dort den Kessellord, um an den Schlüssel zu gelangen. Benutzt diese Flasche, um eine Probe aus dem Kessel zu entnehmen.\n\nGute Jagd, {name}!", progress = "Die Zugangsklappe zum Kessel bleibt fest verschlossen. Um sie zu öffnen, müsst Ihr den Schlüssel finden.", completion = "Der Schlüssel des Kessellords entriegelt die Zugangsklappe zu diesem Kessel und verschwindet dann, ähnlich wie die anderen Schlüssel für die vorherigen beiden Kessel, um die Ihr Euch gekümmert habt. Eine faulig riechende Substanz brodelt heftig unter der Plattform des Kessels.\n\nDie Flasche passt perfekt unter einen kleinen Hahn, sodass Ihr eine Probe für die Schattenpriesterin Vandis am Bollwerk entnehmen könnt.", objectives = "Begebt Euch zum trostlosen Feld in den Westlichen Pestländern, um den dortigen Kessellord zu suchen und zu besiegen. Verwendet dann seinen Schlüssel, um Zugang zum Kessel zu erhalten. Ihr müsst die leere Flasche: Das trostlose Feld bei Euch haben, um eine Probe des Giftes zu entnehmen, das sich in dem Kessel findet.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[5223] = { id = 5223, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr zum Chillwind-Lager", description = "Vorsichtig füllt Ihr die leere Flasche. Jetzt schwappt eine Probe der stinkenden Substanz, die unter der Plattform des Kessels brodelt, in dem zerbrechlichen Glasbehälter herum.\n\nMit dem Gift in der Hand ist es Zeit, zur Hohepriesterin MacDonnell an der Chillwindspitze zurückzukehren, um die Mission abzuschließen.", progress = "Wenn wir erst die Probe vom Kessel des trostlosen Felds analysiert haben, wird sie uns einen dritten Weg bieten, um die Geißel mit einem verheerenden Gegenmittel zu schlagen!", completion = "Wieder habt Ihr eine Mission hervorragend durchgeführt, {name}! Damit stehen uns drei Kessel zur Verfügung, die wir gegen die Geißel einsetzen können. Wenn die nekromantische Herrschaft von Kel'Thuzad über diese Länder nicht so stark wäre, wie sie es derzeit ist, würde ich sagen, dass Ihr sie ganz erledigt habt.\n\nAlchimist Arbington wird einen Bericht darüber anfertigen, was dieser Kessel - genau wie jeder andere von uns veränderte Kessel - benötigt, um unser Gegenmittel gegen die Seuche einzusetzen. Damit ist die Zeit gekommen, den letzten Kessel im Westen unter unseren Einfluss zu bringen!", objectives = "Bringt die gefüllte Flasche: Das trostlose Feld zur Hohepriesterin MacDonnell an der Chillwindspitze, Westliche Pestländer.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[5224] = { id = 5224, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Kessel des trostlosen Felds", progress = "Der Seuchenkessel der Geißel steht vor Euch und speit große Mengen Toxin in die Luft. Eine kleine, unauffällige Zugangsklappe befindet sich in der großen Plattform des Kessels.\n\nDa Ihr den Kessellord bereits besiegt und seinen Schlüssel an Euch genommen habt, könnt Ihr die geeigneten Reagenzien in den Kessel geben, um ein Gegenmittel gegen die Seuche zu schaffen.", completion = "Nach Hinzufügen der Reagenzien zu dem Gemisch des Kessels beginnt sich die Farbe und Beschaffenheit der Wolke zu ändern, die er ausspeit. Angehörige der Geißel, die sich irgendwo in der Nähe des Kessels befinden, scheinen zu straucheln, als die neuen Komponenten in die Umgebung gelangen." }
quests[5225] = { id = 5225, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ziel: Gahrrons Trauerfeld", description = "Der letzte verbleibende Kessel befindet sich auf einem Hof, der jetzt Gahrrons Trauerfeld genannt wird. Er wird durch einige der stärkeren Diener der Geißel bewacht... um genau zu sein durch Gespenster und Geisterscheinungen. Die darf man nicht unterschätzen, {name}.\n\nGahrrons Trauerfeld liegt von unserer Position hier aus im Nordosten, etwa dort, wo die Östlichen Pestländer beginnen. Eliminiert auch dort den Kessellord, um an den Schlüssel zu gelangen. Hier ist Eure leere Probenflasche; bringt sie mir gefüllt zurück. Möge das Licht Euch bei dieser gefährlichen Mission schützen, {class}.", progress = "Die Zugangsklappe zum Kessel bleibt fest verschlossen. Um sie zu öffnen, müsst Ihr den Schlüssel finden.", completion = "Der Schlüssel des Kessellords Rachseele löst sich auf, als er das Schloss der Zugangsklappe im Fundament der Kesselplattform berührt. Im Inneren erklingt ein leicht rasselndes Geräusch. Als die Zugangsklappe aufschwingt, enthüllt sie weitere zähflüssige Toxine im System des Kessels.\n\nDie Flasche passt perfekt unter einen kleinen Hahn, sodass Ihr eine Probe für die Schattenpriesterin Vandis am Bollwerk entnehmen könnt.", objectives = "Begebt Euch zu Gahrrons Trauerfeld in den Westlichen Pestländern, um den dortigen Kessellord zu suchen und zu besiegen. Verwendet dann seinen Schlüssel, um Zugang zum Kessel zu erhalten. Ihr müsst die leere Flasche: Gahrrons Trauerfeld bei Euch haben, um eine Probe des Giftes zu entnehmen, das sich in dem Kessel findet.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[5226] = { id = 5226, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr zum Chillwind-Lager", description = "Ihr schließt sorgfältig den Hahn in der Zugangsklappe und beobachtet, wie das faulige Sekret des Kessels in die leere Flasche tropft.\n\nMit dem Gift in der Hand ist es Zeit, zur Hohepriesterin MacDonnell an der Chillwindspitze zurückzukehren, um die Mission abzuschließen.", progress = "Gahrrons Trauerfeld beherbergt den letzten Kessel hier im Westen, zu dem wir Zugang brauchen. Wenn wir eine Probe der Seuche haben, die er ausspeit, können wir unsere Reagenzien durch vier separate Gefäße in die Umgebung entlassen. Die Geißel wird es schwer haben, um uns von allen vieren fern zu halten, selbst mit der Kraft von Kel'Thuzad hinter sich.", completion = "Herzlichen Glückwunsch, {name}, Ihr habt den letzten Kessel für uns entriegelt! Alchimist Arbington wird bald wissen, welche Reagenzien für die Mischung dieses Kessels erforderlich sind.\n\nWas Euch angeht, so bin ich sicher, dass Kommandant Valorfist Euch persönlich für die Hilfe, die Ihr uns habt angedeihen lassen, danken will. Ohne Euch wäre unser Kampf gegen die Geißel nahezu unmöglich gewesen. Danke, oh Held!", objectives = "Bringt die gefüllte Flasche: Gahrrons Trauerfeld zur Hohepriesterin MacDonnell an der Chillwindspitze, Westliche Pestländer.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[5227] = { id = 5227, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Kessel von Gahrrons Trauerfeld", progress = "Der Seuchenkessel der Geißel steht vor Euch und speit große Mengen Toxin in die Luft. Eine kleine, unauffällige Zugangsklappe befindet sich in der großen Plattform des Kessels.\n\nDa Ihr den Kessellord bereits besiegt und seinen Schlüssel an Euch genommen habt, könnt Ihr die geeigneten Reagenzien in den Kessel geben, um ein Gegenmittel gegen die Seuche zu schaffen.", completion = "Nach Hinzufügen der Reagenzien zu dem Gemisch des Kessels beginnt sich die Farbe und Beschaffenheit der Wolke zu ändern, die er ausspeit. Angehörige der Geißel, die sich irgendwo in der Nähe des Kessels befinden, scheinen zu straucheln, als die neuen Komponenten in die Umgebung gelangen." }
quests[5228] = { id = 5228, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Geißelkessel", description = "In den Ländern des ehemaligen Lordaeron befinden sich acht Kessel - vier im Westen und vier weitere verschanzt im Osten. Diese Kessel speien Gifte in die Luft und verbreiten die Seuche für die Geißel im ganzen Land.\n\nDie nekromantische Macht von Kel'Thuzad ist zu stark, um diese Kessel gänzlich zu schließen, aber wir glauben zu wissen, wie wir sie zu unserem Vorteil nutzen könnten. Meine rechte Hand, die Schattenpriesterin Vandis wird Eure Kontaktperson für diesen Auftrag sein; sie wird die Einweisung fortsetzen.", completion = "Aus den Schatten, Bruder {race}, entbiete ich meine Grüße. Ich werde als Eure Koordinatorin für unseren Plan zur Sabotage der Kessel der Geißel dienen.\n\nUnser Ziel wird darin bestehen, die Zusammensetzung der Seuche, die die Kessel erzeugen, in etwas zu verwandeln, das sich negativ auf die Geißel auswirkt. Um diese Veränderung zu bewirken, müsst Ihr freien Zugriff auf jeden der vier Kessel hier in den Westlichen Pestländern sicherstellen.\n\nDie Zeit ist gekommen, dass Ihr den Sturm gegen die Geißel anführt.", objectives = "Sprecht mit der Schattenpriesterin Vandis am Bollwerk, Westliche Pestländer.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[5229] = { id = 5229, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ziel: Teufelssteinfeld", description = "Von den vier Kesseln, die sich in den Westlichen Pestländern befinden, ist derjenige, der sich im Teufelssteinfeld befindet, wohl der, zu dem der Zugang am einfachsten ist. Die Geißel hat hier Truppen mit weniger Erfahrung positioniert, sie sollten aber trotzdem nicht unterschätzt werden.\n\nGeht zum Teufelssteinfeld, direkt östlich von hier und nordwestlich von Andorhal, und befasst Euch dort mit dem Kessellord. Er hat einen Schlüssel bei sich, der den Zugang zu dem Kessel freigeben wird. Wenn er frei ist, benutzt diese Flasche, um dem Kessel eine Probe des Giftes zu entnehmen; wir benötigen sie für die Entwicklung eines Gegenwirkstoffs.", progress = "Die Zugangsklappe zum Kessel bleibt fest verschlossen. Um sie zu öffnen, müsst Ihr den Schlüssel finden.", completion = "Der Schlüssel, den Ihr dem Kessellord Gallenschlund abgenommen habt, passt perfekt zu der Zugangsklappe, verschwindet aber, nachdem Ihr ihn benutzt habt. Ihr habt aber so ein Gefühl, dass Ihr den Zugang jetzt auch ohne einen Schlüssel öffnen könnt. Ein fauliger Geruch entweicht der geöffneten Klappe, während eine unbekannte Mischung aus konzentrierten Substanzen im Kessel umherwirbelt.\n\nDie Flasche passt perfekt unter einen kleinen Hahn, sodass Ihr eine Probe für die Schattenpriesterin Vandis am Bollwerk entnehmen könnt.", objectives = "Geht zum Teufelssteinfeld im den Westlichen Pestländern. Sucht nach dem dortigen Kessellord und besiegt ihn. Er könnte einen Schlüssel haben, der den Zugang zu dem Kessel ermöglicht. Ihr müsst die leere Flasche: Teufelssteinfeld bei Euch haben, um eine Probe des Giftes zu entnehmen, das sich in dem Kessel findet.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[5230] = { id = 5230, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr zum Bollwerk", description = "Ihr füllt die Flasche mit einer ausreichenden Menge des giftiges Gebräus aus dem Kessel, sodass es für eine Probe zur Untersuchung reicht.\n\nMit dem Gift in der Hand ist es Zeit, zur Schattenpriesterin Vandis am Bollwerk zurückzukehren, um die Mission abzuschließen.", progress = "Willkommen in der relativen Sicherheit des Bollwerks, {name}. Welche Fortschritte könnt Ihr bezüglich der Kessel berichten?", completion = "Gut gemacht {name} - Apotheker Dithers sollte in der Lage sein, dies umgehend zu analysieren und ein Gegenmittel zu entwickeln, das wir dann in den Kessel geben. Wenn wir genug davon in die Luft pumpen können, sind wir vielleicht in der Lage, alle hier präsenten Mitglieder der Geißel zu schwächen.\n\nDiese Aktion wird sich ohne Zweifel über längere Zeit hinziehen; wir müssen der Mischung in diesen Kesseln ständig unsere Reagenzien hinzufügen. Wenn wir das aufrechterhalten können, werden wir einen großen Vorteil gegenüber der Geißel haben, wenn die Zeit für den Kampf gekommen ist!", objectives = "Bringt die gefüllte Flasche: Teufelssteinfeld zur Schattenpriesterin Vandis am Bollwerk, Westliche Pestländer.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[5231] = { id = 5231, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ziel: Dalsons Tränenfeld", description = "Einer der Seuchenkessel befindet sich auf dem Feld eines ehemaligen Bauernhauses, das jetzt Dalsons Tränenfeld genannt wird. Heute werden keine Tränen vergossen, {class}; wir müssen bei diesem Kessel zuschlagen und Zugang zu ihm erlangen!\n\nBegebt Euch zu Dalsons Tränenfeld, fast direkt nördlich von Andorhal, und eliminiert den Kessellord dort. Er sollte, wie der Letzte auch, einen Schlüssel haben, durch den Ihr ans Innere des Kessels gelangen könnt. Benutzt diese Flasche, um eine Probe aus dem Kessel zu entnehmen; jeder Kessel enthält ein jeweils für ihn einzigartiges Gebräu aus Toxinen, das nur er benutzt.", progress = "Die Zugangsklappe zum Kessel bleibt fest verschlossen. Um sie zu öffnen, müsst Ihr den Schlüssel finden.", completion = "Der Skelettschlüssel des Kessellords gleitet problemlos in ein Schlüsselloch und verschwindet dann, wodurch Ihr permanenten Zugriff darauf habt. Kunstlose, zähflüssige Sekrete pulsieren durch die geschwungenen Röhren im Unterbau des Kessels.\n\nDie Flasche passt perfekt unter einen kleinen Hahn, sodass Ihr eine Probe für die Schattenpriesterin Vandis am Bollwerk entnehmen könnt.", objectives = "Begebt Euch zu Dalsons Tränenfeld in den Westlichen Pestländern, um den dortigen Kessellord zu suchen und zu besiegen. Verwendet dann seinen Schlüssel, um Zugang zum Kessel zu erhalten. Ihr müsst die leere Flasche: Dalsons Tränenfeld bei Euch haben, um eine Probe des Giftes zu entnehmen, das sich in dem Kessel findet.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[5232] = { id = 5232, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr zum Bollwerk", description = "Vorsichtig füllt Ihr so viel, wie Ihr für eine sinnvolle Probe für nötig erachtet, von dem Sekret aus dem Kessel in die Flasche.\n\nMit dem Gift in der Hand ist es Zeit, zur Schattenpriesterin Vandis am Bollwerk zurückzukehren, um die Mission abzuschließen.", progress = "Wir wissen, dass sich in jedem Kessel ein anderes Gemisch von Reagenzien befindet, mit denen das Seuchen verursachende Toxin erzeugt wird. Dementsprechend müssen wir auch ein Gegenmittel entwickeln, das für jeden Kessel einzigartig ist. Eure Probe von Dalsons Tränenfeld wird der Schlüssel sein, um den einzigartigen Reagenzienbedarf für diesen Kessel zu bestimmen.", completion = "Ah, darin ist mehr als genug für die Untersuchungen. Gut gemacht, {name}!\n\nJetzt liegt der nächste Schritt bei uns. Wir werden eine Liste von Reagenzien erstellen, die in Kombination mit dem, was sich bereits in dem Kessel befindet, als Gegenmittel wirken.\n\nWir können dies allerdings nur umsetzen, indem die Reagenzien direkt in den Kessel gegeben werden. Apotheker Dithers dürfte weitere Informationen darüber haben, also sprecht mit ihm, sobald es Euch beliebt.", objectives = "Bringt die gefüllte Flasche: Dalsons Tränenfeld zur Schattenpriesterin Vandis am Bollwerk, Westliche Pestländer.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[5233] = { id = 5233, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ziel: Das trostlose Feld", description = "Zwei Kessel wurden erfolgreich geöffnet. Auf diese könnt Ihr jetzt zwar unbegrenzt zugreifen, aber wir möchten immer noch, dass Ihr die beiden verbleibenden öffnet. Damit erhielten wir weitere Möglichkeiten, den Gegenwirkstoff einzusetzen!\n\nDieses Mal werdet Ihr Euch um den Kessel des trostlosen Felds kümmern. Er befindet sich ziemlich genau östlich von Andorhal, relativ nahe bei den zerstörten Stadtmauern. Eliminiert auch dort den Kessellord, um an den Schlüssel zu gelangen. Benutzt diese Flasche, um eine Probe aus dem Kessel zu entnehmen.\n\nGute Jagd, {name}!", progress = "Die Zugangsklappe zum Kessel bleibt fest verschlossen. Um sie zu öffnen, müsst Ihr den Schlüssel finden.", completion = "Der Schlüssel des Kessellords entriegelt die Zugangsklappe zu diesem Kessel und verschwindet dann, ähnlich wie die anderen Schlüssel für die vorherigen Kessel, um die Ihr Euch gekümmert habt. Eine faulig riechende Substanz brodelt heftig unter der Plattform des Kessels.\n\nDie Flasche passt perfekt unter einen kleinen Hahn, sodass Ihr eine Probe für die Schattenpriesterin Vandis am Bollwerk entnehmen könnt.", objectives = "Begebt Euch zum trostlosen Feld in den Westlichen Pestländern, um den dortigen Kessellord zu suchen und zu besiegen. Verwendet dann seinen Schlüssel, um Zugang zum Kessel zu erhalten. Ihr müsst die leere Flasche: Das trostlose Feld bei Euch haben, um eine Probe des Giftes zu entnehmen, das sich in dem Kessel findet.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[5234] = { id = 5234, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr zum Bollwerk", description = "Vorsichtig füllt Ihr die leere Flasche. Jetzt schwappt eine Probe der stinkenden Substanz, die unter der Plattform des Kessels brodelt, in dem zerbrechlichen Glasbehälter herum.\n\nMit dem Gift in der Hand ist es Zeit, zur Schattenpriesterin Vandis am Bollwerk zurückzukehren, um die Mission abzuschließen.", progress = "Wenn wir erst die Probe vom Kessel des trostlosen Felds analysiert haben, wird sie uns einen dritten Weg bieten, um die Geißel mit einem verheerenden Gegenmittel zu schlagen!", completion = "Wieder habt Ihr eine Mission hervorragend durchgeführt, {name}! Damit stehen uns drei Kessel zur Verfügung, die wir gegen die Geißel einsetzen können. Wenn die nekromantische Herrschaft von Kel'Thuzad über diese Länder nicht so stark wäre, wie sie es derzeit ist, würde ich sagen, dass Ihr sie ganz erledigt habt.\n\nApotheker Dithers wird einen Bericht darüber anfertigen, was dieser Kessel - genau wie jeder andere von uns veränderte Kessel - benötigt, um unser Gegenmittel gegen die Seuche einzusetzen. Damit ist die Zeit gekommen, den letzten Kessel im Westen unter unseren Einfluss zu bringen!", objectives = "Bringt die gefüllte Flasche: Das trostlose Feld zur Schattenpriesterin Vandis am Bollwerk, Westliche Pestländer.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[5235] = { id = 5235, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ziel: Gahrrons Trauerfeld", description = "Der letzte verbleibende Kessel befindet sich auf einem Hof, der jetzt Gahrrons Trauerfeld genannt wird. Er wird durch einige der stärkeren Diener der Geißel bewacht... um genau zu sein durch Gespenster und Geisterscheinungen. Die darf man nicht unterschätzen, {name}.\n\nGahrrons Trauerfeld liegt weit im Osten vom Bollwerk aus gesehen, etwa dort, wo die Östlichen Pestländer beginnen. Eliminiert auch dort den Kessellord, um an den Schlüssel zu gelangen. Hier ist Eure leere Probenflasche; bringt sie mir gefüllt zurück. Mögen die Schatten Euch für diese gefährliche Mission in Sicherheit hüllen, {class}.", progress = "Die Zugangsklappe zum Kessel bleibt fest verschlossen. Um sie zu öffnen, müsst Ihr den Schlüssel finden.", completion = "Der Schlüssel des Kessellords Rachseele löst sich auf, als er das Schloss der Zugangsklappe im Fundament der Kesselplattform berührt. Im Inneren erklingt ein leicht rasselndes Geräusch. Als die Zugangsklappe aufschwingt, enthüllt sie weitere zähflüssige Toxine im System des Kessels.\n\nDie Flasche passt perfekt unter einen kleinen Hahn, sodass Ihr eine Probe für die Schattenpriesterin Vandis am Bollwerk entnehmen könnt.", objectives = "Begebt Euch zu Gahrrons Trauerfeld in den Westlichen Pestländern, um den dortigen Kessellord zu suchen und zu besiegen. Verwendet dann seinen Schlüssel, um Zugang zum Kessel zu erhalten. Ihr müsst die leere Flasche: Gahrrons Trauerfeld bei Euch haben, um eine Probe des Giftes zu entnehmen, das sich in dem Kessel findet.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[5236] = { id = 5236, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr zum Bollwerk", description = "Ihr schließt sorgfältig den Hahn in der Zugangsklappe und beobachtet, wie das faulige Sekret des Kessels in die leere Flasche tropft.\n\nMit dem Gift in der Hand ist es Zeit, zur Schattenpriesterin Vandis am Bollwerk zurückzukehren, um die Mission abzuschließen.", progress = "Gahrrons Tränenfeld beherbergt den letzten Kessel, zu dem wir hier im Westen Zugang brauchen. Wenn wir eine Probe der Seuche von diesem Kessel haben, können wir unsere Reagenzien durch vier separate Gefäße in die Umgebung entlassen. Die Geißel wird es schwer haben, um uns von allen vieren fern zu halten, selbst mit der Kraft von Kel'Thuzad hinter sich.", completion = "Herzlichen Glückwunsch, {name}, Ihr habt den letzten Kessel für uns entriegelt! Apotheker Dithers wird bald wissen, welche Reagenzien für die Mischung dieses Kessels erforderlich sind.\n\nWas Euch angeht, so bin ich sicher, dass Hochexekutor Derrington Euch persönlich für die Hilfe, die Ihr uns habt angedeihen lassen, danken will. Ohne Euch wäre unser Kampf gegen die Geißel nahezu unmöglich gewesen. Ich danke Euch, {class}.", objectives = "Bringt die gefüllte Flasche: Gahrrons Trauerfeld zur Schattenpriesterin Vandis am Bollwerk, Westliche Pestländer.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[5237] = { id = 5237, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mission erfüllt!", sourceObjective = "{name}, Eure erfolgreiche Umarbeitung der Kessel ist ein überwältigender Sieg für uns!\n\n\n\nAlle, die sich hier in meinem Umfeld befinden, mögen Folgendes hören: Für Dienste am Königreich Stormwind und der Allianz, die über die gebotenen Pflichten hinausgingen - trotz wenig Erfolg versprechender Chancen und im Angesicht unglaublicher Gefahren, möchte ich {name} dies geben und ihn unserer unvergänglichen Dankbarkeit als wahren Helden der Allianz versichern. Danke, sage ich!", sourceObjectiveStatus = "unverified-source-field" }
quests[5238] = { id = 5238, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mission erfüllt!", sourceObjective = "{name}, Eure erfolgreiche Umarbeitung der Kessel ist ein überwältigender Sieg für uns!\n\n\n\nAlle, die sich hier in meinem Umfeld befinden, mögen Folgendes hören: Für Dienste an den Verlassenen und an der Horde, die weit über die erwarteten Pflichten hinausgingen - trotz wenig Erfolg versprechender Chancen und im Angesicht unglaublicher Gefahren, möchte ich {name} dies geben und ihn unserer unvergänglichen Dankbarkeit als wahren Helden der Horde versichern. Hussah!", sourceObjectiveStatus = "unverified-source-field" }
quests[5241] = { id = 5241, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Onkel Carlin", description = "Manchmal kann ich nachts meinen Onkel Carlin weinen hören. Es klingt, als ob er weit weg wäre, im Osten.\n\nIch hoffe, dass er nicht um mich weint! {name}, werdet Ihr meinen Onkel suchen und ihm sagen, dass es mir gut geht?\n\nWenn Ihr ihn findet, sagt ihm, dass ich auf ihn warte und die Geschichte hören möchte, die er immer erzählt hat... die über die Hasen und die Marmelade! Die Geschichte ist so lustig!", completion = "Ihr habt Pamela gesehen? Sie lebt?\n\nSie ist tot? Nein! Oh, Pamela! Warum leidet dein Geist nur immer noch in dieser Welt... Warum bist du umgekommen, während das Schicksal mich am Leben erhält? Ich würde sofort mit dir tauschen und durch das tote Darrowshire wandern, als Geisterscheinung und allein!\n\nAch, aber diese Neuigkeiten können das Schicksal nicht ändern. Ich danke Euch, {name}. Jetzt brennt meine Pflicht, meine Pflicht zur Rache, so heiß wie noch nie.", objectives = "Sucht Carlin Redpath.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[5242] = { id = 5242, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der endgültige Schlag", description = "Leider scheint die einzige Möglichkeit, diese Bedrohung für den Teufelswald zu stoppen, ein Frontalangriff zu sein. Es gibt keine anderen Wege in die Schattenfeste und ich habe keine Möglichkeit, Euch ins Innere zu teleportieren. Der gerade Weg hinab in die Tiefe ist der einzige Weg... und ich weiß auch, wen Ihr aufsuchen solltet. Sein Name ist Fel'dan ... Schattenlord Fel'dan. Er ist der Sterbliche, der dort unten die Macht hat... er ist der Kopf der Schlange. Tötet ihn und seine beiden Sukkubus-Diener und kehrt zu mir zurück. Fel'dan ist derjenige, der Pakte mit der Legion schließt. Er muss aufgehalten werden.", progress = "Ohne Fel'dan werden die Mitglieder des Schattenrates hoffentlich ihr Ziel aus den Augen verlieren und untereinander zu streiten beginnen. Sie werden um die Macht kämpfen und Reichtümer für zukünftige Pläne anhäufen. Das wird eine günstige Zeit sein, um sie und ihre Dämonensklaven zu vernichten.", completion = "Gelobt sei die Erdenmutter, {name}! Danke! Das ist wirklich ein großer Tag!\n\nDer Schattenrat wird es nach diesem Schlag gegen seine Hierarchie schwer haben, wieder in demselben Maße Macht zu erlangen wie zuvor. Heute habt Ihr etwas Großes geleistet!", objectives = "Tötet Moora und Salia und bringt den Kopf von Schattenlord Fel'dan zu Greta Mosshoof im Teufelswald.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[5243] = { id = 5243, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Häuser der Heiligen", description = "Ich sehe meinen Untod als eine Krankheit an, {race}. Eine Krankheit, die einfach nur eine Behandlung erfordert; sie ist aber auch ein großer Segen für die Argentumdämmerung. Wie kann man die Heiden der Geißel besser schlagen als durch den Untod?\n\nIch werde von meinen Kollegen wegen der Opfer, die ich dargebracht habe, geachtet, aber das Lob bedeutet mir nichts.\n\nWenn Ihr daran interessiert seid, der Argentumdämmerung zu helfen, kann ich Euch einen Auftrag anbieten.\n\nBegebt Euch nach Stratholme und holt unsere Reserven an heiligem Wasser. Durchsucht die Vorratskisten.", progress = "Seid vorsichtig, vermutlich haben nicht alle Vorratskisten die Zerstörung der Stadt überstanden. Die Geißel wagt es zwar nicht, das Wasser zu berühren, aber das heilige Wasser wird sicherlich keine Verseuchung durch Gezücht verhindern.", completion = "Gut gemacht, {race}. Ihr habt bewiesen, dass Ihr, auch wenn Ihr anderen gegenüber tolerant seid, vor nichts Halt machen werdet, um die Diener von Kel'Thuzad zu vernichten.", objectives = "Begebt Euch nach Stratholme im Norden. Durchsucht die Vorratskisten, die über die Stadt verstreut sind, und holt 5 Einheiten Heiliges Wasser von Stratholme. Kehrt zu Leonid Barthalomew dem Geachteten zurück, wenn Ihr genug der gesegneten Flüssigkeit gesammelt habt.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[5244] = { id = 5244, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Ruinen von Kel'Theril", description = "Die Geschichte hinter Kel'Theril ist die eines verfluchten Volkes, gebunden an den Ort, an dem es ein unglückliches Ritual versuchte...\n\nDie Hochgeborenen, die Ihr dort finden werdet, stahlen einst ein hochheiliges Artefakt in dem Glauben, dass sie seine Macht für sich selbst nutzen und so noch mächtiger werden könnten. Durch ihre Bemühungen zerbrach das Relikt in einer gewaltigen Explosion, bei der die Teile unter das Eis des Sees getrieben wurden...\n\nSprecht mit Jaron Stoneshaper, wenn Ihr mehr erfahren möchtet; er hat das Gebiet vor kurzem besucht und kann Euch mehr berichten.", completion = "Nun ja, sicher, ich kann Euch mehr über Kel'Theril berichten. Wohlgemerkt, ich bin kein Historiker, aber ich kann Euch erzählen, was ich dort sah...", objectives = "Sprecht mit Jaron Stoneshaper in Starfall.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[5245] = { id = 5245, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die gequälten Seelen von Kel'Theril", description = "Die Geister der Hochgeborenen sind erbärmliche Kreaturen, das ist mal sicher. Sie suchen immer noch nach Teilen dessen, was sie für immer nach Kel'Theril verdammte - das gestohlene Relikt.\n\nWenn Ihr so daran interessiert seid, nehmt meine Hacke und geht nach Süden zum See. Seht, ob Ihr die Teile des Relikts aus dem Eis holen könnt.\n\nWas Ihr da finden werdet, darüber kann ich Euch nichts sagen, aber ich kenne jemanden, der es vielleicht kann... Aurora Skycaller; sie lebt beim Nordpassturm im nördlichen Teil der Östlichen Pestländer.", progress = "Warum kommt Ihr hierher?", completion = "Über die Vergangenheit der Hochelfen möchte ich nicht gern sprechen, {name}. Bitte, es schmerzt mich, an all das zu denken, was geschehen ist... Und es gibt keine Möglichkeit, die Dinge wieder in Ordnung zu bringen.", objectives = "Benutzt Jarons Hacke, um die vier Fragmente des Hochgeborenenrelikts zu suchen. Bringt sie zu Aurora Skycaller in den Östlichen Pestländern.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[5246] = { id = 5246, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fragmente der Vergangenheit", description = "Ich wusste nicht, dass... Vergebt mir meine harten Worte, {class}.\n\nÜber die Fehler meiner Vorfahren möchte ich mich nicht auslassen, aber wenn Eure Bitte wirklich echt ist, dann werde ich Euch helfen.\n\n<Aurora untersucht die Fragmente.>\n\nIch glaube, dass dies der Kristall von Zin-Malor ist, ein Artefakt, das starke arkane Kräfte fesseln und kontrollieren kann. Es hätte für das Gute genutzt werden können, aber die bösen Absichten derjenigen, die es stahlen, ließen es zersplittern.\n\nBegebt Euch zum Tempel von Zin-Malor in Azshara - ich kann nur hoffen, dass das Buch noch dort ist.", progress = "Nur mit Hilfe der Seiten der hochheiligen Schriften kann ich erkennen, ob ich Euch helfen kann oder nicht...", completion = "Die Seiten wurden seit vielen, vielen Jahren nicht mehr berührt...", objectives = "Sucht die hochheiligen Schriften der Hochgeborenen im Tempel von Zin-Malor in Azshara und bringt sie zu Aurora Skycaller beim Nordpassturm in den östlichen Pestländern.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[5247] = { id = 5247, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fragmente der Vergangenheit", description = "Ich kann Euch helfen, wenn Ihr das Artefakt wirklich wiederherstellen wollt.\n\nUm die Teile wieder zusammenzufügen und zu versiegeln, werde ich Gegenstände mit starken magischen Eigenschaften benötigen. Einen verzauberten Thoriumbarren und fünf Kristallflicker ... Ihr werdet außerdem etwas Wasser von einem seltsam anmutenden Ort holen müssen ... Sucht den Düsterteich entlang der Eldrethgasse in Düsterbruch in Feralas auf und füllt dort diese Phiole.\n\nWährend Ihr unterwegs seid, werde ich versuchen, diesen Seiten das Wissen zu entnehmen, das ich benötige, um den Schaden zu reparieren, der an dem Relikt verursacht wurde.", progress = "Das Relikt muss in die Hände der absolut Vertrauenswürdigsten gelegt werden. Es darf nicht wieder gestohlen werden...", completion = "Mit diesen Elementen kann ich die Fragmente zusammenfügen... hoffentlich zu dem, was sie einst waren.", objectives = "Bringt einen verzauberten Thoriumbarren, 5 Kristallflicker und eine Phiole mit Düsterwasser zu Aurora Skycaller beim Nordpassturm in den östlichen Pestländern.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[5248] = { id = 5248, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gequält von der Vergangenheit", description = "{name}, ich weine ob dessen, was in der Vergangenheit geschehen ist. Wie dieser Kristall wurden auch die Elfen als Volk zerschmettert. Ich weiß nicht, ob die Teile jemals wieder zu einem vereinigt werden können, aber meine Trauer wurde dadurch gelindert, dass ich Euch bei dieser kleinen Aufgabe helfen konnte. \n\nWir dürfen die Vergangenheit nicht vergessen, {name} ...\n\nBringt bitte den Kristall von Zin-Malor zurück zum Kel'Therilsee. Ihr müsst einen Geist eines Hochgeborenen finden, der erkennt, was für ein Fehler vor so langer Zeit begangen wurde. Zeigt dem Geist, dass wir die Dinge wieder in Ordnung gebracht haben.", progress = "Verrrrrrflucht... Fürrrr immmmerrrr...", completion = "Bitteeeeee, lasssssst miiiiiiiiich...", objectives = "Bringt den Kristall von Zin-Malor zum Kel'Therilsee in Winterspring und sucht einen Geist eines Hochgeborenen, der mit Euch sprechen will.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[5249] = { id = 5249, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nach Winterspring!", description = "In Winterspring, nördlich von hier, gibt es viele alte Elfenruinen. Es ist ein raues Land, aber man kann dort viele Geheimnisse und Orte erkunden.\n\nBei der vielen Arbeit, die hier im Teufelswald meiner harrt, hatte ich keine Gelegenheit, nach Winterspring zu reisen. Aber es gibt keinen Grund, warum Ihr es nicht tun solltet!\n\nWährend Ihr dort seid, sucht doch nach Wynd Nightchaser. Er verbringt den Großteil seiner Zeit in Starfall und er weiß viel über die Gegend.", completion = "Ein Freund von Ivy Leafrunner? Ich freue mich, Euch kennen zu lernen, {name}.", objectives = "Sucht Starfall in Winterspring und sprecht mit Wynd Nightchaser.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[5250] = { id = 5250, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Starfall", description = "In Winterspring, nördlich des Teufelswaldes, gibt es viele alte Elfenruinen. Es ist ein raues Land, aber man kann dort viele Geheimnisse und Orte erkunden.\n\nMeine Studien hier beschäftigen mich so sehr, dass ich seit einiger Zeit keine Gelegenheit mehr hatte, nach Winterspring zu reisen. Aber es gibt keinen Grund, warum Ihr nicht dorthin reisen und die Ruinen erforschen solltet.\n\nWährend Ihr dort seid, sucht doch nach Wynd Nightchaser. Er verbringt den Großteil seiner Zeit in Starfall und er weiß viel über die Gegend.\n\nSagt ihm, dass Ihr einer meiner Schüler seid ...", completion = "Ein Schüler von Daryn Lightwind? Ich freue mich, Euch kennen zu lernen, {name}.", objectives = "Sucht Starfall in Winterspring und sprecht mit Wynd Nightchaser.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[5251] = { id = 5251, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Archivar", description = "Alles, was zum Extremen getrieben wird, ist für unsere Welt gefährlich, {name}. Nehmt zum Beispiel den Scharlachroten Kreuzzug. Glaubt Ihr, dass der blinde Fanatismus seiner Anhänger etwas Gutem dient? Wie viele Unschuldige haben sie im Namen des Lichts vernichtet?\n\nGotteslästerer, alle zusammen!\n\nEiner interessiert mich aber besonders, der Archivar Galford von Stratholme: ein Mann, der über die wertvollsten Dokumente des Kreuzzugs wacht. Vernichtet ihn und verbrennt seine Archive! Wenn Ihr erfolgreich seid, kehrt zu mir zurück und Ihr werdet belohnt.", completion = "Phantastisch, {name}! Über Jahre hinweg gesammelte Informationen, verloren! Der Scharlachrote Kreuzzug wird diesen Schlag in den folgenden Wochen sicherlich spüren.", objectives = "Reist nach Stratholme und sucht Archivar Galford vom Scharlachroten Kreuzzug. Vernichtet ihn und verbrennt das Scharlachrote Archiv.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[5252] = { id = 5252, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reuevolle Hochgeborene", description = "Der... der Kristall...\n\nDie Hochgeborenen hier sssind durch ihr eigenessss Elend verwirrrrt...\n\nIch bin betrrrrübt, aber ich erkenne den Fehlerrr dessen, wassss vor so langer Zeit geschah. Obwohl esss keine Möglichkeit giiibt, die Vergangenheit zu ändern, habe ich nun Friiiieden gefunnnnden, da ich weiß, dass Ihr den Kristall von Zin-Malor wiederbeschafft habt...\n\nIiihr müsssssst ihn zurückbringennnn...\n\nEr muuussss zurückgebracht werrrdennnn.", progress = "Es ist eine Weile her, seit Ihr weggegangen seid, {name}. Wie ist es Euch ergangen?", completion = "Ist das... für was ich es halte?", objectives = "Sprecht mit Wynd Nightchaser in Starfall und fragt nach dem richtigen Ort für den Kristall von Zin-Malor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[5253] = { id = 5253, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Kristall von Zin-Malor", description = "Recht eindrucksvoll, {name}.\n\nDer Kristall von Zin-Malor kann niemals in den Tempel zurückgebracht werden, der, wie Ihr wisst, nur noch eine Ruine ist. Aber ich finde, dass Eure Bemühung, das Böse der Vergangenheit ungeschehen zu machen, nicht ohne Belohnung bleiben soll.\n\nSucht den Erzdruiden Fandral Staghelm in Darnassus auf und bringt ihm den Kristall, {name}. Er sollte sich in den Händen derer befinden, die seine Macht nicht missbrauchen werden. Wie es aussieht, sind von den stärksten Magieanwendern nur eine Hand voll in der Lage, solch eine Macht zu kontrollieren.", progress = "Ja, {race}?", completion = "Ich habe von dem Kristall von Zin-Malor gehört; der Benutzer des Kristalls wird unglaublicher arkaner Macht fähig, aber nur, wenn er wirklich würdig ist. Ich bin beeindruckt, dass Ihr nicht nur den Kristall wiederbeschafft habt, sondern auch Eure eigenen Grenzen erkannt und nicht versucht habt, den Kristall selbst zu benutzen.\n\nDanke, dass Ihr ihn mir gebracht habt, {name}. Wir werden ihn sicher aufbewahren, und mögen die verfluchten Geister, die den zerbrochenen Kristall einst bewachten, endlich ihren Frieden finden.", objectives = "Überbringt dem Erzdruiden Fandral Staghelm in Darnassus den Kristall von Zin-Malor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[5261] = { id = 5261, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eagan Peltskinner", description = "Eagan Peltskinner sucht nach jemandem, der für ihn Wölfe jagt. Das ist gut, da wir es hier im Nordhaintal in letzter Zeit verstärkt mit Wölfen zu tun haben.\n\nWenn Ihr interessiert seid, dann sprecht mit Eagan. Ihr findet ihn neben der Abtei, auf der linken Seite.", completion = "Das ist wahr. Ich suche nach jemandem, der für mich Wölfe jagt! Seid Ihr diese Person?", objectives = "Sprecht mit Eagan Peltskinner.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[5262] = { id = 5262, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Wahrheit zeigt sich mit Macht", description = "Ihr versucht, Eure Gedanken zu sammeln, während sich der Staub in der Kammer wieder setzt. Ihr geht in Gedanken die Ereignisse durch, die sich gerade ereignet haben, und könnt dennoch die Schwere der Situation nicht verstehen.\n\nDer oberste Kreuzzügler des Scharlachroten Kreuzzugs ein Dämon? Und nicht nur irgendein Dämon, sondern der Bruder von Varimathras, Erzlord von Undercity?\n\nIhr verstaut den abgetrennten Kopf des Schreckenslords sorgfältig in Eurem Rucksack. Natürlich würde Euch niemand diese Geschichte ohne Beweise glauben.\n\nFürst Nicholas Zverenhoff muss sofort davon erfahren!", progress = "Was habt Ihr denn da, {name}?", completion = "Was bedeutet das für den Kreuzzug? Könnte es wirklich sein, dass seine Mitglieder sich unter der Kontrolle dieses Dämons befanden? Und unwissentlich als Bauern für ein größeres Übel dienten?", objectives = "Bringt den Kopf von Balnazzar zu Fürst Nicholas Zverenhoff in den Östlichen Pestländern.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[5263] = { id = 5263, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Übertroffen", description = "Ihr zeigt eine natürliche Begabung für die Kunst der Zerstörung und Ihr folgt Befehlen. Es ist selten, dass beides zusammentrifft. In mir keimt immer mehr der Gedanke, dass Ihr ein hervorragendes Mittel göttlicher Gerechtigkeit darstellen könntet.\n\n<Zverenhoff verschränkt seine Hände vor seinem Gesicht.>\n\nDer Laufbursche von Kel'Thuzad regiert über Stratholme. Beweist mir, dass Ihr ein Held seid - mein Held. Vernichtet Baron Rivendare und kehrt mit seinem Kopf zu mir zurück.", progress = "Der Baron hat mehr Menschen getötet, als Ihr wahrscheinlich in Eurem Leben gesehen habt.", completion = "Es ist viele Jahre her, dass ich einen Helden in unsere Ränge eingeführt habe. Ihr seid der Erste, dem seit Jahren eine Audienz bei Lord Maxwell gewährt wird.", objectives = "Zieht nach Stratholme und vernichtet Baron Rivendare. Nehmt seinen Kopf und kehrt zu Fürst Nicholas Zverenhoff zurück.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[5264] = { id = 5264, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lord Maxwell Tyrosus", description = "Ich werde Euch eine große Ehre zuteil werden lassen, {name}.\n\nLord Maxwell wünscht, Euch für Euren Dienst an der Argentumdämmerung zu belohnen!\n\nEs ist Jahre her, seitdem Maxwell das letzte Mal einem Außenstehenden eine Audienz gewährt hat.", completion = "Ihr seid ein würdiger Verbündeter, {name}. Ihr sollt die Belohnung für Eure standhafte Hingabe ernten.", objectives = "Sprecht mit Lord Maxwell Tyrosus. Er befindet sich in der Kirche.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[5265] = { id = 5265, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Argentumtresor", description = "Über viele Jahre hinweg blieb der Argentumtresor verschlossen. Niemand war würdig genug, hineinzugreifen und die Macht der Argentumdämmerung herauszunehmen - bis heute.\n\nder Argentumtresor ist nun für Euch geöffnet, {name}.", completion = "Boah...", objectives = "Öffnet den Argentumtresor und nehmt Euch Eure Belohnung.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[5281] = { id = 5281, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die ruhelosen Seelen", description = "Da gibt es diejenigen, die tragisch beim Fall von Stratholme starben. Viele nahmen sich das Leben, entschieden sich dafür, sich lieber selbst in die Myriaden Flammen der glimmenden Stadt zu stürzen, statt einer der Geißel zu werden.\n\nNun ziehen sie als ruhelose Geister durch die Straßen von Stratholme.\n\nWir müssen ihnen helfen, {name}!\n\nIch habe einen Partner namens Egan, der wunderbare Arbeit mit Geistern und Seelen geleistet hat. Sucht ihn auf. Er streift durch die Östlichen Pestländer, in der Nähe von Stratholme, und testet seine Neuheiten.", completion = "Alen hat also endlich jemanden gefunden, der mutig genug ist, hmm?", objectives = "Sucht Egan. Ihr wisst nur, dass er zuletzt in der Nähe von Stratholme gesehen wurde.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[5282] = { id = 5282, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die ruhelosen Seelen", description = "Ich ziehe meine Macht - meinen Willen, weiter zu leben und zu atmen - aus dem ganzen Hass, den ich der Geißel entgegenbringe, und allem, was sie getan hat. Ich bin aber trotzdem kein Eiferer. Es gibt die, wie die Mitglieder des Scharlachroten Kreuzzugs, die die unschuldigen Untoten eher vernichten würden, als ihnen auch nur ein wenig Mitleid entgegenzubringen.\n\nDas bringt mich zu dem hier: meinem Blaster. Er wird die gequälten Seelen von Stratholme erlösen.\n\nWendet ihn auf die Geisterscheinungen an, die die geplünderten Straßen durchstreifen. Befreit ihre Seelen.", completion = "<Egan wischt eine Träne weg.>\n\nHabt Ihr meine Mutter gesehen, {name}? Habt Ihr sie befreit?\n\nIhr seid ein leuchtendes Beispiel des Anstands.", objectives = "Wendet Egans Blaster auf die geisterhaften und spektralen Bürger von Stratholme an. Wenn die ruhelosen Geister ihre geisterhaften Hüllen sprengen, wendet den Blaster erneut an - dann sind sie endlich frei!\n\nBefreit 15 ruhelose Seelen und kehrt zu Egan zurück.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[5283] = { id = 5283, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Kunst des Rüstungsschmiedes", description = "Tja, Ihr habt 'ne kluge Entscheidung getroffen.\n\nWir haben nix füreinander übrig, ich und der alte Ironus hier. Dieser nichtsnutzige Spielzeughersteller weiß, wer die wahren Handwerker hier sind.\n\nDie wirklich großen Kriege werden mit 'ner guten Verteidigung gewonnen. Wenn's losgeht, wird Euch kein Angriff helfen.\n\nAlso dann, ran an die Arbeit! Ihr müsst mir nur zeigen, dass Ihr über Talent verfügt. Danach reiß ich alle Unreinheiten, die noch in Euch sind, raus und mach einen Rüstungsschmied aus Euch. Ihr wisst doch, wie man verschnörkeltes Mithril herstellt, nicht wahr?", progress = "Ah, es geht nichts über eine gute Schmiedebräune. Am Schürzenstreifen kann man erkennen, wer 'ne wirklich gute Bräune hat.", completion = "So, {name}. Danach gibt es keinen Weg zurück. Es ist noch nicht zu spät, Spielzeugmacher, äh, Waffenschmied zu werden.\n\nIch denke, dass Ihr die richtige Entscheidung trefft.", objectives = "Um Rüstungsschmied zu werden, müsst Ihr die folgenden Gegenstände herstellen und zu Grumnus bringen: 4 verschnörkelte Mithrilhelme, 2 verschnörkelte Mithrilstiefel, 1 verschnörkelte Mithrilbrustplatte.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[5284] = { id = 5284, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Weg des Waffenschmieds...", description = "Als Waffenschmied werdet Ihr feststellen, dass sehr häufig Helden und Abenteurer der Ausrüstung wegen zu Euch kommen werden. Wenn die viele Arbeit manchmal auch unerträglich sein kann, macht der Wohlstand aber doch die Rückenschmerzen und die Aschenlunge wett.\n\nOh ja, {name}, Waffenschmiede sind die mit dem ganzen Gold!\n\nWenn Ihr unseren Rängen beitreten wollt, müsst Ihr mir zeigen, dass Ihr mir ein Silberstück oder zwei machen könnt - ich meine, zeigt mir, dass Ihr habt, was man braucht, wenn Menschen Waffen überragender Qualität benötigen. An die Arbeit!", progress = "<Ironus ist damit beschäftigt, goldene Münzen zu ordentlichen kleinen Häufchen zu stapeln.>", completion = "Das wurde auch Zeit! Ich hab Kunden, die warten.\n\nGebt mir die Dinger und hört mir zu. Ihr werdet den ersten Schritt in Eurer Karriere als Waffenschmied machen.", objectives = "Um Waffenschmied zu werden, müsst Ihr die folgenden Gegenstände herstellen und zu Ironus bringen: 4 Mondstahlbreitschwerter, 4 massive Eisenäxte, 2 schwere Mithriläxte und 2 große schwarze Streitkolben.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[5301] = { id = 5301, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Kunst des Rüstungsschmiedes", description = "Zufriedenheit. Das bekomme ich von Hammer und Amboss. Einen stolzen Krieger der Horde zu sehen, der von meinem Stahl geschützt ist, erinnert mich daran, was es heißt, am Leben zu sein. Das ist eine Sucht, die ich niemals ablegen werde, {name}.\n\nIch kann Euch diese Zufriedenheit nicht garantieren, Euch nur auf den Weg dazu bringen. Wie bei allen Bestrebungen des Lebens ist auch der Weg des Rüstungsschmieds eine Reise.\n\nWenn Ihr einer der wenigen Erwählten sein wollt, müsst Ihr nur fragen und ich werde Euch ausbilden, aber zuerst müsst Ihr eine Aufgabe erledigen.", objectives = "Um Rüstungsschmied zu werden, müsst Ihr die folgenden Gegenstände herstellen und zu Okothos bringen: 4 verschnörkelte Mithrilhelme, 2 verschnörkelte Mithrilstiefel, 1 verschnörkelte Mithrilbrustplatte.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[5302] = { id = 5302, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Weg des Waffenschmieds...", description = "Eines Tages werde ich einen legendären Hammer erschaffen. Einen Hammer, der eines Kriegshäuptlings würdig ist!\n\nDas ist mein Lebenswerk, {name}. Meine Leidenschaft. Ich erkenne, dass Ihr das Potenzial habt, zu uns zu gehören, einer von uns zu sein - ein Waffenschmied. Ich bin derjenige, der Euch helfen kann, dieses Potenzial nutzbar zu machen.\n\n Alles, was Ihr dafür erledigen müsst, ist eine einfache Aufgabe. Einfach für jemanden von Eurer außergewöhnlichen Fertigkeit.", progress = "Für den Ruhm der Horde!", completion = "Dies ist der letzte Schritt, bevor Ihr Eure neue Karriere als Waffenschmied beginnen könnt, {name}. Solltet Ihr Euch dazu entscheiden abzuspringen, ist jetzt Eure letzte Gelegenheit dazu. Anderenfalls bereitet Euch darauf vor, vom Wissen verzehrt zu werden!", objectives = "Um Waffenschmied zu werden, müsst Ihr die folgenden Gegenstände herstellen und zu Borgosh bringen: 4 Mondstahlbreitschwerter, 4 massive Eisenäxte, 2 schwere Mithriläxte und 2 große schwarze Streitkolben.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[5305] = { id = 5305, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Süße Beschaulichkeit", description = "In den Grenzen der Scharlachroten Bastion liegt die süße Beschaulichkeit. Der purpurrote Hammerschmied bewacht das Rezept mit seinem Leben. Besiegt ihn und bringt mir seine Schürze. Dafür werde ich Euch zu einem Hammerschmied ausbilden.\n\nIhr müsst eines wissen: Wenn Ihr Euch für den Weg des Hammerschmieds entschieden habt, sind die Wege des Schwertschmieds und des Axtschmieds nicht mehr verfügbar.", objectives = "Begebt Euch nach Stratholme und tötet den purpurroten Hammerschmied. Nehmt die Schürze des purpurroten Hammerschmiedes und kehrt zu Lilith zurück.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[5306] = { id = 5306, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlangenstein der Schattenjägerin", description = "Lasst Euch von ihrer Schönheit nicht narren, {class}. Die Schattenjägerin Vosh'gajin ist todbringend und wahnsinnig.\n\n<Kilram zeigt auf die Narbe in seinem Gesicht.>\n\nJa, die habe ich von ihr - eine Liebkosung, wie sie es nannte.\n\nJetzt endlich ist die Zeit der Rache gekommen.\n\nIhr könnt Vosh'gajin in der Blackrockspitze finden. Erschlagt sie und kehrt mit ihrem Schlangenstein zu mir zurück. Erledigt das und ich werde Euch den Weg eines Axtschmieds weisen.", progress = "Die Legende besagt, dass Vosh'gajins Schlangenstein eine Axt mit einer einzigen Anwendung 1000 Jahre lang messerscharf machen würde!", completion = "Ihr seid Euch also sicher, dass Ihr dies wollt? Ein Axtschmied werden? Denkt daran, die Türen zu Schwertschmied und Hammerschmied werden Euch dann für immer verschlossen sein.", objectives = "Begebt Euch zur Blackrockspitze und erschlagt Schattenjägerin Vosh'gajin. Holt Vosh'gajins Schlangenstein und kehrt zu Kilram zurück.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[5307] = { id = 5307, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verderbnis", description = "Wenn ich mit Euch kurz angebunden bin, dann gibt es einen Grund dafür. Die Pläne für die Erschaffung der großen Klinge, der Verderbnis, wurden von der schwarzen Wache gestohlen: den Skeletteliteeinheiten von Baron Rivendare.\n\nJa, Baron Rivendare von Stratholme.\n\nDer Schwertschmied der schwarzen Wache bewacht diese Pläne nun mit seinem ... Untod.\n\nErschlagt ihn, kehrt mit einem Beweis für diese Tat zurück und ich werde Euch den Weg eines Schwertschmieds weisen.", progress = "Habt Ihr vergessen, welche Aufgabe Euch aufgetragen wurde, {name}?", completion = "Ihr seid Euch also sicher, dass Ihr dies wollt? Ein Schwertschmied werden? Denkt daran, die Türen zu Hammerschmied und Axtschmied werden Euch dann für immer verschlossen sein.", objectives = "Findet den Schwertschmied der schwarzen Wache in Stratholme und vernichtet ihn. Holt die Insignien der schwarzen Wache und kehrt zu Seril Scourgebane zurück.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[5321] = { id = 5321, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Schläfer ist erwacht", description = "Ich war auf dem Weg zu Maestras Posten, um mich mit Liladris Moonriver zu treffen, als ich beschloss, hier anzuhalten und ein kurzes Nickerchen zu machen. Seit ich aus dem Smaragdgrünen Traum aufgewacht bin, bin ich ständig so müde...\n\n<gähnt>\n\nKönntet Ihr mir den Weg zeigen? Ich weiß, dass Maestras Posten südlich von hier ist, entlang der Straße in Ashenvale. Es kann gefährlich werden, daher hoffe ich, dass Ihr einige Freunde habt, die sich uns anschließen werden.\n\nAußerdem könnte ich einschlafen. Wenn Ihr mich also einmal aufwecken müsst, dann benutzt dazu bitte mein Horn. Ihr findet es in der Truhe hier.", progress = "Ist Kerlonian angekommen?", completion = "Oh, ich bin ja so froh, dass Kerlonian es geschafft hat! Und ich bin sicher, dass ich ihn hier irgendwo süß und fest schlafend antreffen werde, nicht wahr?\n\nDanke, dass Ihr ihm den Weg gezeigt habt, {name}.", objectives = "Begleitet Kerlonian Evershade zu Liladris Moonriver in Maestras Posten in Ashenvale.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[5341] = { id = 5341, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Familienvermögen der Barovs", description = "In der Scholomance liegt das Familienvermögen der Barovs. Ich, Alexi Barov, bin einer der beiden letzten verbliebenen Erben des Hauses Barov. Mein Bruder Weldon ist der andere.\n\nWeldon, der jämmerliche Feigling, floh während des Krieges und hielt so an seiner wertlosen Existenz als Mensch fest.\n\nJetzt sucht er nach den Besitzurkunden, damit er das Vermögen für sich beanspruchen kann. Holt die Besitzurkunden, bevor mein Bruder es tut, und ich werde Euch reicher machen, als Ihr je zu träumen gewagt habt.", progress = "Neigt Euer Haupt in meiner Anwesenheit, {race}. Schließlich gehöre ich zum Adel und Ihr seid ein dummer Bauerntölpel.", completion = "Gut gemacht, {race}. Jetzt muss ich mir mein Erbe sichern...", objectives = "Begebt Euch zur Scholomance und holt das Familienvermögen der Barovs zurück. Dieses Vermögen besteht aus vier Besitzurkunden: Es sind die Besitzurkunde für Caer Darrow, die Besitzurkunde für Brill, die Besitzurkunde für Tarrens Mühle und die Besitzurkunde für Southshore. Kehrt zu Alexi Barov zurück, sobald die Aufgabe erledigt ist.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[5342] = { id = 5342, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der letzte Barov", description = "Da mein Bruder noch am Leben ist, wird es möglicherweise einen Disput darüber geben, wer der Hauptbegünstigte des Familienvermögens ist. Das darf nicht sein.\n\nEin niederer Gossenstreuner wie Ihr hat ja wohl nichts gegen einen kleinen kaltblütigen Mord einzuwenden, hoffe ich.\n\nEs ist eine einfache Aufgabe und ich erwarte, dass Ihr sie erfüllt... das heißt, falls Ihr Eure Belohnung erhalten wollt.\n\nWeldon sitzt unter dem Schutz der Allianz im Chillwind-Lager im Osten. Erschlagt ihn, bringt seinen Kopf zurück.\n\n<Alexi gähnt.>\n\nUnd jetzt fort mit Euch.", progress = "Sichert mir mein Vermögen und Ihr erhaltet einen Anteil an der Beute.", completion = "Großartig! Jetzt habe ich allein die Macht und das Vermögen des Hauses Barov!\n\n<Alexi wirft Euch einen großen Beutel zu.>\n\nUnd behaltet den Rest, dreckiges Tier!", objectives = "Begebt Euch zum Chillwind-Lager - Territorium der Allianz - und ermordet Weldon Barov. Nehmt seinen Kopf und kehrt zu Alexi Barov zurück.\n\nSeid gewarnt, Weldon wird wahrscheinlich gut von Abschaum der Allianz geschützt.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[5343] = { id = 5343, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Familienvermögen der Barovs", description = "Mein lieber Bruder Alexi. Was für ein Narr war ich doch, sein Leben zu verschonen. Ich sah dem Feind ins Gesicht, einem der Untoten, und ließ ihn am Leben.\n\n<Weldon spuckt aus.>\n\nUnd jetzt sucht er nach MEINEM Erbe. Das darf einfach nicht sein.\n\nSucht die Besitzurkunden meiner Familie, bevor sie diesem niederträchtigen Bastard in seine knochigen Hände fallen, und ich werde Euch mit großem Reichtum belohnen. Sie liegen irgendwo in den Ruinen der Scholomance. Beeilt Euch!", progress = "Sichert mir meine Zukunft und ich werde die Eure sichern.", completion = "Es gibt nur noch eine weitere Aufgabe, die Ihr für mich erledigen müsst, {name}.", objectives = "Begebt Euch zur Scholomance und holt das Familienvermögen der Barovs zurück. Dieses Vermögen besteht aus vier Besitzurkunden: Es sind die Besitzurkunde für Caer Darrow, die Besitzurkunde für Brill, die Besitzurkunde für Tarrens Mühle und die Besitzurkunde für Southshore. Kehrt zu Weldon Barov zurück, sobald die Aufgabe erledigt ist.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[5344] = { id = 5344, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der letzte Barov", description = "Da die Besitzurkunden beschafft sind, bleibt nur noch eine Sache zu tun. Alexi muss getötet werden. Wenn er tot ist, brauche ich nicht mehr zu fürchten, dass eine skrupellose Bande von Söldnern meinen Kopf haben will.\n\nDie Aufgabe ist einfach. Alexi versteckt sich unter dem Schutz der Horde - beim Bollwerk.\n\nNein, ich erwarte nicht, dass Ihr einfach nur hingeht und ihn tötet, ich will seinen Kopf! Wie Ihr ihn bekommt ... tja, dieser Part ist Euch überlassen. Ein derartiges Verhalten ist einem von meiner edlen Erziehung nicht würdig..", progress = "Ihr wollt Eure Bezahlung, was?", completion = "Das ist ein glorreicher Tag! Endlich wurde der Schandfleck des Hauses Barov eliminiert und mein Vermögen gesichert!\n\nNehmt dies und geht mir aus den Augen... Wurm.", objectives = "Begebt Euch zum Bollwerk - Territorium der Horde - und ermordet Alexi Barov. Nehmt seinen Kopf und kehrt zu Weldon Barov zurück.\n\nSeid gewarnt, Alexi wird wahrscheinlich gut durch Abschaum der Horde geschützt.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[5361] = { id = 5361, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stammbaum", description = "Mein Bruder Nataka ist beim Geistwandlerposten drüben in Desolace stationiert. Also, worum ich Euch bitten möchte, ist... könntet Ihr ihm diesen Bericht von mir geben? Ein Jahr ist vergangen, seit ich ihm das letzte Mal schrieb, und es gab seitdem ungewöhnliche Zentaurenaktivitäten, über die er informiert werden sollte.\n\nReist zum Steinkrallengebirge nördlich von Crossroads und dann westlich zum verbrannten Tal. Begebt Euch von dort aus südlich nach Desolace; dort findet Ihr eine Straße, die gen Süden zum Geistwandlerposten führt.", progress = "Welche Neuigkeiten habt Ihr, {class}? Ah - eine Nachricht von meinem Bruder, sagt Ihr? Nun dann, gebt den Bericht her!", completion = "Ich weiß nicht, in welcher Beziehung Ihr zu meinem Bruder steht, aber es sieht so aus, als würde er Euch vertrauen, {class}.\n\nIch bin Nataka Longhorn und möchte Euch im Geistwandlerposten willkommen heißen. Wir können Leute wie Euch hier gut brauchen, {class}! Sprecht mit anderen, vielleicht braucht man hier Eure Hilfe.", objectives = "Bringt den Bericht von Klippenbehüter Longhorn zu Nataka Longhorn am Geistwandlerposten in Desolace.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[5381] = { id = 5381, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hand von Iruxos", description = "Die Burning Blade besitzen den Dämonenkasten. Darin liegt die mächtige Hand von Iruxos. Die Burning Nlade verwenden sie, um dämonische Portale in Mannorocs Koven zu öffnen. Wir müssen die Flut der Dämonen stoppen, die in unsere Welt eindringt, {name}!\n\nWendet diese Dämonenhacke auf den roten Kristall in der Festung Thunder Axe an, um Zugang zu dem Dämonenkasten zu erlangen.", progress = "{name}, habt Ihr den Dämonenkasten?", completion = "Ah, der Dämonenkasten. Gebt ihn mir, {class}, und ich werde ihn öffnen... und Euch damit die Hand von Iruxos offenbaren.", objectives = "Holt den Dämonenkasten aus der Festung Thunder Axe und kehrt damit zu Taiga Wisemane nach Shadowprey zurück.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[5382] = { id = 5382, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Doktor Theolen Krastinov, der Schlächter", description = "Krastinov ist für den Tod von Tausenden verantwortlich. Er muss bestraft werden, die Gerechtigkeit muss ihren Lauf nehmen.\n\nSucht ihn und bringt jene Qual über ihn, die er über zahllose Unschuldige gebracht hat. Wenn er vernichtet ist, verbrennt unsere Überreste. Verwandelt sie in Asche, {name}.", progress = "Der Schlächter muss aufgehalten werden!", completion = "Ich fühle, wie mein Geist heilt, {name}. Ihr habt meinem Ehemann und mir einen großen Dienst erwiesen, aber ich bin sicher, dass es noch mehr zu tun gibt.", objectives = "Sucht Doktor Theolen Krastinov in der Scholomance. Vernichtet ihn, verbrennt dann die Überreste von Eva Sarkhoff und die Überreste von Lucien Sarkhoff. Kehrt zu Eva Sarkhoff zurück, sobald Ihr die Aufgabe erfüllt habt.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[5383] = { id = 5383, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Krastinovs Tasche der Schrecken", description = "Ihr öffnet die Tasche und entdeckt darin verschiedene Folterinstrumente. Unter dem Zubehör fällt Euch ein merkwürdiges Objekt ins Auge. Eine Phiole mit Blut - noch immer warm.\n\nIhr denkt, dass die Sarkhoffs an Eurer Entdeckung interessiert sein könnten.", sourceObjective = "Bringt die Tasche der Schrecken zu Eva Sarkhoff in Darrowehr.\n\nBereitgestellter Gegenstand:", sourceObjectiveStatus = "unverified-source-field" }
quests[5384] = { id = 5384, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kirtonos der Herold", description = "Das ist es, {name}.\n\n<Eva zeigt auf die Phiole in der Tasche.>\n\nDas Blut von Unschuldigen. Das reinste Blut... damit wird Krastinovs Meister besänftigt.\n\nMit diesem Blut kann Kirtonos beschworen werden. Mit diesem Blut muss Kirtonos auch vernichtet werden.\n\nBringt dieses Blut auf die Veranda. Legt es auf die Kohlenpfanne. Kirtonos wird kommen - er kann nicht widerstehen. Wenn er erscheint, entfesselt die Wut und den Zorn von Tausenden unschuldigen Toten über ihm.\n\nWenn Ihr erfolgreich seid, werdet Ihr mehr verdienen als nur unsere Dankbarkeit.", progress = "Seid vorsichtig, Kirtonos ist ein erfahrener Kämpfer.", completion = "Mit dem Tod von Kirtonos wird ein Kapitel in der schrecklichen Geschichte der Scholomance geschlossen. Aber es gibt noch mehr zu tun. Andere hier sind sich jetzt Eurer mutigen Taten bewusst. Nehmt das, {name}. Es ist ein Stück unserer eigenen Essenz. Sie ermöglicht Euch, mit den anderen verlorenen Seelen von Caer Darrow zu kommunizieren.", objectives = "Kehrt mit dem Blut Unschuldiger zur Scholomance zurück. Sucht die Veranda und legt das Blut der Unschuldigen in die Kohlenpfanne. Kirtonos wird kommen, um sich von Eurer Seele zu nähren.\n\nKämpft tapfer, gebt keinen Fußbreit nach! Vernichtet Kirtonos und kehrt zu Eva Sarkhoff zurück.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[5385] = { id = 5385, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Überreste von Trey Lightforge", description = "Ihr hebt den Sack vorsichtig auf und macht Euch auf den Rückweg zu Jessir Moonbow an der Grenze des Teufelswaldes und Ashenvale. Hoffentlich wird dem Paladin der ihm zustehende Respekt erwiesen, wenn Ihr seine Überreste seinen Freunden übergeben habt.", progress = "Wie lief es in Jaedenar, {name}?", completion = "Ihr habt es geschafft! Gelobt sei Elune und welche Mächte auch immer Ihr anbetet, {name}. Ihr habt heute etwas Ehrenwertes und Großmütiges getan. Ich bin sicher, dass Arko'narin erfreut sein wird, dass Ihr Euch nicht nur die Zeit genommen habt, sie zu retten, sondern auch die Kreatur zu erledigen, die einen ihrer besten Freunde gefoltert hat.\n\nIch wünschte, ich könnte mehr für Euch tun, aber bitte, nehmt dies.", objectives = "Bringt die Überreste von Trey Lightforge zu Jessir Moonbow im Teufelswald.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[5386] = { id = 5386, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Fang des Tages", description = "Der Geruch von gekochtem Fisch ist hier im Geistwandlerposten schon längst verschwunden. Die Trolle von Shadowprey sind die Besten, wenn es um das Fangen von Fischen geht... aber leider habe ich aufgrund all der Zentaurenaktivitäten nicht genug Zeit, um eine Reise zu den Trollen zu unternehmen. Hm...\n\nTut mir einen Gefallen und reist nach Shadowprey. Sprecht mit dem dortigen Angler Jinar'Zillen und bringt mir mein Leibgericht, Blutbauchfisch. Die Straße südlich von hier bringt Euch nach Westen zu dem Trolldorf.", progress = "Mein Huf prickelt und mir läuft das Wasser im Mund zusammen, wenn ich an gebratenen Blutbauchfisch denke... Habt Ihr welchen dabei?", completion = "Ihr seid ein Retter, {name}! Diese Blutbauchfische sehen fast gut genug aus, um sie roh zu essen.\n\n\n\nHier, bitteschön. Wählt einen dieser Gegenstände als Bezahlung für diese Fische aus.", objectives = "Sprecht mit Jinar'Zillen in Shadowprey und bringt Nataka Longhorn dann 2 Blutbauchfische.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[5401] = { id = 5401, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Anstecknadel der Argentumdämmerung", sourceObjective = "Alle, die für die Argentumdämmerung das Böse bekämpfen, müssen unsere Anstecknadel tragen. Wenn Ihr eine solche tragt, erhaltet Ihr das Recht, Belohnungen in Anspruch zu nehmen, die unsere Rüstmeister anzubieten haben.\n\nWährend Ihr die Nadel tragt, könnt Ihr Euch Geißelsteine von erschlagenen Mitgliedern der Geißel holen; das sind Insignien, die sie manchmal besitzen. Beschafft Euch diese Insignien und bringt sie mir. Für alle, die Ihr abgebt, erhaltet Ihr unsere Marke des Heldentums - die Ehrenmarke der Argentumdämmerung.\n\nErfüllt Euer Schicksal, {class}... stürzt Euch noch heute in den Kampf!", sourceObjectiveStatus = "unverified-source-field" }
quests[5402] = { id = 5402, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geißelsteine des Dieners", progress = "Der Geißelstein des Dieners ist die Insignie des Fußvolkes der Geißel. Man findet sie manchmal bei den schwächeren Truppen, die in den Pestländern stationiert sind, obwohl der Begriff 'schwächere' natürlich relativ betrachtet werden muss. Die Geißel sollte, ganz gleich wo sie sich befindet, niemals unterschätzt werden.\n\nDie Argentumdämmerung bietet derzeit eine Ehrenmarke im Tausch für zwanzig dieser Insignien - ein Tausch, den ich freudig ausführe, vorausgesetzt, Ihr habt genug Geißelsteine!", completion = "Glückwunsch, {name}... ich bin erfreut, Euch mit einer Ehrenmarke der Argentumdämmerung zu belohnen!\n\nDie Marken dienen zwei Zwecken. Erstens können sie verwendet werden, um Euren Stand innerhalb der Argentumdämmerung zu fördern; das könnte Euch zu Möglichkeiten und Belohnungen verhelfen, die unseren geehrten und geachteten Verbündeten vorbehalten sind. Zweitens könnt Ihr sie, zusammen mit Münzen, an unsere Rüstmeister weitergeben, als Bezahlung für einige der kostspieligeren Gegenstände der Dämmerung.\n\nWozu Ihr Euch auch entscheidet, wisset, dass Ihr Euch Eure Anstecknadel verdient. Gut gemacht!" }
quests[5403] = { id = 5403, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geißelsteine des Eindringlings", progress = "Der Geißelstein des Eindringlings ist die Insignie der Elitetruppen der Geißel. Man findet sie manchmal bei den stärkeren Truppen, die in den Pestländern stationiert sind. Das Erschlagen einer solchen Kreatur ist wahrlich eine Herausforderung, aber eine, die jemand, der sich den Sieg über das Böse auf die Fahne geschrieben hat, mit Freude erfüllen sollte.\n\nDie Argentumdämmerung bietet derzeit eine Ehrenmarke im Tausch für zehn dieser Insignien. Bringt sie mir und ich werde sicherstellen, dass Ihr Eure gerechte Belohnung erhaltet.", completion = "Glückwunsch, {name}... ich bin erfreut, Euch mit einer Ehrenmarke der Argentumdämmerung zu belohnen!\n\nJede Ehrenmarke, die an einen würdigen Empfänger vergeben wird, ist ein Zeichen, dass sich das Schicksal gegen die Geißel wendet. Da mehr und mehr Helden die Geißel in ihren eigenen Ländern bekämpfen, wird die Argentumdämmerung sicherlich in erster Reihe stehen, wenn die Zeit kommt, Krieg über das ultimative Böse der Geißel zu bringen. Ich hoffe, dass der Mut, den Ihr gezeigt habt, um Eure Marke zu erlangen, auch dann den Sieg davontragen wird!" }
quests[5404] = { id = 5404, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geißelsteine des Verderbers", sourceObjective = "Der Geißelstein des Verderbers ist die Insignie der Oberanführer der Geißel. Ein mächtiges Wesen, das eine Autoritätsposition über der Geißel innehat, wird immer einen besitzen. Eine solch bösartige Kreatur zu erschlagen, würde die Sache der Argentumdämmerung und alle guten Sachen sicherlich voranbringen!\n\nIm Namen der Argentumdämmerung werde ich Euch eine Ehrenmarke im Tausch für jeweils eine dieser Insignien geben. Seid vorsichtig, wenn Ihr diese Insignien holt, {name}... mit solch mächtigen Wesen ist nicht zu spaßen.", progress = "Der Geißelstein des Verderbers ist die Insignie der Oberanführer der Geißel. Ein mächtiges Wesen, das eine Autoritätsposition über der Geißel innehat, wird immer einen besitzen. Eine solch bösartige Kreatur zu erschlagen, würde die Sache der Argentumdämmerung und alle guten Sachen sicherlich voranbringen!\n\nIm Namen der Argentumdämmerung werde ich Euch eine Ehrenmarke im Tausch für jeweils eine dieser Insignien geben. Seid vorsichtig, wenn Ihr diese Insignien holt, {name} ... mit solch mächtigen Wesen ist nicht zu spaßen.", completion = "Glückwunsch, {name}... ich bin erfreut, Euch mit einer Ehrenmarke der Argentumdämmerung zu belohnen!\n\nAuf solche Art eine Ehrenmarke zu erhalten, zeigt, dass Ihr ein wahrer Held der Sache des Guten seid. Wir schätzen alle Bemühungen, die gegen die Geißel aufgebracht werden, aber einen ihrer Anführer auszuschalten, bedeutet wahrlich, ihnen eine vernichtende Niederlage beizubringen!\n\nFür die Dämmerung, mein Bruder.", sourceObjectiveStatus = "unverified-source-field" }
quests[5405] = { id = 5405, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Anstecknadel der Argentumdämmerung", sourceObjective = "Alle, die für die Argentumdämmerung das Böse bekämpfen, müssen unsere Anstecknadel tragen. Wenn Ihr eine solche tragt, erhaltet Ihr das Recht, Belohnungen in Anspruch zu nehmen, die unsere Rüstmeister anzubieten haben.\n\nWährend Ihr die Nadel tragt, könnt Ihr Euch Geißelsteine von erschlagenen Mitgliedern der Geißel holen; das sind Insignien, die sie manchmal besitzen. Beschafft Euch diese Insignien und bringt sie mir. Für alle, die Ihr abgebt, erhaltet Ihr unsere Marke des Heldentums - die Ehrenmarke der Argentumdämmerung.\n\nErfüllt Euer Schicksal, {class}... stürzt Euch noch heute in den Kampf!", sourceObjectiveStatus = "unverified-source-field" }
quests[5406] = { id = 5406, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geißelsteine des Verderbers", sourceObjective = "Der Geißelstein des Verderbers ist die Insignie der Oberanführer der Geißel. Ein mächtiges Wesen, das eine Autoritätsposition über der Geißel innehat, wird immer einen besitzen. Eine solch bösartige Kreatur zu erschlagen, würde die Sache der Argentumdämmerung und alle guten Sachen sicherlich voranbringen!\n\nIm Namen der Argentumdämmerung werde ich Euch eine Ehrenmarke im Tausch für jeweils eine dieser Insignien geben. Seid vorsichtig, wenn Ihr diese Insignien holt, {name}... mit solch mächtigen Wesen ist nicht zu spaßen.", progress = "Der Geißelstein des Verderbers ist die Insignie der Oberanführer der Geißel. Ein mächtiges Wesen, das eine Autoritätsposition über der Geißel innehat, wird immer einen besitzen. Eine solch bösartige Kreatur zu erschlagen, würde die Sache der Argentumdämmerung und alle guten Sachen sicherlich voranbringen!\n\nIm Namen der Argentumdämmerung werde ich Euch eine Ehrenmarke im Tausch für jeweils eine dieser Insignien geben. Seid vorsichtig, wenn Ihr diese Insignien holt, {name} ... mit solch mächtigen Wesen ist nicht zu spaßen.", completion = "Glückwunsch, {name}... ich bin erfreut, Euch mit einer Ehrenmarke der Argentumdämmerung zu belohnen!\n\nAuf solche Art eine Ehrenmarke zu erhalten, zeigt, dass Ihr ein wahrer Held der Sache des Guten seid. Wir schätzen alle Bemühungen, die gegen die Geißel aufgebracht werden, aber einen ihrer Anführer auszuschalten, bedeutet wahrlich, ihnen eine vernichtende Niederlage beizubringen!\n\nFür die Dämmerung, mein Bruder.", sourceObjectiveStatus = "unverified-source-field" }
quests[5407] = { id = 5407, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geißelsteine des Eindringlings", progress = "Der Geißelstein des Eindringlings ist die Insignie der Elitetruppen der Geißel. Man findet sie manchmal bei den stärkeren Truppen, die in den Pestländern stationiert sind. Das Erschlagen einer solchen Kreatur ist wahrlich eine Herausforderung, aber eine, die jemand, der sich den Sieg über das Böse auf die Fahne geschrieben hat, mit Freude erfüllen sollte.\n\nDie Argentumdämmerung bietet derzeit eine Ehrenmarke im Tausch für zehn dieser Insignien. Bringt sie mir und ich werde sicherstellen, dass Ihr Eure gerechte Belohnung erhaltet.", completion = "Glückwunsch, {name}... ich bin erfreut, Euch mit einer Ehrenmarke der Argentumdämmerung zu belohnen!\n\nJede Ehrenmarke, die an einen würdigen Empfänger vergeben wird, ist ein Zeichen, dass sich das Schicksal gegen die Geißel wendet. Da mehr und mehr Helden die Geißel in ihren eigenen Ländern bekämpfen, wird die Argentumdämmerung sicherlich in erster Reihe stehen, wenn die Zeit kommt, Krieg über das ultimative Böse der Geißel zu bringen. Ich hoffe, dass der Mut, den Ihr gezeigt habt, um Eure Marke zu erlangen, auch dann den Sieg davontragen wird!" }
quests[5408] = { id = 5408, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geißelsteine des Dieners", progress = "Der Geißelstein des Dieners ist die Insignie des Fußvolkes der Geißel. Man findet sie manchmal bei den schwächeren Truppen, die in den Pestländern stationiert sind, obwohl der Begriff 'schwächere' natürlich relativ betrachtet werden muss. Die Geißel sollte, ganz gleich wo sie sich befindet, niemals unterschätzt werden.\n\nDie Argentumdämmerung bietet derzeit eine Ehrenmarke im Tausch für zwanzig dieser Insignien - ein Tausch, den ich freudig ausführe, vorausgesetzt, Ihr habt genug Geißelsteine!", completion = "Glückwunsch, {name}... ich bin erfreut, Euch mit einer Ehrenmarke der Argentumdämmerung zu belohnen!\n\nDie Marken dienen zwei Zwecken. Erstens können sie verwendet werden, um Euren Stand innerhalb der Argentumdämmerung zu fördern; das könnte Euch zu Möglichkeiten und Belohnungen verhelfen, die unseren geehrten und geachteten Verbündeten vorbehalten sind. Zweitens könnt Ihr sie, zusammen mit Münzen, an unsere Rüstmeister weitergeben, als Bezahlung für einige der kostspieligeren Gegenstände der Dämmerung.\n\nWozu Ihr Euch auch entscheidet, wisset, dass Ihr Euch Eure Anstecknadel verdient. Gut gemacht!" }
quests[5421] = { id = 5421, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fisch im Eimer", progress = "Ich werde jeden belohnen, der mein Leben ein bisschen einfacher macht... Ich genieße es, so wenig wie möglich zu tun, Mann!\n\nUnter den Docks hier in Shadowprey habe ich viele Schalentierfallen. Wenn Ihr so freundlich wärt, meine Arbeit zu tun und meine Schalentiere einzusammeln, dann werde ich Euch mit etwas belohnen, das Ihr wollt... Ihr wisst schon, was ich meine, eh? Für jeweils fünf Schalentiere, die Ihr mir bringt, gebe ich Euch einen feinen Blutbauchfisch!", completion = "Echt toll, nichts ist besser als getane Arbeit, vor allem, wenn sie jemand anderes getan hat... eh?" }
quests[5441] = { id = 5441, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Faule Peons", description = "Verfluchte Peons! Sie arbeiten ja hart daran, Holz aus den Bäumen im Tal zu gewinnen, aber sie machen ständig Nickerchen! Ich brauche jemanden, der dabei hilft, die Peons auf Zack zu halten.\n\nIhr seht wie geschaffen für meinen Auftrag aus, {race}. Hier, Ihr nehmt jetzt diesen Totschläger und lasst ihn auf allen faulen Peons tanzen, die Ihr bei der Arbeit schlafend vorfindet. Ein ordentlicher Schlag wird sie schnell wieder an die Arbeit bringen! Bringt mir den Totschläger wieder, wenn Ihr fertig seid.\n\nVerdammte faule Peons ...", progress = "Verdammter fauler B...\n\n Huch? Habt Ihr meinen Totschläger? Habt Ihr Peons dabei erwischt, wie sie bei der Arbeit schliefen?!", completion = "Gut, gut. Vielleicht werden sie es sich in Zukunft zweimal überlegen, bevor sie wieder nachlässig werden! Ich danke Euch für Eure Hilfe!", objectives = "Benutzt den Totschläger des Großknechts an faulen Peons, wenn sie schlafen. Weckt 5 Peons auf und bringt dann den Totschläger des Großknechts zu Großknecht Thazz'ril ins Tal der Prüfungen zurück.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[5461] = { id = 5461, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Mensch Ras Frostraunen", description = "Die Untoten fürchten das Leben genauso sehr wie die Lebenden den Tod fürchten. Es ist nicht ungewöhnlich, dass ein denkender Untoter alle Überreste seines vorherigen Lebens vollständig zerstört, nachdem er zum Untoten wurde.\n\nLeider benötigen wir, um ein Artefakt zu erschaffen, das Ras Frostraunen wieder in einen Sterblichen zurückverwandeln kann, ein Andenken aus seinen Jahren unter den Lebenden.\n\nIhr müsst Euch zur zerstörten Stadt von Stromgarde begeben, Frostraunens Heim, und nach solch einem Gegenstand suchen. Möge das Glück mit Euch sein, {name}.", progress = "Ein Andenken der Erinnerung ist ein seltener Fund, {name}.", completion = "Ich hatte bezweifelt, dass solch ein Gegendstand existieren könnte. Das eröffnet uns definitiv eine unglaubliche Gelegenheit - eine, die wir nicht vergeuden dürfen.\n\nMacht Euch fertig, {name}, denn das, worum ich Euch bitten werde, wird Euch in die Tiefen der Hölle führen.", objectives = "Reist in das Arathihochland zu den Ruinen von Stromgarde. Durchsucht Stromgarde nach einem Andenken der Erinnerung. Wenn Ihr einen solchen Gegenstand findet, kehrt mit ihm zu Magistrat Marduke zurück.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[5462] = { id = 5462, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Sterbende Ras Frostraunen", description = "Das Andenken muss auf besudeltem Boden korrekt eingestellt werden.\n\nMan erzählt sich, dass Stratholme der Ort sei, an dem Frostraunen dem Lichkönig erlag. Auf diesem blutigen Boden gab er sein Leben - frei und mit einem Motiv -, um einer der Unsterbenden zu werden.\n\nDieser Ort muss gefunden werden.\n\nEs gibt einen untoten Dissidenten der Geißel, der durch die Bansheekönigin befreit wurde, aber der Sache der Argentumdämmerung gegenüber loyal ist. Sucht ihn: Leonid Barthalomew der Geachtete. Er könnte mehr wissen. Sucht die Hoffnung des Lichts auf, {name}.", progress = "Stellt keine Fragen, auf die Ihr keine Antworten wollt.", completion = "<Leonid sieht sich das Andenken an.>\n\nEuer Problem weckt Erinnerungen, von denen ich gehofft hatte, dass sie nie wieder an die Oberfläche kommen würden.", objectives = "Reist zur Hoffnung des Lichts in den Östlichen Pestländern und sucht Leonid Barthalomew den Geachteten auf. Zeigt ihm das Andenken der Erinnerung und berichtet ihm alles, was Ihr entdeckt habt.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[5463] = { id = 5463, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Menethils Geschenk", description = "Ich sah zu, wie der Mensch Ras Frostraunen seine unsterbliche Seele dem Lichkönig verpfändete. Er setzte den Dolch an seiner eigenen Kehle an und durchschnitt sie mit einem Lächeln von einem Ohr zum anderen. Sein Körper brach in den Grenzen des Pentagramms zusammen. Der Lichkönig stand über dem gefallenen Magier, und mit einer einzigen Bewegung wurde Ras Frostraunen der Lich geboren.\n\n<Leonid blickt zu Boden und sieht Euch dann an.>\n\nJa, {race}, ich erinnere mich. Was Ihr sucht, hat einen Namen - Menethils Geschenk: Der vom Lichkönig gesegnete Boden - heiliger Boden für die Geißel.", progress = "Der Bereich um Menethils Geschenk herum ist außergewöhnlich kalt.", completion = "Ihr platziert das Andenken auf dem besudelten Boden.", objectives = "Begebt Euch nach Stratholme und sucht Menethils Geschenk. Platziert das Andenken der Erinnerung auf dem unheiligen Boden.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[5464] = { id = 5464, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Menethils Geschenk", description = "Die Seele des Gefallenen hängt sich an das, was sein ehemaliges Leben repräsentiert, und verwandelt den Gegenstand in ein seelengebundenes Andenken. Ihr hebt den Gegenstand auf und verstaut ihn in Eurem Rucksack.", progress = "<Leonid erschauert.>", completion = "Wie die Seele an dem Andenken hing, so soll sie an der physischen Gestalt von Ras Frostraunen hängen.", objectives = "Bringt das seelengebundene Andenken zu Leonid Barthalomew in den Östlichen Pestländern.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[5465] = { id = 5465, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seelengebundenes Andenken", description = "Kehrt mit dem Andenken zu Marduke zurück, {name}. Er wird Euch über die Anwendung instruieren.", progress = "Habt Ihr das Unmögliche getan?", completion = "Ich war sicher, dass Ihr mir als ein weiterer unglückseliger Geist Gesellschaft leisten würdet.", objectives = "Kehrt zu Magistrat Marduke in Caer Darrow zurück. Zeigt ihm das seelengebundene Andenken.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[5466] = { id = 5466, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Lich Ras Frostraunen", description = "Es verbleibt noch eine Aufgabe, {name}. Tretet dem Lich Ras Frostraunen in seinem Unterschlupf gegenüber.\n\nBenutzt die Macht des Andenkens gegen die Bestie - seid unerbittlich in Euren Taten! Haltet den Schlägen stand, mit denen das um sich schlagende Biest Euch sicherlich eindecken wird. Gebt dem Schmerz nicht nach!\n\nWenn das Ritual abgeschlossen ist, wird Ras wieder ein Sterblicher sein. An diesem Punkt muss er getötet werden. Schlagt ihn nieder und nehmt Euch seinen menschlichen Kopf.", progress = "Ihr tragt die Bürde von Zehntausenden ruheloser Seelen, {name}.", completion = "Zehntausende Seele schreien wie eine auf, {name}! Ihr habt der Geißel und ihren Meistern einen tödlichen Schlag versetzt.", objectives = "Sucht Ras Frostraunen in der Scholomance. Wenn Ihr ihn gefunden habt, wendet das seelengebundene Andenken auf sein untotes Antlitz an. Solltet Ihr ihn erfolgreich in einen Sterblichen zurückverwandeln können, dann schlagt ihn nieder und nehmt den menschlichen Kopf von Ras Frostraunen an Euch. Bringt den Kopf zu Magistrat Marduke.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[5481] = { id = 5481, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gordos Aufgabe", description = "Meister will Kräuter. Wir große Hände haben und nicht gut greifen können. Ihr uns helfen und wir Euch nicht wehtun. Wir Düsterkraut brauchen. Viele Kräuter hier und bei Straße.\n\nWenn Ihr Düsterkraut haben, Ihr bringen zu Meister Holland auf Brill-Friedhof.", progress = "Wo ist diese nutzlose Monstrosität? Entweder habt Ihr, was ich benötige, oder Ihr verschwindet besser von hier und sucht es.", completion = "Was ist denn das? Düsterkraut?! Ich brauche kein Düsterkraut! Diese hirnlose Fleischmasse pflückt da draußen Gänseblümchen und bringt Gott weiß wie viele Tölpel wie Euch dazu, das Gleiche zu tun. Das sollte keine Beleidigung sein.\n\nNun denn, Ihr seid jetzt hier und das ist das einzig Wichtige. Da ich keine Zeit darauf verschwenden werde, dieser Monstrosität alles noch mal zu erklären, wie wäre es, wenn Ihr das sammelt, was ich wirklich benötige ... Verdammniskraut.", objectives = "Sammelt 3 Düsterkräuter und bringt sie zu Jungapotheker Holland auf den Brill-Friedhof.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[5482] = { id = 5482, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verdammniskraut", description = "Ihr seht also die Zwickmühle, in der ich mich befinde, {name}. Dieses Ding da draußen sammelt die falschen Kräuter! Ich werde Euch dafür belohnen, wenn Ihr sammelt, was ich wirklich benötige. Bringt mir genug Verdammniskraut und ich werde Euch eine angemessene Belohnung geben.\n\nSoweit mir bekannt ist, verseucht es gern die Flora in der Nähe des Massengrabs, nördlich des Friedhofes von Brill. Beeilt Euch und hütet Euch vor den Gnollen in dem Gebiet.", progress = "Hoffentlich ist das wichtig... Ich gehe davon aus, dass Ihr das benötigte Verdammniskraut habt?", completion = "Ah, mein Verdammniskraut. Exzellent!\n\n<Jungapotheker Holland reibt gierig seine Hände aneinander.>\n\nDas passt perfekt. Ihr habt mir, äh, der Fürstin heute einen großen Dienst erwiesen, {name}. Wie versprochen ist hier die Belohnung, die Ihr verdient.", objectives = "Sammelt 10 Verdammniskräuter und bringt sie zu Jungapotheker Holland.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[5501] = { id = 5501, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Knochensammler", description = "Wir sitzen hier auf einer Goldmine, ich sage Euch - einer Goldmine! Kodoknochen werden die Welt für immer verändern... Ich habe Kunden, die daraus Möbel, Musikinstrumente und sogar Sprengpulver herstellen.\n\nEine Karawane kommt hier vorbei, die meine Kodoknochen mitnimmt und sie dann in Shadowprey verkauft. Wenn Ihr zum Kodofriedhof südlich von hier gehen und mir zehn Kodoknochen bringen könntet, würde ich Euch dafür etwas anderes geben. Ist das ein Geschäft?", progress = "Habt Ihr die Knochen? Die Karawane wird jeden Moment hier sein. Ich benötige nur noch zehn weitere Kodoknochen, um den Gipfel meiner Karriere zu erreichen. Den Gipfel meiner Karriere, sage ich Euch!", completion = "Ah, prima! Meine Knochen!\n\nIch kann es kaum abwarten, dass die Jungs zuhause mein Gesicht auf dem Titel von Goblin'preneur sehen. Ich werde der reichste Goblin auf der Welt sein... und mein Sportlehrer hat immer gesagt, aus mir würde nie was werden.", objectives = "Bringt Bibbly F'utzbuckle bei Kormeks Hütte 10 Kodoknochen vom Kodofriedhof.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[5502] = { id = 5502, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tageseltern der Horde", description = "Ihr wart die ganze Zeit so gut zu mir, {name}. Nie hätte ich erwartet während der Kinderwoche soviel Spaß zu haben! Danke schön. Ich versuche über das, was mir und den anderen passiert ist nicht traurig zu sein - meine Eltern sagten immer, ich müsse über allem Bösen stehen, dass in der Welt passiert. Weißt du was? Wenn ich groß bin, möchte ich genauso ein Held sein wie Ihr!\n\nEs macht mich zwar traurig, aber leider muss ich jetzt nach Hause gehen. Lass uns zur Matrone zurückgehen und ihr erzählen, was für ein wunderbarer Mensch du bist!", sourceObjective = "Bringt Euren Schützling in das Waisenhaus von Ogrimmar zurück, indem Ihr die Pfeife des orcischen Waisenkindes an Waisenmatrone Battlewail im Tal der Ehre übergebt.", progress = "Es ist schön Euch wiederzusehen, {name}. Habt Ihr die Euch auferlegten Pflichten, für die Ihr Euch während der Kinderwoche freiwillig gemeldet habt, sorgfältig erfüllt?", completion = "Mögen die Geister Euch segnen, {name}. Ihr habt für Grunz mehr getan, als es jemand anderem je in den Sinn käme. Vielen Dank - Ihr seid der Inbegriff eines Helden der Horde.\n\nBitte besucht uns mal wieder, wenn Ihr etwas Zeit habt. Ich weiß, dass Grunz sich sehr freuen würde, genauso wie ich.\n\nGrunz hatte so viel Spaß mit Euch, {name}. Er hat mich gebeten Euch eines seiner Lieblingstierchen zu geben, damit Ihr Euch stets an ihn erinnert.", sourceObjectiveStatus = "unverified-source-field" }
quests[5503] = { id = 5503, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Anstecknadel der Argentumdämmerung", sourceObjective = "Alle, die für die Argentumdämmerung das Böse bekämpfen, müssen unsere Anstecknadel tragen. Wenn Ihr eine solche tragt, erhaltet Ihr das Recht, Belohnungen in Anspruch zu nehmen, die unsere Rüstmeister anzubieten haben.\n\nWährend Ihr die Nadel tragt, könnt Ihr Euch Geißelsteine von erschlagenen Mitgliedern der Geißel holen; das sind Insignien, die sie manchmal besitzen. Beschafft Euch diese Insignien und bringt sie mir. Für alle, die Ihr abgebt, erhaltet Ihr unsere Marke des Heldentums - die Ehrenmarke der Argentumdämmerung.\n\nErfüllt Euer Schicksal, {class}... stürzt Euch noch heute in den Kampf!", sourceObjectiveStatus = "unverified-source-field" }
quests[5504] = { id = 5504, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mäntel der Dämmerung", description = "Euer hervorragenden Dienste für die Argentumdämmerung haben sich herumgesprochen, {name}. Wir sind geehrt, Euch in unseren Reihen zu wissen. Ich wurde ermächtigt, Euch einige der wertvollsten Gegenstände der Dämmerung anzubieten - unsere Mäntel des Magiewiderstands.\n\n Wenn Ihr einen Mantel mit Eurer Schulterpanzerung verwendet, könnt Ihr euren Widerstand gegen die Kräfte der Magie auf eine von fünf mögliche Arten verbessern. Als Zeichen der Hingabe für unsere Sache, erbitte ich von Euch nicht weniger als zehn unserer Ehrenmarken, um Zugriff auf die Mäntel zu erhalten.", progress = "Ah, edler {class}!  Habt Ihr die Ehrenmarken um die ich Euch gebeten habe? Sobald Ihr mir die Marken übergebt, habt Ihr die Möglichkeit unsere Mäntel zu erwerben.", completion = "Hervorragend - Euer Tribut an die Argentumdämmerung wurde wohlwollend zur Kenntnis genommen, {name}. Nun, da wir dies hinter uns gebracht haben, bin ich erfreut Euch unsere Mäntel zum Erwerb anbieten zu können. Solange Ihr Euren momentanen Status mit uns aufrecht erhaltet, könnt Ihr die Mäntel der Dämmerung bei jedem bevollmächtigten Rüstmeister der Argentumdämmerung erwerben.\n\nFür die Dämmerung, Bruder!", objectives = "Bringt 10 Ehrenmarken der Argentumdämmerung zu Rüstmeister Hasana ins Bollwerk in den westlichen Pestländern.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[5505] = { id = 5505, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Schlüssel zur Scholomance", sourceObjective = "Tja, da ist er, {name}, der fertige Skelettschlüssel. Ich bin eigentlich absolut sicher, dass dieser Schlüssel Euch Zutritt zur Scholomance verschaffen wird. Es gibt aber nur eine Möglichkeit, um absolut sicher zu sein, dass er wirklich funktioniert. Verschwendet keine Zeit darauf, es auszuprobieren, sage ich.\n\nViel Glück. Möget Ihr auch weiterhin Licht in die Dunkelheit bringen!", sourceObjectiveStatus = "unverified-source-field" }
quests[5507] = { id = 5507, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mäntel der Dämmerung", description = "Euer hervorragenden Dienste für die Argentumdämmerung haben sich herumgesprochen, {name}. Wir sind geehrt, Euch in unseren Reihen zu wissen. Ich wurde ermächtigt, Euch einige der wertvollsten Gegenstände der Dämmerung anzubieten - unsere Mäntel des Magiewiderstands.\n\n Wenn Ihr einen Mantel mit Eurer Schulterpanzerung verwendet, könnt Ihr euren Widerstand gegen die Kräfte der Magie auf eine von fünf mögliche Arten verbessern. Als Zeichen der Hingabe für unsere Sache, erbitte ich von Euch nicht weniger als zehn unserer Ehrenmarken, um Zugriff auf die Mäntel zu erhalten.", progress = "Ah, edler {class}!  Habt Ihr die Ehrenmarken um die ich Euch gebeten habe? Sobald Ihr mir die Marken übergebt, habt Ihr die Möglichkeit unsere Mäntel zu erwerben.", completion = "Hervorragend - Euer Tribut an die Argentumdämmerung wurde wohlwollend zur Kenntnis genommen, {name}. Nun, da wir dies hinter uns gebracht haben, bin ich erfreut Euch unsere Mäntel zum Erwerb anbieten zu können. Solange Ihr Euren momentanen Status mit uns aufrecht erhaltet, könnt Ihr die Mäntel der Dämmerung bei jedem bevollmächtigten Rüstmeister der Argentumdämmerung erwerben.\n\nFür die Dämmerung, Bruder!", objectives = "Bringt 10 Ehrenmarken der Argentumdämmerung zu Rüstmeister Lightspark im Chillwind-Lager in den westlichen Pestländern.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[5508] = { id = 5508, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geißelsteine des Verderbers", progress = "Der Geißelstein des Verderbers ist die Insignie der Oberanführer der Geißel. Ein mächtiges Wesen, das eine Autoritätsposition über der Geißel innehat, wird immer einen besitzen. Eine solch bösartige Kreatur zu erschlagen, würde die Sache der Argentumdämmerung und alle guten Zwecke sicherlich voranbringen!\n\nIm Namen der Argentumdämmerung werde ich Euch eine Ehrenmarke im Tausch für jeweils eine dieser Insignien geben. Seid vorsichtig, wenn Ihr diese Insignien holt, {name}... mit solch mächtigen Wesen ist nicht zu spaßen.", completion = "Glückwunsch, {name}... ich bin erfreut, Euch mit einer Ehrenmarke der Argentumdämmerung zu belohnen!\n\nAuf solche Art eine Ehrenmarke zu erhalten, zeigt, dass Ihr ein wahrer Held der Sache des Guten seid. Wir schätzen alle Bemühungen, die gegen die Geißel aufgebracht werden, aber einen ihrer Anführer auszuschalten, bedeutet wahrlich, ihnen eine vernichtende Niederlage beizubringen!\n\nFür die Dämmerung, mein Bruder." }
quests[5509] = { id = 5509, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geißelsteine des Eindringlings", progress = "Der Geißelstein des Eindringlings ist die Insignie der Elitetruppen der Geißel. Man findet sie manchmal bei den stärkeren Truppen, die in den Pestländern stationiert sind. Das Erschlagen einer solchen Kreatur ist wahrlich eine Herausforderung, aber eine, die jemand, der sich den Sieg über das Böse auf die Fahne geschrieben hat, mit Freude erfüllen sollte.\n\nDie Argentumdämmerung bietet derzeit eine Ehrenmarke im Tausch für zehn dieser Insignien. Bringt sie mir und ich werde sicherstellen, dass Ihr Eure gerechte Belohnung erhaltet.", completion = "Glückwunsch, {name}... ich bin erfreut, Euch mit einer Ehrenmarke der Argentumdämmerung zu belohnen!\n\nJede Ehrenmarke, die an einen würdigen Empfänger vergeben wird, ist ein Zeichen, dass sich das Schicksal gegen die Geißel wendet. Da mehr und mehr Helden die Geißel in ihren eigenen Ländern bekämpfen, wird die Argentumdämmerung sicherlich in erster Reihe stehen, wenn die Zeit kommt, Krieg über das ultimative Böse der Geißel zu bringen. Ich hoffe, dass der Mut, den Ihr gezeigt habt, um Eure Marke zu erlangen, auch dann den Sieg davontragen wird!" }
quests[5510] = { id = 5510, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geißelsteine des Dieners", progress = "Der Geißelstein des Dieners ist die Insignie des Fußvolkes der Geißel. Man findet sie manchmal bei den schwächeren Truppen, die in den Pestländern stationiert sind, obwohl der Begriff 'schwächere' natürlich relativ betrachtet werden muss. Die Geißel sollte, ganz gleich wo sie sich befindet, niemals unterschätzt werden.\n\nDie Argentumdämmerung bietet derzeit eine Ehrenmarke im Tausch für zwanzig dieser Insignien - ein Tausch, den ich freudig ausführe, vorausgesetzt, Ihr habt genug Geißelsteine!", completion = "Glückwunsch, {name}... ich bin erfreut, Euch mit einer Ehrenmarke der Argentumdämmerung zu belohnen!\n\nDie Marken dienen zwei Zwecken. Erstens können sie verwendet werden, um Euren Stand innerhalb der Argentumdämmerung zu fördern; das könnte Euch zu Möglichkeiten und Belohnungen verhelfen, die unseren geehrten und geachteten Verbündeten vorbehalten sind. Zweitens könnt Ihr sie, zusammen mit Münzen, an unsere Rüstmeister weitergeben, als Bezahlung für einige der kostspieligeren Gegenstände der Dämmerung.\n\nWozu Ihr Euch auch entscheidet, wisset, dass Ihr Euch Eure Anstecknadel verdient. Gut gemacht!" }
